window.HS_DATA={"grades":["高一","高二","高三一轮","高三二轮"],"byGrade":{"高一":[{"id":"sy-g1-c1","name":"集合与常用逻辑用语","book":"必修第一册","grade":"高一","lessons":[{"id":"sy-g1-c1-l1","name":"1.1 集合的概念与表示","chapterId":"sy-g1-c1","chapterName":"集合与常用逻辑用语","book":"必修第一册","grade":"高一","video":"https://2119944279174578176.app.workbuddy.host/videos/sy-g1-c1-l1.mp4?sharecode=IVGNI3FZYP","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"下列各组对象能组成集合的是","options":["所有的正三角形","著名的数学家","很漂亮的花","很大的数"],"answer":0,"analysis":"集合的元素须确定；\"著名\"\"漂亮\"\"很大\"都无明确标准。","id":"sy-g1-c1-l1-q1"},{"type":"choice","level":"基础","stem":"方程 x²−1=0 的解集用列举法表示为","options":["{−1,1}","{1}","{−1}","∅"],"answer":0,"analysis":"两根 −1 与 1 都要写出。","id":"sy-g1-c1-l1-q2"},{"type":"fill","level":"中档","stem":"若 1∈{a, a²}，则 a=____","answer":"−1","analysis":"a=1 时元素重复不满足互异性；a²=1 得 a=±1，排除 a=1，故 a=−1。","id":"sy-g1-c1-l1-q3"},{"type":"fill","level":"中档","stem":"全集 U={1,2,3,4}，A={1,3}，则 ∁ᵤA=____","answer":"{2,4}","analysis":"补集为 U 中不属于 A 的元素。","id":"sy-g1-c1-l2-q3"},{"id":"sy-g1-c1-l1-e1","type":"essay","level":"简答","stem":"简答：判断下列对象能否构成集合，并说明理由：(1) 本班身高超过 1.7 米的同学；(2) 本班个子高的同学。","ref":"(1) 能，\"身高超过 1.7 米\"标准明确、元素确定；(2) 不能，\"个子高\"没有明确标准，元素不确定。"},{"id":"sy-g1-c1-l1-e2","type":"essay","level":"简答","stem":"简答：用描述法表示不等式 2x−1>3 的解集，并说明列举法与描述法各自的适用情形。","ref":"解集为 {x|x>2}。列举法适合元素个数少且有限（如有限集合）；描述法适合元素较多或有共同特征的集合（如无限集、区间型集合）。"}]},{"id":"sy-g1-c1-l2","name":"1.2 集合间的基本关系与运算","chapterId":"sy-g1-c1","chapterName":"集合与常用逻辑用语","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"A={1,2}，B={2,3}，则 A∩B=","options":["{2}","{1,2}","{2,3}","{1,2,3}"],"answer":0,"analysis":"交集只保留公共元素 2。","id":"sy-g1-c1-l2-q1"},{"type":"choice","level":"基础","stem":"A={1,2}，B={2,3}，则 A∪B=","options":["{2}","{1,2,3}","{1,3}","{1,2}"],"answer":1,"analysis":"并集合并去重，得 {1,2,3}。","id":"sy-g1-c1-l2-q2"},{"type":"fill","level":"中档","stem":"全集 U={1,2,3,4}，A={1,3}，则 ∁ᵤA=____","answer":"{2,4}","analysis":"补集为 U 中不属于 A 的元素。","id":"sy-g1-c1-l2-q3"},{"type":"fill","level":"中档","stem":"若 1∈{a, a²}，则 a=____","answer":"−1","analysis":"a=1 时元素重复不满足互异性；a²=1 得 a=±1，排除 a=1，故 a=−1。","id":"sy-g1-c1-l1-q3"},{"id":"sy-g1-c1-l2-e1","type":"essay","level":"简答","stem":"简答：已知 A={1,2,3}，写出 A 的所有子集，并说明为什么不能漏掉空集。","ref":"子集：∅、{1}、{2}、{3}、{1,2}、{1,3}、{2,3}、{1,2,3}（其中真子集除 {1,2,3} 外共 7 个）。空集是任何集合的子集，定义如此，漏掉会少解。"},{"id":"sy-g1-c1-l2-e2","type":"essay","level":"简答","stem":"简答：说明 A∩B、A∪B、∁ᵤA 三种运算的结果与韦恩图阴影区域的对应关系。","ref":"A∩B 是两集合公共部分；A∪B 是两集合合并后的全部部分；∁ᵤA 是全集 U 中除去 A 剩下的部分。画图时分别涂公共区、并集整体、A 外区域。"}]},{"id":"sy-g1-c1-l3","name":"1.3 充分条件与全称量词","chapterId":"sy-g1-c1","chapterName":"集合与常用逻辑用语","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"\"x>0\" 是 \"x²>0\" 的","options":["充分不必要条件","必要不充分条件","充要条件","既不充分也不必要条件"],"answer":0,"analysis":"x>0 必有 x²>0；x=−1 时 x²>0 但 x<0，反向不成立。","id":"sy-g1-c1-l3-q1"},{"type":"choice","level":"基础","stem":"命题 \"∀x∈R，x²+1>0\" 的否定是","options":["∃x∈R，x²+1≤0","∀x∈R，x²+1≤0","∃x∈R，x²+1>0","∃x∈R，x²+1<0"],"answer":0,"analysis":"全称命题的否定：量词改存在，结论取反（\">\" 的否定是 \"≤\"）。","id":"sy-g1-c1-l3-q2"},{"type":"fill","level":"中档","stem":"\"x>3\" 是 \"x>1\" 的____条件（填\"充分不必要\"\"必要不充分\"\"充要\"\"既不充分也不必要\"）","answer":"充分不必要","analysis":"x>3⇒x>1；反之取 x=2 不成立。","id":"sy-g1-c1-l3-q3"},{"type":"fill","level":"中档","stem":"若 1∈{a, a²}，则 a=____","answer":"−1","analysis":"a=1 时元素重复不满足互异性；a²=1 得 a=±1，排除 a=1，故 a=−1。","id":"sy-g1-c1-l1-q3"},{"id":"sy-g1-c1-l3-e1","type":"essay","level":"简答","stem":"简答：说明判断 \"p 是 q 的充分条件\" 的集合方法，并举例。","ref":"设 p 对应集合 A、q 对应集合 B，若 A⊆B 则 p 是 q 的充分条件。例：p: x>2，q: x>0，{x|x>2}⊆{x|x>0}，故 p 是 q 的充分条件。"},{"id":"sy-g1-c1-l3-e2","type":"essay","level":"简答","stem":"简答：写出 \"∃x∈R，x²−2x+3<0\" 的否定，并判断其真假。","ref":"否定为 \"∀x∈R，x²−2x+3≥0\"。因 Δ=(−2)²−4×3=−8<0，开口向上恒正，故该全称命题为真。"}]}]},{"id":"sy-g1-c2","name":"一元二次函数、方程和不等式","book":"必修第一册","grade":"高一","lessons":[{"id":"sy-g1-c2-l1","name":"2.1 等式性质与不等式性质","chapterId":"sy-g1-c2","chapterName":"一元二次函数、方程和不等式","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"若 a>b，则下列一定成立的是","options":["a−3>b−3","a²>b²","1/a<1/b","ac>bc"],"answer":0,"analysis":"不等式两边同减同一个数，方向不变；其余选项在负数、c≤0 时不成立。","id":"sy-g1-c2-l1-q1"},{"type":"choice","level":"基础","stem":"若 a>b，c>0，则","options":["ac>bc","ac<bc","a/c<b/c","大小不确定"],"answer":0,"analysis":"两边同乘正数 c，不等号方向不变。","id":"sy-g1-c2-l1-q2"},{"type":"fill","level":"中档","stem":"已知 1<x<3，2<y<4，则 x−y 的取值范围是____","answer":"(−3,1)","analysis":"x−y=x+(−y)，而 −4<−y<−2，同向相加得 −3<x−y<1。","id":"sy-g1-c2-l1-q3"},{"type":"fill","level":"中档","stem":"不等式 x²+2x−3≤0 的整数解共有____个","answer":"5","analysis":"解得 −3≤x≤1，整数为 −3,−2,−1,0,1，共 5 个。","id":"sy-g1-c2-l2-q3"},{"id":"sy-g1-c2-l1-e1","type":"essay","level":"简答","stem":"简答：举例说明 \"a>b 时 a²>b² 不一定成立\" 的反例，并指出比较大小的一般方法。","ref":"反例：a=1，b=−2，则 a>b 但 a²=1<b²=4。比较大小一般用作差法：作差→变形（因式分解、配方）→判断符号。"},{"id":"sy-g1-c2-l1-e2","type":"essay","level":"简答","stem":"简答：已知 a>b>0，c<d<0，简述证明 ac<bd 的思路。","ref":"由 c<d<0 得 −c>−d>0；又 a>b>0，同向正数不等式相乘得 −ac>−bd，两边同乘 −1 变号得 ac<bd。"}]},{"id":"sy-g1-c2-l2","name":"2.2 一元二次不等式","chapterId":"sy-g1-c2","chapterName":"一元二次函数、方程和不等式","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"不等式 x²−3x+2<0 的解集是","options":["1<x<2","x<1 或 x>2","−2<x<−1","全体实数"],"answer":0,"analysis":"因式分解 (x−1)(x−2)<0，小于取两根之间。","id":"sy-g1-c2-l2-q1"},{"type":"choice","level":"基础","stem":"不等式 −x²+4x−3≥0 的解集是","options":["1≤x≤3","x≤1 或 x≥3","−3≤x≤−1","空集"],"answer":0,"analysis":"两边乘 −1 得 x²−4x+3≤0，即 (x−1)(x−3)≤0，得 1≤x≤3。","id":"sy-g1-c2-l2-q2"},{"type":"fill","level":"中档","stem":"不等式 x²+2x−3≤0 的整数解共有____个","answer":"5","analysis":"解得 −3≤x≤1，整数为 −3,−2,−1,0,1，共 5 个。","id":"sy-g1-c2-l2-q3"},{"type":"fill","level":"中档","stem":"已知 1<x<3，2<y<4，则 x−y 的取值范围是____","answer":"(−3,1)","analysis":"x−y=x+(−y)，而 −4<−y<−2，同向相加得 −3<x−y<1。","id":"sy-g1-c2-l1-q3"},{"id":"sy-g1-c2-l2-e1","type":"essay","level":"简答","stem":"简答：叙述解一元二次不等式的一般步骤，并以 x²−x−6>0 为例说明。","ref":"步骤：化二次项系数为正→求对应方程的根→结合开口方向写解集。本例分解为 (x−2)(x+3)>0，开口向上，大于取两边，解集为 x<−3 或 x>2。"},{"id":"sy-g1-c2-l2-e2","type":"essay","level":"简答","stem":"简答：不等式 ax²+bx+c<0 恒成立的条件是什么？分情况说明。","ref":"a=0 时须 b=0 且 c<0；a≠0 时须 a<0 且 Δ=b²−4ac<0（开口向下且与 x 轴无交点，图像全在 x 轴下方）。"}]},{"id":"sy-g1-c2-l3","name":"2.3 基本不等式","chapterId":"sy-g1-c2","chapterName":"一元二次函数、方程和不等式","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"x>0 时，x+1/x 的最小值为","options":["1","2","4","不存在"],"answer":1,"analysis":"x+1/x≥2√(x·1/x)=2，当 x=1 时取等。","id":"sy-g1-c2-l3-q1"},{"type":"choice","level":"基础","stem":"x>0，y>0，x+y=4，则 xy 的最大值为","options":["2","4","8","16"],"answer":1,"analysis":"xy≤((x+y)/2)²=4，x=y=2 时取等。","id":"sy-g1-c2-l3-q2"},{"type":"fill","level":"中档","stem":"x>1 时，x+1/(x−1) 的最小值为____","answer":"3","analysis":"凑项：(x−1)+1/(x−1)+1≥2+1=3，当 x=2 时取等。","id":"sy-g1-c2-l3-q3"},{"type":"fill","level":"中档","stem":"已知 1<x<3，2<y<4，则 x−y 的取值范围是____","answer":"(−3,1)","analysis":"x−y=x+(−y)，而 −4<−y<−2，同向相加得 −3<x−y<1。","id":"sy-g1-c2-l1-q3"},{"id":"sy-g1-c2-l3-e1","type":"essay","level":"简答","stem":"简答：用基本不等式求最值时为什么要验证\"一正、二定、三相等\"？各举一个不满足的情形。","ref":"不满足任一条最值结论就不成立：一正——x<0 时不能直接用；二定——积或和不是定值则取不到；三相等——等号条件无解（如 x+1/x² 类型取等方程无实根）时最值不存在，须另求。"},{"id":"sy-g1-c2-l3-e2","type":"essay","level":"简答","stem":"简答：已知 x>0，说明求 x+4/x 最小值的完整过程，并指出等号成立条件。","ref":"x+4/x≥2√(x·4/x)=4，当且仅当 x=4/x 即 x=2 时取等，最小值为 4。关键：积为定值 4、两项均为正、等号可取。"}]}]},{"id":"sy-g1-c3","name":"函数的概念与性质","book":"必修第一册","grade":"高一","lessons":[{"id":"sy-g1-c3-l1","name":"3.1 函数的概念与表示","chapterId":"sy-g1-c3","chapterName":"函数的概念与性质","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"函数 f(x)=1/(x−1) 的定义域是","options":["x≠1","x>1","x≠0","全体实数"],"answer":0,"analysis":"分母不为零，故 x≠1。","id":"sy-g1-c3-l1-q1"},{"type":"choice","level":"基础","stem":"函数 f(x)=√(x+2) 的定义域是","options":["x≥−2","x>−2","x≤−2","全体实数"],"answer":0,"analysis":"被开方数非负：x+2≥0。","id":"sy-g1-c3-l1-q2"},{"type":"fill","level":"中档","stem":"f(x)=2x+1，则 f(f(1))=____","answer":"7","analysis":"f(1)=3，再代入得 f(3)=7。","id":"sy-g1-c3-l1-q3"},{"type":"fill","level":"中档","stem":"f(x) 为奇函数且 f(2)=3，则 f(−2)=____","answer":"−3","analysis":"奇函数满足 f(−x)=−f(x)。","id":"sy-g1-c3-l3-q3"},{"id":"sy-g1-c3-l1-e1","type":"essay","level":"简答","stem":"简答：同一函数的判断标准是什么？判断 f(x)=x 与 g(x)=√(x²) 是否为同一函数。","ref":"标准：定义域与对应关系都相同（值域不必直接比较）。g(x)=√(x²)=|x|，当 x<0 时 g(x)=−x≠x，对应关系不同，故不是同一函数。"},{"id":"sy-g1-c3-l1-e2","type":"essay","level":"简答","stem":"简答：求 f(x)=1/(x−2)+√(x+1) 的定义域，并写出求定义域的一般依据。","ref":"须 x−2≠0 且 x+1≥0，得 x≥−1 且 x≠2，即 [−1,2)∪(2,+∞)。依据：分母不为零、被开方数非负、实际意义等。"}]},{"id":"sy-g1-c3-l2","name":"3.2 单调性与最值","chapterId":"sy-g1-c3","chapterName":"函数的概念与性质","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"函数 f(x)=−2x+3 在 R 上","options":["单调递减","单调递增","先增后减","不具单调性"],"answer":0,"analysis":"一次函数斜率 −2<0，故单调递减。","id":"sy-g1-c3-l2-q1"},{"type":"choice","level":"基础","stem":"函数 f(x)=x²−2x 的单调递增区间是","options":["[1,+∞)","(−∞,1]","R","(0,+∞)"],"answer":0,"analysis":"对称轴 x=1，开口向上，右半支递增。","id":"sy-g1-c3-l2-q2"},{"type":"fill","level":"中档","stem":"f(x)=x²−4x+1 在 [0,3] 上的最小值为____","answer":"−3","analysis":"对称轴 x=2∈[0,3]，最小值 f(2)=−3。","id":"sy-g1-c3-l2-q3"},{"type":"fill","level":"中档","stem":"f(x)=2x+1，则 f(f(1))=____","answer":"7","analysis":"f(1)=3，再代入得 f(3)=7。","id":"sy-g1-c3-l1-q3"},{"id":"sy-g1-c3-l2-e1","type":"essay","level":"简答","stem":"简答：叙述用定义证明 f(x) 在区间 D 上单调递增的规范步骤。","ref":"四步：取值（任取 x₁<x₂∈D）→作差 f(x₁)−f(x₂)→变形（因式分解、通分，定号）→结论（差小于 0，故递增）。"},{"id":"sy-g1-c3-l2-e2","type":"essay","level":"简答","stem":"简答：说明函数 y=x+1/x（x>0）的单调区间及最值情况。","ref":"在 (0,1) 上递减，在 [1,+∞) 上递增；x=1 时取得最小值 2；无最大值。可由对勾函数图像或定义证明。"}]},{"id":"sy-g1-c3-l3","name":"3.3 奇偶性","chapterId":"sy-g1-c3","chapterName":"函数的概念与性质","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"f(x)=x³ 是","options":["奇函数","偶函数","既奇又偶","非奇非偶"],"answer":0,"analysis":"f(−x)=−x³=−f(x)，定义域 R 关于原点对称。","id":"sy-g1-c3-l3-q1"},{"type":"choice","level":"基础","stem":"f(x)=x²+1 是","options":["偶函数","奇函数","既奇又偶","非奇非偶"],"answer":0,"analysis":"f(−x)=f(x)，故为偶函数。","id":"sy-g1-c3-l3-q2"},{"type":"fill","level":"中档","stem":"f(x) 为奇函数且 f(2)=3，则 f(−2)=____","answer":"−3","analysis":"奇函数满足 f(−x)=−f(x)。","id":"sy-g1-c3-l3-q3"},{"type":"fill","level":"中档","stem":"f(x)=2x+1，则 f(f(1))=____","answer":"7","analysis":"f(1)=3，再代入得 f(3)=7。","id":"sy-g1-c3-l1-q3"},{"id":"sy-g1-c3-l3-e1","type":"essay","level":"简答","stem":"简答：叙述奇函数的定义，说明奇函数图像的特征及 f(0) 的取值要求。","ref":"定义：对定义域内任意 x，f(−x)=−f(x)。图像关于原点对称；若 0 在定义域内，则必有 f(0)=0（代 x=0 得 f(0)=−f(0)）。"},{"id":"sy-g1-c3-l3-e2","type":"essay","level":"简答","stem":"简答：判断 f(x)=x³+x 的奇偶性并证明；说明奇函数在对称区间上单调性的关系。","ref":"f(−x)=(−x)³+(−x)=−x³−x=−f(x)，且定义域为 R，故为奇函数。奇函数在对称区间上单调性相同（同增同减）。"}]}]},{"id":"sy-g1-c4","name":"指数函数与对数函数","book":"必修第一册","grade":"高一","lessons":[{"id":"sy-g1-c4-l1","name":"4.1 指数运算与指数函数","chapterId":"sy-g1-c4","chapterName":"指数函数与对数函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"2³×2⁻¹ 的值是","options":["2","4","8","16"],"answer":1,"analysis":"同底数幂相乘指数相加：2^(3−1)=2²=4。","id":"sy-g1-c4-l1-q1"},{"type":"choice","level":"基础","stem":"a^(2/3)·a^(1/3)（a>0）等于","options":["a","a²","a^(2/9)","1"],"answer":0,"analysis":"指数相加 2/3+1/3=1。","id":"sy-g1-c4-l1-q2"},{"type":"fill","level":"中档","stem":"(1/2)⁻² 的值是____","answer":"4","analysis":"负指数取倒数：(1/2)⁻²=2²=4。","id":"sy-g1-c4-l1-q3"},{"type":"fill","level":"中档","stem":"函数 f(x)=x²−3x+2 的零点个数为____","answer":"2","analysis":"Δ=9−8=1>0，两个不同实根 1 与 2。","id":"sy-g1-c4-l3-q3"},{"id":"sy-g1-c4-l1-e1","type":"essay","level":"简答","stem":"简答：化简 √a·√(1/a)（a>0）并说明分数指数幂与根式的互化规则。","ref":"√a·√(1/a)=√(a·1/a)=√1=1。规则：a^(m/n)=ⁿ√(aᵐ)（a>0，n>0）；根指数为分母、被开方数指数为分子，互化后按幂的运算法则计算。"},{"id":"sy-g1-c4-l1-e2","type":"essay","level":"简答","stem":"简答：说明指数函数 y=aˣ 的图象随 a 变化的规律（分 a>1 与 0<a<1 两种情况）。","ref":"a>1：图象上升，x 越大 y 越大，函数递增；0<a<1：图象下降，函数递减。两类图象都过定点 (0,1)，且位于 x 轴上方。"}]},{"id":"sy-g1-c4-l2","name":"4.2 对数运算与对数函数","chapterId":"sy-g1-c4","chapterName":"指数函数与对数函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"log₂8 的值是","options":["2","3","4","8"],"answer":1,"analysis":"2³=8，故 log₂8=3。","id":"sy-g1-c4-l2-q1"},{"type":"choice","level":"基础","stem":"lg2+lg5 的值是","options":["1","2","10","lg7"],"answer":0,"analysis":"lg2+lg5=lg10=1。","id":"sy-g1-c4-l2-q2"},{"type":"fill","level":"中档","stem":"log₃27+log₂(1/4) 的值是____","answer":"1","analysis":"log₃27=3，log₂(1/4)=−2，和为 1。","id":"sy-g1-c4-l2-q3"},{"type":"fill","level":"中档","stem":"函数 f(x)=x²−3x+2 的零点个数为____","answer":"2","analysis":"Δ=9−8=1>0，两个不同实根 1 与 2。","id":"sy-g1-c4-l3-q3"},{"id":"sy-g1-c4-l2-e1","type":"essay","level":"简答","stem":"简答：计算 log₂8+lg100 并写出每步所用的对数运算法则。","ref":"log₂8=log₂2³=3（指数式还原）；lg100=lg10²=2，和为 5。所用法则：log_a aⁿ=n（恒等式）。"},{"id":"sy-g1-c4-l2-e2","type":"essay","level":"简答","stem":"简答：说明对数函数 y=log_a x 的定义域、值域及 a 对单调性的影响。","ref":"定义域 (0,+∞)，值域 R。a>1 时递增，0<a<1 时递减；图象都过定点 (1,0)。真数必须大于 0，这是解题取值依据。"}]},{"id":"sy-g1-c4-l3","name":"4.3 函数的零点","chapterId":"sy-g1-c4","chapterName":"指数函数与对数函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"函数 f(x)=x−2 的零点是","options":["2","−2","(2,0)","0"],"answer":0,"analysis":"零点是使 f(x)=0 的自变量值，不是点。","id":"sy-g1-c4-l3-q1"},{"type":"choice","level":"基础","stem":"函数 f(x)=2ˣ−8 的零点是","options":["3","4","8","log₂8−1"],"answer":0,"analysis":"2ˣ=8=2³，故 x=3。","id":"sy-g1-c4-l3-q2"},{"type":"fill","level":"中档","stem":"函数 f(x)=x²−3x+2 的零点个数为____","answer":"2","analysis":"Δ=9−8=1>0，两个不同实根 1 与 2。","id":"sy-g1-c4-l3-q3"},{"type":"fill","level":"中档","stem":"(1/2)⁻² 的值是____","answer":"4","analysis":"负指数取倒数：(1/2)⁻²=2²=4。","id":"sy-g1-c4-l1-q3"},{"id":"sy-g1-c4-l3-e1","type":"essay","level":"简答","stem":"简答：叙述函数零点存在定理的条件与结论，并举一个不能用该定理的例子。","ref":"条件：f(x) 在 [a,b] 上图象连续不断，且 f(a)·f(b)<0；结论：存在零点 x₀∈(a,b)。反例：f(x)=1/x² 在含 0 的区间两端同号但无零点——定理条件不满足（不连续），不能套用。"},{"id":"sy-g1-c4-l3-e2","type":"essay","level":"简答","stem":"简答：说明用二分法求方程近似解的基本流程与终止标准。","ref":"流程：取两端点使函数值异号→取中点算函数值→与一端异号的区间保留→重复压缩区间。终止：区间长度小于给定精度 ε 时，中点即为近似解。"}]}]},{"id":"sy-g1-c5","name":"三角函数","book":"必修第一册","grade":"高一","lessons":[{"id":"sy-g1-c5-l1","name":"5.1 任意角与弧度制","chapterId":"sy-g1-c5","chapterName":"三角函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"120° 化为弧度是","options":["2π/3","3π/4","π/3","5π/6"],"answer":0,"analysis":"120°×π/180°=2π/3。","id":"sy-g1-c5-l1-q1"},{"type":"choice","level":"基础","stem":"5π/6 化为角度是","options":["150°","120°","135°","210°"],"answer":0,"analysis":"5π/6×180°/π=150°。","id":"sy-g1-c5-l1-q2"},{"type":"fill","level":"中档","stem":"与 −30° 终边相同的角的集合是____（用 α=−30°+k·360° 形式表示）","answer":"{α|α=−30°+k·360°,k∈Z}","analysis":"终边相同的角相差 360° 的整数倍。","id":"sy-g1-c5-l1-q3"},{"type":"fill","level":"中档","stem":"sin30°cos15°+cos30°sin15° 的值是____","answer":"√2/2","analysis":"逆用和角公式得 sin(30°+15°)=sin45°=√2/2。","id":"sy-g1-c5-l4-q3"},{"id":"sy-g1-c5-l1-e1","type":"essay","level":"简答","stem":"简答：写出弧度制下扇形弧长与面积公式，并说明与角度制公式的联系。","ref":"弧长 l=αr，面积 S=½l·r=½αr²（α 为弧度）。与角度制联系：n°=nπ/180 rad，代入后两公式一致。"},{"id":"sy-g1-c5-l1-e2","type":"essay","level":"简答","stem":"简答：把 150° 化为弧度，并说明终边相同的角的表示方法。","ref":"150°=150×π/180=5π/6。与 α 终边相同的角为 β=α+2kπ（k∈Z），即相差整数圈。"}]},{"id":"sy-g1-c5-l2","name":"5.2 三角函数定义与诱导公式","chapterId":"sy-g1-c5","chapterName":"三角函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"已知角 α 的终边经过点 (3,4)，则 sinα 的值是","options":["4/5","3/5","3/4","4/3"],"answer":0,"analysis":"r=5，sinα=y/r=4/5。","id":"sy-g1-c5-l2-q1"},{"type":"choice","level":"基础","stem":"sin150° 的值是","options":["1/2","−1/2","√3/2","−√3/2"],"answer":0,"analysis":"sin150°=sin(180°−30°)=sin30°=1/2。","id":"sy-g1-c5-l2-q2"},{"type":"fill","level":"中档","stem":"cos(π+α)=____","answer":"−cosα","analysis":"π+α 在第三象限，余弦为负，函数名不变。","id":"sy-g1-c5-l2-q3"},{"type":"fill","level":"中档","stem":"sin30°cos15°+cos30°sin15° 的值是____","answer":"√2/2","analysis":"逆用和角公式得 sin(30°+15°)=sin45°=√2/2。","id":"sy-g1-c5-l4-q3"},{"id":"sy-g1-c5-l2-e1","type":"essay","level":"简答","stem":"简答：写出角 α 终边上一点 P(x,y)（r=|OP|）的六个三角函数值定义。","ref":"sinα=y/r，cosα=x/r，tanα=y/x（x≠0），倒数关系：cscα=r/y、secα=r/x、cotα=x/y（相应分母非零）。"},{"id":"sy-g1-c5-l2-e2","type":"essay","level":"简答","stem":"简答：叙述诱导公式中\"奇变偶不变，符号看象限\"的含义并举一例。","ref":"角 π/2±α、3π/2±α（奇数倍）时函数名改变（sin↔cos），2π±α、π±α（偶数倍）不变；符号由把 α 看作锐角时原函数在相应象限的正负决定。例：sin(π+α)=−sinα（第三象限 sin 为负）。"}]},{"id":"sy-g1-c5-l3","name":"5.3 三角函数的图象与性质","chapterId":"sy-g1-c5","chapterName":"三角函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"函数 y=sin x 的最小正周期为","options":["2π","π","π/2","4π"],"answer":0,"analysis":"正弦函数周期 2π。","id":"sy-g1-c5-l3-q1"},{"type":"choice","level":"基础","stem":"y=cosx 的最大值是","options":["1","0","−1","2"],"answer":0,"analysis":"余弦值域 [−1,1]，最大值 1。","id":"sy-g1-c5-l3-q2"},{"type":"fill","level":"中档","stem":"y=2sin(2x+π/3) 的最小正周期是____","answer":"π","analysis":"T=2π/|ω|=2π/2=π。","id":"sy-g1-c5-l3-q3"},{"type":"fill","level":"中档","stem":"sin30°cos15°+cos30°sin15° 的值是____","answer":"√2/2","analysis":"逆用和角公式得 sin(30°+15°)=sin45°=√2/2。","id":"sy-g1-c5-l4-q3"},{"id":"sy-g1-c5-l3-e1","type":"essay","level":"简答","stem":"简答：说明正弦曲线 y=sin x 的周期、最值、对称轴，并说明 \"T=2π\" 的含义。","ref":"最小正周期 2π：每隔 2π 图象重复一次；最大值 1（x=π/2+2kπ）、最小值 −1（x=3π/2+2kπ）；对称轴 x=π/2+kπ。"},{"id":"sy-g1-c5-l3-e2","type":"essay","level":"简答","stem":"简答：由 y=sin x 的图象如何得到 y=2sin(2x+π/3) 的图象？写出变换顺序。","ref":"三种等效顺序之一：先左移 π/3 得 y=sin(x+π/3)；再纵坐标不变横坐标缩短为原来 1/2（周期变 π）；最后纵坐标伸长为原来的 2 倍（最大值 2）。"}]},{"id":"sy-g1-c5-l4","name":"5.4 三角恒等变换","chapterId":"sy-g1-c5","chapterName":"三角函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"sin2α 等于","options":["2sinαcosα","sin²α−cos²α","2sin²α","cos²α−sin²α"],"answer":0,"analysis":"二倍角正弦公式。","id":"sy-g1-c5-l4-q1"},{"type":"choice","level":"基础","stem":"cos2α 可化为","options":["1−2sin²α","2sin²α−1","2cos²α−1+2","1+2sin²α"],"answer":0,"analysis":"cos2α=1−2sin²α=2cos²α−1。","id":"sy-g1-c5-l4-q2"},{"type":"fill","level":"中档","stem":"sin30°cos15°+cos30°sin15° 的值是____","answer":"√2/2","analysis":"逆用和角公式得 sin(30°+15°)=sin45°=√2/2。","id":"sy-g1-c5-l4-q3"},{"type":"fill","level":"中档","stem":"与 −30° 终边相同的角的集合是____（用 α=−30°+k·360° 形式表示）","answer":"{α|α=−30°+k·360°,k∈Z}","analysis":"终边相同的角相差 360° 的整数倍。","id":"sy-g1-c5-l1-q3"},{"id":"sy-g1-c5-l4-e1","type":"essay","level":"简答","stem":"简答：写出两角和与差的正弦、余弦公式（sin(α±β)、cos(α±β)）。","ref":"sin(α±β)=sinαcosβ±cosαsinβ；cos(α±β)=cosαcosβ∓sinαsinβ（和角取上号、差角取下号）。"},{"id":"sy-g1-c5-l4-e2","type":"essay","level":"简答","stem":"简答：化简 sin(x+π/4)·cos(x−π/4)−cos(x+π/4)·sin(x−π/4)，并说明所用公式。","ref":"逆用 sin(A−B)=sinAcosB−cosAsinB，原式=sin[(x+π/4)−(x−π/4)]=sin(π/2)=1。"}]}]},{"id":"sy-g1-c6","name":"平面向量及其应用","book":"必修第二册","grade":"高一","lessons":[{"id":"sy-g1-c6-l1","name":"6.1 向量的线性运算","chapterId":"sy-g1-c6","chapterName":"平面向量及其应用","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"向量 AB + 向量 BC =","options":["向量 AC","向量 CA","向量 BA","零向量"],"answer":0,"analysis":"首尾相接，首连尾：AB+BC=AC。","id":"sy-g1-c6-l1-q1"},{"type":"choice","level":"基础","stem":"a=(1,2)，b=(3,−1)，则 a+b=","options":["(4,1)","(2,3)","(−2,3)","(4,−1)"],"answer":0,"analysis":"坐标相加：(1+3, 2−1)=(4,1)。","id":"sy-g1-c6-l1-q2"},{"type":"fill","level":"中档","stem":"a=(2,−4)，则 2a=____","answer":"(4,−8)","analysis":"数乘向量各坐标同乘 2。","id":"sy-g1-c6-l1-q3"},{"type":"fill","level":"中档","stem":"在 △ABC 中，a=3，b=4，C=60°，则 c²=____","answer":"13","analysis":"c²=9+16−2×3×4×(1/2)=13。","id":"sy-g1-c6-l3-q3"},{"id":"sy-g1-c6-l1-e1","type":"essay","level":"简答","stem":"简答：说明向量数乘 a 的几何意义，并写出共线向量定理。","ref":"λa 与 a 共线：λ>0 同向、λ<0 反向、|λa|=|λ||a|。共线定理：a∥b（a≠0）⇔ 存在唯一实数 λ 使 b=λa。"},{"id":"sy-g1-c6-l1-e2","type":"essay","level":"简答","stem":"简答：用向量线性运算说明\"AB→+BC→=AC→\"的几何意义，并举例说明化简一条折线向量式的方法。","ref":"首尾相接的两段位移之和等于起点到终点的总位移（三角形法则）。化简方法：按字母顺序首尾相接逐步合并，如 AB→+BC→+CD→=AD→。"}]},{"id":"sy-g1-c6-l2","name":"6.2 数量积、夹角与模","chapterId":"sy-g1-c6","chapterName":"平面向量及其应用","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"a·b=|a||b|cosθ 中 θ 的取值范围是","options":["[0,π]","[0,2π)","(0,π)","[−π/2,π/2]"],"answer":0,"analysis":"两向量夹角定义在 0 到 π 之间。","id":"sy-g1-c6-l2-q1"},{"type":"choice","level":"基础","stem":"a=(1,0)，b=(0,1)，则 a·b=","options":["0","1","2","−1"],"answer":0,"analysis":"坐标数量积 1×0+0×1=0，两向量垂直。","id":"sy-g1-c6-l2-q2"},{"type":"fill","level":"中档","stem":"|a|=2，|b|=3，a·b=3，则 cos<a,b>=____","answer":"1/2","analysis":"cosθ=3/(2×3)=1/2。","id":"sy-g1-c6-l2-q3"},{"type":"fill","level":"中档","stem":"在 △ABC 中，a=3，b=4，C=60°，则 c²=____","answer":"13","analysis":"c²=9+16−2×3×4×(1/2)=13。","id":"sy-g1-c6-l3-q3"},{"id":"sy-g1-c6-l2-e1","type":"essay","level":"简答","stem":"简答：写出数量积的定义式，并说明如何用它求两向量的夹角。","ref":"a·b=|a||b|cosθ。由 cosθ=(a·b)/(|a||b|)（θ∈[0,π]）反求夹角；a·b=0 是垂直的充要条件。"},{"id":"sy-g1-c6-l2-e2","type":"essay","level":"简答","stem":"简答：说明 a·b 与 |a||b| 的大小关系及取等条件。","ref":"a·b=|a||b|cosθ≤|a||b|，当且仅当 θ=0（同向）时取等；θ=π（反向）时 a·b=−|a||b| 最小。"}]},{"id":"sy-g1-c6-l3","name":"6.3 解三角形（正弦、余弦定理）","chapterId":"sy-g1-c6","chapterName":"平面向量及其应用","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"在 △ABC 中，a=2，A=30°，则 2R（R 为外接圆半径）等于","options":["4","2","1","8"],"answer":0,"analysis":"由 a/sinA=2R 得 2R=2/(1/2)=4。","id":"sy-g1-c6-l3-q1"},{"type":"choice","level":"基础","stem":"已知 b=3，c=4，A=90°，则 a=","options":["5","7","1","√7"],"answer":0,"analysis":"余弦定理 a²=b²+c²−2bc·cos90°=25。","id":"sy-g1-c6-l3-q2"},{"type":"fill","level":"中档","stem":"在 △ABC 中，a=3，b=4，C=60°，则 c²=____","answer":"13","analysis":"c²=9+16−2×3×4×(1/2)=13。","id":"sy-g1-c6-l3-q3"},{"type":"fill","level":"中档","stem":"|a|=2，|b|=3，a·b=3，则 cos<a,b>=____","answer":"1/2","analysis":"cosθ=3/(2×3)=1/2。","id":"sy-g1-c6-l2-q3"},{"id":"sy-g1-c6-l3-e1","type":"essay","level":"简答","stem":"简答：写出正弦定理与余弦定理，并各说明一种典型适用情形。","ref":"正弦定理 a/sinA=b/sinB=c/sinC=2R：已知两角一边或两边与其中一边的对角时用。余弦定理 a²=b²+c²−2bc·cosA：已知两边夹角或三边求角时用。"},{"id":"sy-g1-c6-l3-e2","type":"essay","level":"简答","stem":"简答：在△ABC 中说明由 a²>b²+c² 能得到什么结论，依据是什么。","ref":"由余弦定理 cosA=(b²+c²−a²)/(2bc)<0，而 A∈(0,π)，故 A 为钝角，三角形为钝角三角形。依据：余弦定理与余弦函数在 (0,π) 的符号。"}]}]},{"id":"sy-g1-c7","name":"复数","book":"必修第二册","grade":"高一","lessons":[{"id":"sy-g1-c7-l1","name":"7.1 复数的概念与几何意义","chapterId":"sy-g1-c7","chapterName":"复数","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"复数 z=3−2i 的虚部是","options":["−2","2","−2i","3"],"answer":0,"analysis":"虚部是不含 i 的实数 −2。","id":"sy-g1-c7-l1-q1"},{"type":"choice","level":"基础","stem":"复数 z=1+2i 在复平面内对应的点位于","options":["第一象限","第二象限","第三象限","第四象限"],"answer":0,"analysis":"实部 1>0，虚部 2>0，位于第一象限。","id":"sy-g1-c7-l1-q2"},{"type":"fill","level":"中档","stem":"复数 z=3+4i 的模 |z|=____","answer":"5","analysis":"|z|=√(9+16)=5。","id":"sy-g1-c7-l1-q3"},{"type":"fill","level":"中档","stem":"(1+i)(1−i)=____","answer":"2","analysis":"按平方差展开得 1−i²=1+1=2。","id":"sy-g1-c7-l2-q3"},{"id":"sy-g1-c7-l1-e1","type":"essay","level":"简答","stem":"简答：说明复数 z=a+bi（a,b∈R）与复平面内点、平面向量的对应关系，并写出模的计算式。","ref":"z 对应点 Z(a,b) 及向量 OZ→；模 |z|=√(a²+b²)。实部 a 对应横坐标，虚部 b 对应纵坐标。"},{"id":"sy-g1-c7-l1-e2","type":"essay","level":"简答","stem":"简答：说明纯虚数与实数的区别，并指出 b 为何值时 z=(b−1)+(b²−1)i 为纯虚数。","ref":"纯虚数实部为 0 且虚部不为 0。须 b−1=0 且 b²−1≠0，得 b=1（b=−1 时虚部为 0 舍去），此时 z=2i 为纯虚数。"}]},{"id":"sy-g1-c7-l2","name":"7.2 复数的四则运算","chapterId":"sy-g1-c7","chapterName":"复数","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"(1+i)+(2−i)=","options":["3","3+2i","1+2i","3−2i"],"answer":0,"analysis":"实部虚部分别相加，虚部抵消为 0。","id":"sy-g1-c7-l2-q1"},{"type":"choice","level":"基础","stem":"i² 等于","options":["−1","1","i","−i"],"answer":0,"analysis":"虚数单位定义 i²=−1。","id":"sy-g1-c7-l2-q2"},{"type":"fill","level":"中档","stem":"(1+i)(1−i)=____","answer":"2","analysis":"按平方差展开得 1−i²=1+1=2。","id":"sy-g1-c7-l2-q3"},{"type":"fill","level":"中档","stem":"复数 z=3+4i 的模 |z|=____","answer":"5","analysis":"|z|=√(9+16)=5。","id":"sy-g1-c7-l1-q3"},{"id":"sy-g1-c7-l2-e1","type":"essay","level":"简答","stem":"简答：计算 (1+i)² 并说明虚数单位 i 的乘方周期性。","ref":"(1+i)²=1+2i+i²=2i。i 的乘方按 4 为周期循环：i¹=i，i²=−1，i³=−i，i⁴=1，iⁿ 按 n 除以 4 的余数取值。"},{"id":"sy-g1-c7-l2-e2","type":"essay","level":"简答","stem":"简答：说明复数除法\"分母实数化\"的方法，并计算 (1+i)/(1−i)。","ref":"分子分母同乘分母的共轭复数。(1+i)/(1−i)×[(1+i)/(1+i)]=(1+i)²/2=2i/2=i。"}]}]},{"id":"sy-g1-c8","name":"立体几何初步","book":"必修第二册","grade":"高一","lessons":[{"id":"sy-g1-c8-l1","name":"8.1 基本几何体与表面积、体积","chapterId":"sy-g1-c8","chapterName":"立体几何初步","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"棱长为 2 的正方体体积为","options":["8","4","12","6"],"answer":0,"analysis":"V=a³=8。","id":"sy-g1-c8-l1-q1"},{"type":"choice","level":"基础","stem":"底面半径为 1、高为 3 的圆柱体积为","options":["3π","π","6π","9π"],"answer":0,"analysis":"V=πr²h=3π。","id":"sy-g1-c8-l1-q2"},{"type":"fill","level":"中档","stem":"表面积为 6 的正方体，其棱长为____","answer":"1","analysis":"6a²=6 得 a=1。","id":"sy-g1-c8-l1-q3"},{"type":"fill","level":"中档","stem":"过平面外一点，与已知平面平行的平面有____个","answer":"1","analysis":"过平面外一点有且只有一个平面与已知平面平行。","id":"sy-g1-c8-l2-q3"},{"id":"sy-g1-c8-l1-e1","type":"essay","level":"简答","stem":"简答：写出棱柱、棱锥、棱台的定义要点，并说明它们的联系。","ref":"棱柱：两底面平行、侧面均为平行四边形；棱锥：一个底面、侧面三角形共顶点；棱台：棱锥被平行于底面的平面截得。联系：棱台可由棱锥截得，棱柱上下底面全等。"},{"id":"sy-g1-c8-l1-e2","type":"essay","level":"简答","stem":"简答：写出球的表面积与体积公式，并说明用\"正方体外接球\"求球的思路。","ref":"S=4πR²，V=(4/3)πR³。正方体棱长 a 时，体对角线即外接球直径：2R=√3·a，故 R=√3a/2，再代公式。"}]},{"id":"sy-g1-c8-l2","name":"8.2 空间点线面位置关系","chapterId":"sy-g1-c8","chapterName":"立体几何初步","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"两条不重合直线的位置关系有","options":["平行、相交、异面","只有平行与相交","只有相交与异面","只有平行与异面"],"answer":0,"analysis":"空间中两直线共面则平行或相交，不共面则异面。","id":"sy-g1-c8-l2-q1"},{"type":"choice","level":"基础","stem":"若直线 a∥平面 α，直线 b⊂α，则 a 与 b","options":["可能平行也可能异面","一定平行","一定相交","一定异面"],"answer":0,"analysis":"线面平行时，面内直线与它无公共点，可能平行也可能异面。","id":"sy-g1-c8-l2-q2"},{"type":"fill","level":"中档","stem":"过平面外一点，与已知平面平行的平面有____个","answer":"1","analysis":"过平面外一点有且只有一个平面与已知平面平行。","id":"sy-g1-c8-l2-q3"},{"type":"fill","level":"中档","stem":"表面积为 6 的正方体，其棱长为____","answer":"1","analysis":"6a²=6 得 a=1。","id":"sy-g1-c8-l1-q3"},{"id":"sy-g1-c8-l2-e1","type":"essay","level":"简答","stem":"简答：叙述异面直线的定义，并举教室里的一个实例说明\"不同在任何一个平面内\"。","ref":"不同在任何一个平面内的两条直线叫异面直线，既不平行也不相交。实例：教室前排地面上的一条线与天花板另一侧横走的直线，无论如何放置平面都不能同时包含两者。"},{"id":"sy-g1-c8-l2-e2","type":"essay","level":"简答","stem":"简答：说明线面平行、面面平行的判定定理及各自需要的条件个数。","ref":"线面平行：平面外一条直线与此平面内一条直线平行（需线在面外+面内线平行）。面面平行：一个平面内两条相交直线都平行于另一平面（需两条且相交）。"}]},{"id":"sy-g1-c8-l3","name":"8.3 平行与垂直的判定","chapterId":"sy-g1-c8","chapterName":"立体几何初步","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"判定直线与平面平行的常用方法是","options":["平面外一条直线与此平面内一条直线平行","直线与平面内两条直线平行","直线与平面垂直","直线与平面无交点即可直接判定"],"answer":0,"analysis":"线面平行判定定理：线线平行推出线面平行。","id":"sy-g1-c8-l3-q1"},{"type":"choice","level":"基础","stem":"若一条直线垂直于平面内两条相交直线，则该直线","options":["垂直于这个平面","平行于这个平面","在平面内","与平面斜交"],"answer":0,"analysis":"线面垂直判定定理。","id":"sy-g1-c8-l3-q2"},{"type":"fill","level":"中档","stem":"正方体 ABCD-A₁B₁C₁D₁ 中，AB 与 A₁C₁ 的位置关系是____（填\"平行\"\"相交\"或\"异面\"）","answer":"异面","analysis":"两直线不共面且不相交，为异面直线。","id":"sy-g1-c8-l3-q3"},{"type":"fill","level":"中档","stem":"过平面外一点，与已知平面平行的平面有____个","answer":"1","analysis":"过平面外一点有且只有一个平面与已知平面平行。","id":"sy-g1-c8-l2-q3"},{"id":"sy-g1-c8-l3-e1","type":"essay","level":"简答","stem":"简答：写出线面垂直的判定定理，并说明为什么\"一条直线垂直于平面内一条直线\"不够。","ref":"定理：直线垂直于平面内两条相交直线，则线面垂直。只垂直一条直线时该直线可能斜着落在平面内，必须与两条相交直线都垂直才能保证垂直于所有直线。"},{"id":"sy-g1-c8-l3-e2","type":"essay","level":"简答","stem":"简答：证明\"若 a∥α，b⊂α，则 a∥b 或 a 与 b 异面\"，写出推理思路。","ref":"反证：若 a 与 b 相交，交点在 α 内，则 a 与 α 有公共点，与 a∥α 矛盾。又 a 不在 α 内（面外），故 a 与 b 无公共点，只能平行或异面。"}]}]},{"id":"sy-g1-c9","name":"统计、概率","book":"必修第二册","grade":"高一","lessons":[{"id":"sy-g1-c9-l1","name":"9.1 随机抽样与样本估计","chapterId":"sy-g1-c9","chapterName":"统计、概率","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"从 1000 名学生中抽取 50 人调查，最合适的抽样方法是","options":["系统抽样","简单随机抽样中的抽签法","整群抽样","普查"],"answer":0,"analysis":"总体容量较大且无明显分层时，等距抽取即系统抽样更便利。","id":"sy-g1-c9-l1-q1"},{"type":"choice","level":"基础","stem":"一组数据 1,2,3,4,5 的平均数是","options":["3","2.5","4","15"],"answer":0,"analysis":"总和 15 除以 5 得 3。","id":"sy-g1-c9-l1-q2"},{"type":"fill","level":"中档","stem":"数据 1,2,3,4,5 的方差是____","answer":"2","analysis":"偏差平方和 (4+1+0+1+4)=10，除以 5 得 2。","id":"sy-g1-c9-l1-q3"},{"type":"fill","level":"中档","stem":"同时掷两枚均匀硬币，恰有一枚正面向上的概率是____","answer":"1/2","analysis":"样本空间 {正正,正反,反正,反反}，符合条件 2 个，概率 1/2。","id":"sy-g1-c9-l2-q3"},{"id":"sy-g1-c9-l1-e1","type":"essay","level":"简答","stem":"简答：比较简单随机抽样、分层抽样、系统抽样的特点与适用情形。","ref":"简单随机抽样：总体小、个体差异小，抽签或随机数；分层抽样：总体由差异明显的几层构成，按比例各层抽取；系统抽样：总体大且分布均匀，编号后按固定间隔抽。共同点：每个个体被抽到机会均等。"},{"id":"sy-g1-c9-l1-e2","type":"essay","level":"简答","stem":"简答：说明用样本频率分布直方图估计总体分布的步骤及纵坐标的含义。","ref":"步骤：求极差→定组距分组→统计频数→算频率/组距作纵坐标→画直方图。纵坐标=频率/组距，各矩形面积之和为 1，面积才是该组频率。"}]},{"id":"sy-g1-c9-l2","name":"9.2 古典概型","chapterId":"sy-g1-c9","chapterName":"统计、概率","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"掷一枚质地均匀的骰子，出现偶数点的概率是","options":["1/2","1/3","1/6","2/3"],"answer":0,"analysis":"偶数点 2,4,6 共 3 个，3/6=1/2。","id":"sy-g1-c9-l2-q1"},{"type":"choice","level":"基础","stem":"从 1,2,3,4 中任取一个数，取到质数的概率是","options":["1/2","1/4","3/4","1/3"],"answer":0,"analysis":"质数 2,3 共 2 个，2/4=1/2。","id":"sy-g1-c9-l2-q2"},{"type":"fill","level":"中档","stem":"同时掷两枚均匀硬币，恰有一枚正面向上的概率是____","answer":"1/2","analysis":"样本空间 {正正,正反,反正,反反}，符合条件 2 个，概率 1/2。","id":"sy-g1-c9-l2-q3"},{"type":"fill","level":"中档","stem":"数据 1,2,3,4,5 的方差是____","answer":"2","analysis":"偏差平方和 (4+1+0+1+4)=10，除以 5 得 2。","id":"sy-g1-c9-l1-q3"},{"id":"sy-g1-c9-l2-e1","type":"essay","level":"简答","stem":"简答：叙述古典概型的两个特征，并举一个满足与一个不满足的例子。","ref":"特征：基本事件有限个；每个基本事件等可能。满足：掷一枚均匀骰子（6 个等可能结果）。不满足：射击命中环数概率不等或连续型情形（如转盘指针停点位置无限多）。"},{"id":"sy-g1-c9-l2-e2","type":"essay","level":"简答","stem":"简答：同时掷两枚均匀硬币，说明\"出现一正一反\"的概率为什么是 1/2 而不是 1/3。","ref":"基本事件：(正,正)、(正,反)、(反,正)、(反,反) 共 4 个等可能；一正一反含 (正,反)、(反,正) 两个事件，故 P=2/4=1/2。错误在于把 (正,反) 与 (反,正) 当成一个事件。"}]},{"id":"sy-g1-c9-l3","name":"9.3 事件的关系与频率","chapterId":"sy-g1-c9","chapterName":"统计、概率","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"若 A、B 为互斥事件，则 P(A∪B)=","options":["P(A)+P(B)","P(A)P(B)","1","P(A)−P(B)"],"answer":0,"analysis":"互斥事件不能同时发生，概率可直接相加。","id":"sy-g1-c9-l3-q1"},{"type":"choice","level":"基础","stem":"事件 A 与其对立事件 Ā 满足","options":["P(A)+P(Ā)=1","P(A)=P(Ā)","P(A)P(Ā)=1","P(A)+P(Ā)=0"],"answer":0,"analysis":"对立事件必有一个发生，概率和为 1。","id":"sy-g1-c9-l3-q2"},{"type":"fill","level":"中档","stem":"P(A)=0.3，则 P(Ā)=____","answer":"0.7","analysis":"对立事件概率 = 1−0.3。","id":"sy-g1-c9-l3-q3"},{"type":"fill","level":"中档","stem":"数据 1,2,3,4,5 的方差是____","answer":"2","analysis":"偏差平方和 (4+1+0+1+4)=10，除以 5 得 2。","id":"sy-g1-c9-l1-q3"},{"id":"sy-g1-c9-l3-e1","type":"essay","level":"简答","stem":"简答：说明互斥事件与对立事件的区别与联系，并各举一例。","ref":"互斥：不能同时发生；对立：互斥且必有一个发生（并集为全集）。对立必互斥，互斥未必对立。例：掷骰子\"出现 1 点\"与\"出现 2 点\"互斥不对立；\"出现奇数\"与\"出现偶数\"对立。"},{"id":"sy-g1-c9-l3-e2","type":"essay","level":"简答","stem":"简答：说明用频率估计概率的依据与注意点。","ref":"大量重复试验中频率稳定于概率附近（概率的统计定义），可用频率作为概率的估计值。注意：试验次数要足够多；单次或少次试验的频率波动大，不宜直接当概率。"}]}]}],"高二":[{"id":"sy-g2-c1","name":"空间向量与立体几何","book":"选择性必修第一册","grade":"高二","lessons":[{"id":"sy-g2-c1-l1","name":"1.1 空间向量的运算与坐标表示","chapterId":"sy-g2-c1","chapterName":"空间向量与立体几何","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"a=(1,2,3)，b=(0,1,−1)，则 a−b=","options":["(1,1,4)","(1,3,2)","(1,1,2)","(1,−1,4)"],"answer":0,"analysis":"对应坐标相减：(1−0, 2−1, 3+1)。","id":"sy-g2-c1-l1-q1"},{"type":"choice","level":"基础","stem":"a=(2,−1,2)，则 |a|=","options":["3","5","√5","9"],"answer":0,"analysis":"|a|=√(4+1+4)=3。","id":"sy-g2-c1-l1-q2"},{"type":"fill","level":"中档","stem":"A(1,0,0)，B(0,2,2)，则 |AB|=____","answer":"3","analysis":"AB=(−1,2,2)，模为 √(1+4+4)=3。","id":"sy-g2-c1-l1-q3"},{"type":"fill","level":"中档","stem":"向量 a=(1,0,0) 与 b=(0,1,0) 的夹角为____度","answer":"90","analysis":"a·b=0，两向量垂直，夹角 90°。","id":"sy-g2-c1-l2-q3"},{"id":"sy-g2-c1-l1-e1","type":"essay","level":"简答","stem":"简答：写出空间向量数量积的坐标公式，并说明如何用它求两条异面直线所成角。","ref":"a·b=a₁b₁+a₂b₂+a₃b₃。求出两直线方向向量 a、b，则 cosθ=|a·b|/(|a||b|)（加绝对值保证角为 [0,π/2]）。"},{"id":"sy-g2-c1-l1-e2","type":"essay","level":"简答","stem":"简答：说明如何建立空间直角坐标系表示一个长方体中的点，并举点 A(0,0,0)、B(2,0,0)、C(2,3,0)、D(2,3,4) 说明 AC→ 与 BD→ 是否垂直。","ref":"取公共顶点为原点，三条棱为 x、y、z 轴。AC→=(2,3,0)，BD→=(0,3,4)；数量积=2×0+3×3+0×4=9≠0，不垂直。"}]},{"id":"sy-g2-c1-l2","name":"1.2 空间角与距离的向量求法","chapterId":"sy-g2-c1","chapterName":"空间向量与立体几何","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"直线与平面所成角 θ 的取值范围是","options":["[0,π/2]","[0,π]","(0,π/2)","[−π/2,π/2]"],"answer":0,"analysis":"线面角不超过直角。","id":"sy-g2-c1-l2-q1"},{"type":"choice","level":"基础","stem":"两个半平面所成二面角的取值范围是","options":["[0,π]","[0,π/2]","(0,π)","[−π,π]"],"answer":0,"analysis":"二面角可以取到钝角，范围 0 到 π。","id":"sy-g2-c1-l2-q2"},{"type":"fill","level":"中档","stem":"向量 a=(1,0,0) 与 b=(0,1,0) 的夹角为____度","answer":"90","analysis":"a·b=0，两向量垂直，夹角 90°。","id":"sy-g2-c1-l2-q3"},{"type":"fill","level":"中档","stem":"A(1,0,0)，B(0,2,2)，则 |AB|=____","answer":"3","analysis":"AB=(−1,2,2)，模为 √(1+4+4)=3。","id":"sy-g2-c1-l1-q3"},{"id":"sy-g2-c1-l2-e1","type":"essay","level":"简答","stem":"简答：叙述用向量法求线面角、二面角的步骤及角度取值范围。","ref":"线面角：求直线方向向量 a 与法向量 n，sinθ=|a·n|/(|a||n|)，θ∈[0,π/2]。二面角：求两半平面法向量 n₁、n₂，cosθ=±(n₁·n₂)/(|n₁||n₂|)，结合图形判断取正取负，θ∈[0,π]。"},{"id":"sy-g2-c1-l2-e2","type":"essay","level":"简答","stem":"简答：说明点到平面的距离的向量求法。","ref":"求平面法向量 n，取平面内一点 B 与该点 P，则距离 d=|PB→·n|/|n|，即投影长度。"}]},{"id":"sy-g2-c1-l3","name":"1.3 外接球、截面与折叠","chapterId":"sy-g2-c1","chapterName":"空间向量与立体几何","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"棱长为 a 的正方体的外接球半径是","options":["√3a/2","a/2","√2a/2","√3a"],"answer":0,"analysis":"体对角线为直径：2R=√3a。","id":"sy-g2-c1-l3-q1"},{"type":"choice","level":"基础","stem":"长、宽、高分别为 a、b、c 的长方体外接球半径是","options":["√(a²+b²+c²)/2","(a+b+c)/2","√(a²+b²)/2","√(abc)/2"],"answer":0,"analysis":"体对角线为直径，半径取一半。","id":"sy-g2-c1-l3-q2"},{"type":"fill","level":"中档","stem":"棱长为 2 的正方体的外接球表面积为____","answer":"12π","analysis":"R=√3，表面积 4πR²=12π。","id":"sy-g2-c1-l3-q3"},{"type":"fill","level":"中档","stem":"向量 a=(1,0,0) 与 b=(0,1,0) 的夹角为____度","answer":"90","analysis":"a·b=0，两向量垂直，夹角 90°。","id":"sy-g2-c1-l2-q3"},{"id":"sy-g2-c1-l3-e1","type":"essay","level":"简答","stem":"简答：说明正方体、长方体外接球球心位置的确定方法。","ref":"球心在体对角线中点（长方体/正方体各顶点到该点距离相等）。利用 2R=体对角线长求半径。"},{"id":"sy-g2-c1-l3-e2","type":"essay","level":"简答","stem":"简答：说明折叠问题中\"折前折后不变的量\"有哪些，并举一例。","ref":"不变量：同一半平面内的线段长度、共面图形内部的角与距离、垂直关系中同侧的部分。例：三角形沿一边折叠后，该边上的高（在被折图形内）长度不变，可用其构造直角三角形求翻折后的距离。"}]}]},{"id":"sy-g2-c2","name":"直线和圆的方程","book":"选择性必修第一册","grade":"高二","lessons":[{"id":"sy-g2-c2-l1","name":"2.1 直线的斜率与方程","chapterId":"sy-g2-c2","chapterName":"直线和圆的方程","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"过点 (0,0) 与 (1,2) 的直线斜率为","options":["2","1/2","−2","−1/2"],"answer":0,"analysis":"k=(2−0)/(1−0)=2。","id":"sy-g2-c2-l1-q1"},{"type":"choice","level":"基础","stem":"直线 y=2x+1 的纵截距为","options":["1","2","−1","1/2"],"answer":0,"analysis":"y=kx+b 中 b 为纵截距。","id":"sy-g2-c2-l1-q2"},{"type":"fill","level":"中档","stem":"过点 (1,2) 且斜率为 3 的直线方程是____（写成 y=kx+b 形式）","answer":"y=3x−1","analysis":"y−2=3(x−1)，整理得 y=3x−1。","id":"sy-g2-c2-l1-q3"},{"type":"fill","level":"中档","stem":"点 (1,1) 关于 x 轴对称的点的坐标是____","answer":"(1,−1)","analysis":"关于 x 轴对称时纵坐标取相反数。","id":"sy-g2-c2-l2-q3"},{"id":"sy-g2-c2-l1-e1","type":"essay","level":"简答","stem":"简答：写出直线斜率公式并说明斜率不存在的情形；说明倾斜角与斜率的关系。","ref":"k=(y₂−y₁)/(x₂−x₁)（x₁≠x₂）。x₁=x₂（倾斜角 90°）时斜率不存在。k=tanα，α∈[0,π)；α=90° 时 tanα 不存在。"},{"id":"sy-g2-c2-l1-e2","type":"essay","level":"简答","stem":"简答：写出直线方程的四种形式及各自适用条件。","ref":"点斜式 y−y₀=k(x−x₀)：已知一点与斜率（斜率存在）；斜截式 y=kx+b：已知斜率与纵截距；两点式：已知两点（横坐标不等且纵坐标不等）；一般式 Ax+By+C=0（A、B 不同时为 0，普适）。"}]},{"id":"sy-g2-c2-l2","name":"2.2 距离公式与对称问题","chapterId":"sy-g2-c2","chapterName":"直线和圆的方程","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"点 (3,4) 到原点的距离是","options":["5","7","25","√7"],"answer":0,"analysis":"√(9+16)=5。","id":"sy-g2-c2-l2-q1"},{"type":"choice","level":"基础","stem":"平行直线 y=x 与 y=x+1 之间的距离是","options":["√2/2","1","√2","1/2"],"answer":0,"analysis":"化为 x−y+1=0，d=1/√2=√2/2。","id":"sy-g2-c2-l2-q2"},{"type":"fill","level":"中档","stem":"点 (1,1) 关于 x 轴对称的点的坐标是____","answer":"(1,−1)","analysis":"关于 x 轴对称时纵坐标取相反数。","id":"sy-g2-c2-l2-q3"},{"type":"fill","level":"中档","stem":"过点 (1,2) 且斜率为 3 的直线方程是____（写成 y=kx+b 形式）","answer":"y=3x−1","analysis":"y−2=3(x−1)，整理得 y=3x−1。","id":"sy-g2-c2-l1-q3"},{"id":"sy-g2-c2-l2-e1","type":"essay","level":"简答","stem":"简答：写出点到直线的距离公式与两平行线间的距离公式。","ref":"点 (x₀,y₀) 到 Ax+By+C=0：d=|Ax₀+By₀+C|/√(A²+B²)。平行线 Ax+By+C₁=0 与 Ax+By+C₂=0：d=|C₁−C₂|/√(A²+B²)，须先把 x、y 系数化成相同。"},{"id":"sy-g2-c2-l2-e2","type":"essay","level":"简答","stem":"简答：说明点 (x₀,y₀) 关于直线 y=x 对称的点的求法，并举一例。","ref":"关于 y=x 对称：横纵坐标互换，(x₀,y₀)→(y₀,x₀)。例：(2,5) 关于 y=x 的对称点为 (5,2)。其他对称轴可用中点在对称轴上+连线垂直于对称轴联立求解。"}]},{"id":"sy-g2-c2-l3","name":"2.3 圆的方程与直线与圆","chapterId":"sy-g2-c2","chapterName":"直线和圆的方程","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"圆 x²+y²=4 的圆心与半径分别是","options":["(0,0)，2","(0,0)，4","(2,0)，2","(0,2)，2"],"answer":0,"analysis":"标准形式圆心原点，半径 r=2。","id":"sy-g2-c2-l3-q1"},{"type":"choice","level":"基础","stem":"圆 (x−1)²+(y+2)²=9 的圆心是","options":["(1,−2)","(−1,2)","(1,2)","(−1,−2)"],"answer":0,"analysis":"注意 y+2 对应圆心纵坐标 −2。","id":"sy-g2-c2-l3-q2"},{"type":"fill","level":"中档","stem":"直线 y=x+2 与圆 x²+y²=2 的位置关系是____（填\"相交\"\"相切\"或\"相离\"）","answer":"相切","analysis":"圆心到直线距离 d=2/√2=√2，等于半径，故相切。","id":"sy-g2-c2-l3-q3"},{"type":"fill","level":"中档","stem":"过点 (1,2) 且斜率为 3 的直线方程是____（写成 y=kx+b 形式）","answer":"y=3x−1","analysis":"y−2=3(x−1)，整理得 y=3x−1。","id":"sy-g2-c2-l1-q3"},{"id":"sy-g2-c2-l3-e1","type":"essay","level":"简答","stem":"简答：写出圆的标准方程与一般方程，并说明一般方程中 D²+E²−4F 的意义。","ref":"标准：(x−a)²+(y−b)²=r²；一般：x²+y²+Dx+Ey+F=0（配方可化标准式）。D²+E²−4F=4r²>0 表示圆；=0 表示点；<0 不表示任何图形。"},{"id":"sy-g2-c2-l3-e2","type":"essay","level":"简答","stem":"简答：说明判断直线与圆位置关系的两种方法，并比较优劣。","ref":"几何法：圆心距 d 与半径 r 比较（d<r 相交、=r 相切、>r 相离），计算量小、首选；代数法：联立方程用判别式 Δ（Δ>0 两交点、=0 相切、<0 相离），通用但运算量大。"}]}]},{"id":"sy-g2-c3","name":"圆锥曲线","book":"选择性必修第一册","grade":"高二","lessons":[{"id":"sy-g2-c3-l1","name":"3.1 椭圆的定义与性质","chapterId":"sy-g2-c3","chapterName":"圆锥曲线","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"椭圆 x²/25+y²/9=1 的离心率是","options":["4/5","3/5","5/4","9/25"],"answer":0,"analysis":"a=5，b=3，c=4，e=c/a=4/5。","id":"sy-g2-c3-l1-q1"},{"type":"choice","level":"基础","stem":"焦点在 x 轴上，a=5，c=3 的椭圆方程是","options":["x²/25+y²/16=1","x²/16+y²/25=1","x²/25+y²/9=1","x²/9+y²/25=1"],"answer":0,"analysis":"b²=a²−c²=16，长轴在 x 轴。","id":"sy-g2-c3-l1-q2"},{"type":"fill","level":"中档","stem":"椭圆上一点 P 到两焦点 F₁、F₂ 的距离之和为____（用 a 表示）","answer":"2a","analysis":"椭圆定义：|PF₁|+|PF₂|=2a。","id":"sy-g2-c3-l1-q3"},{"type":"fill","level":"中档","stem":"双曲线 x²/4−y²/5=1 的焦距为____","answer":"6","analysis":"c²=4+5=9，c=3，焦距 2c=6。","id":"sy-g2-c3-l2-q3"},{"id":"sy-g2-c3-l1-e1","type":"essay","level":"简答","stem":"简答：写出椭圆的定义、标准方程与 a、b、c 的关系式。","ref":"定义：到两定点距离之和为常数 2a（2a>2c）的点的轨迹。焦点在 x 轴：x²/a²+y²/b²=1（a>b>0）；关系：a²=b²+c²，2c 为焦距。"},{"id":"sy-g2-c3-l1-e2","type":"essay","level":"简答","stem":"简答：说明椭圆的离心率的定义及 e 的大小对椭圆形状的影响。","ref":"e=c/a∈(0,1)。e 越小越接近圆（c 相对越小），e 越接近 1 越扁。e=0 时退化为圆（c=0）。"}]},{"id":"sy-g2-c3-l2","name":"3.2 双曲线的定义与性质","chapterId":"sy-g2-c3","chapterName":"圆锥曲线","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"双曲线 x²/9−y²/16=1 的渐近线方程是","options":["y=±4x/3","y=±3x/4","y=±16x/9","y=±9x/16"],"answer":0,"analysis":"渐近线 y=±(b/a)x=±(4/3)x。","id":"sy-g2-c3-l2-q1"},{"type":"choice","level":"基础","stem":"双曲线的离心率 e 满足","options":["e>1","0<e<1","e=1","e<0"],"answer":0,"analysis":"双曲线 c>a，故 e=c/a>1。","id":"sy-g2-c3-l2-q2"},{"type":"fill","level":"中档","stem":"双曲线 x²/4−y²/5=1 的焦距为____","answer":"6","analysis":"c²=4+5=9，c=3，焦距 2c=6。","id":"sy-g2-c3-l2-q3"},{"type":"fill","level":"中档","stem":"椭圆上一点 P 到两焦点 F₁、F₂ 的距离之和为____（用 a 表示）","answer":"2a","analysis":"椭圆定义：|PF₁|+|PF₂|=2a。","id":"sy-g2-c3-l1-q3"},{"id":"sy-g2-c3-l2-e1","type":"essay","level":"简答","stem":"简答：写出双曲线的定义与标准方程，说明与椭圆方程中 a²、b² 关系的差别。","ref":"定义：到两定点距离之差的绝对值为常数 2a（0<2a<2c）。x²/a²−y²/b²=1（焦点在 x 轴）；双曲线中 c²=a²+b²，而椭圆是 a²=b²+c²，符号方向相反。"},{"id":"sy-g2-c3-l2-e2","type":"essay","level":"简答","stem":"简答：写出双曲线渐近线方程的求法，并说明离心率与渐近线斜率的关系。","ref":"x²/a²−y²/b²=1 的渐近线为 y=±(b/a)x（把 1 换成 0 解出）。e=√(1+b²/a²)，b/a 越大 e 越大，开口越开阔。"}]},{"id":"sy-g2-c3-l3","name":"3.3 抛物线的定义与性质","chapterId":"sy-g2-c3","chapterName":"圆锥曲线","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"抛物线 y²=8x 的准线方程是","options":["x=−2","x=2","y=−2","y=2"],"answer":0,"analysis":"2p=8，p=4，准线 x=−p/2=−2。","id":"sy-g2-c3-l3-q1"},{"type":"choice","level":"基础","stem":"抛物线 y²=2px（p>0）的焦点坐标是","options":["(p/2,0)","(p,0)","(0,p/2)","(−p/2,0)"],"answer":0,"analysis":"焦点在 x 轴正半轴，横坐标 p/2。","id":"sy-g2-c3-l3-q2"},{"type":"fill","level":"中档","stem":"抛物线 y²=4x 上一点 P(1,2) 到焦点的距离为____","answer":"2","analysis":"到焦点距离等于到准线 x=−1 的距离：1+1=2。","id":"sy-g2-c3-l3-q3"},{"type":"fill","level":"中档","stem":"椭圆上一点 P 到两焦点 F₁、F₂ 的距离之和为____（用 a 表示）","answer":"2a","analysis":"椭圆定义：|PF₁|+|PF₂|=2a。","id":"sy-g2-c3-l1-q3"},{"id":"sy-g2-c3-l3-e1","type":"essay","level":"简答","stem":"简答：写出抛物线 y²=2px（p>0）的焦点坐标与准线方程，并说明抛物线的定义。","ref":"焦点 (p/2,0)，准线 x=−p/2。定义：与定点（焦点）和定直线（准线）距离相等的点的轨迹（直线不经过焦点）。"},{"id":"sy-g2-c3-l3-e2","type":"essay","level":"简答","stem":"简答：说明抛物线的焦点弦的性质：\"焦点弦长最短为通径 2p\"。","ref":"过焦点垂直于对称轴的弦（通径）长为 2p，是最短的焦点弦；一般焦点弦两端点横坐标之积为定值 −p²/4（y²=2px 时）。"}]}]},{"id":"sy-g2-c4","name":"数列","book":"选择性必修第二册","grade":"高二","lessons":[{"id":"sy-g2-c4-l1","name":"4.1 等差数列","chapterId":"sy-g2-c4","chapterName":"数列","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"等差数列 a₁=2，d=3，则 a₅=","options":["14","15","12","17"],"answer":0,"analysis":"a₅=a₁+4d=2+12=14。","id":"sy-g2-c4-l1-q1"},{"type":"choice","level":"基础","stem":"若 a、b、c 成等差数列，则","options":["2b=a+c","b²=ac","b=a+c","a+b=c"],"answer":0,"analysis":"等差中项为两端之和的一半。","id":"sy-g2-c4-l1-q2"},{"type":"fill","level":"中档","stem":"等差数列中 a₃=7，a₇=15，则公差 d=____","answer":"2","analysis":"a₇−a₃=4d，8=4d，故 d=2。","id":"sy-g2-c4-l1-q3"},{"type":"fill","level":"中档","stem":"1/(1×2)+1/(2×3)+…+1/(9×10)=____","answer":"9/10","analysis":"裂项相消后剩 1−1/10=9/10。","id":"sy-g2-c4-l3-q3"},{"id":"sy-g2-c4-l1-e1","type":"essay","level":"简答","stem":"简答：写出等差数列的通项公式与前 n 项和公式，并说明判断等差数列的方法。","ref":"aₙ=a₁+(n−1)d；Sₙ=n(a₁+aₙ)/2=na₁+n(n−1)d/2。判定：aₙ₊₁−aₙ 为同一常数（定义法），或 2aₙ₊₁=aₙ+aₙ₊₂（中项法）。"},{"id":"sy-g2-c4-l1-e2","type":"essay","level":"简答","stem":"简答：说明等差数列前 n 项和 Sₙ 与 n 的函数关系及图象特征。","ref":"Sₙ=(d/2)n²+(a₁−d/2)n 是关于 n 的常数项为 0 的二次函数（d≠0 时），图象为抛物线上的离散点，开口由 d 决定。"}]},{"id":"sy-g2-c4-l2","name":"4.2 等比数列","chapterId":"sy-g2-c4","chapterName":"数列","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"等比数列 a₁=1，q=2，则 a₄=","options":["8","6","4","16"],"answer":0,"analysis":"a₄=a₁q³=8。","id":"sy-g2-c4-l2-q1"},{"type":"choice","level":"基础","stem":"若 a、b、c 成等比数列，则","options":["b²=ac","2b=a+c","b=ac","b²=a+c"],"answer":0,"analysis":"等比中项满足 b²=ac（同号）。","id":"sy-g2-c4-l2-q2"},{"type":"fill","level":"中档","stem":"等比数列 a₁=2，q=3，则 S₃=____","answer":"26","analysis":"S₃=2(1+3+9)=26。","id":"sy-g2-c4-l2-q3"},{"type":"fill","level":"中档","stem":"等差数列中 a₃=7，a₇=15，则公差 d=____","answer":"2","analysis":"a₇−a₃=4d，8=4d，故 d=2。","id":"sy-g2-c4-l1-q3"},{"id":"sy-g2-c4-l2-e1","type":"essay","level":"简答","stem":"简答：写出等比数列的通项公式与前 n 项和公式，并说明公比 q=1 时的特殊处理。","ref":"aₙ=a₁qⁿ⁻¹；q≠1 时 Sₙ=a₁(1−qⁿ)/(1−q)，q=1 时 Sₙ=na₁（求和公式分母 1−q 不能为 0，须分讨）。"},{"id":"sy-g2-c4-l2-e2","type":"essay","level":"简答","stem":"简答：说明等比数列各项均为正时，为什么取对数后成等差数列。","ref":"aₙ>0 时设 bₙ=lg aₙ，则 bₙ₊₁−bₙ=lg(aₙ₊₁/aₙ)=lg q 为常数，故 {bₙ} 是公差 lg q 的等差数列——指数运算与对数运算互逆的体现。"}]},{"id":"sy-g2-c4-l3","name":"4.3 通项与求和方法","chapterId":"sy-g2-c4","chapterName":"数列","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"等差数列通项公式为","options":["aₙ=a₁+(n−1)d","aₙ=a₁+nd","aₙ=a₁·dⁿ⁻¹","aₙ=n·d"],"answer":0,"analysis":"第 n 项比首项多加 n−1 个公差。","id":"sy-g2-c4-l3-q1"},{"type":"choice","level":"基础","stem":"裂项 1/[n(n+1)] 可写成","options":["1/n−1/(n+1)","1/n+1/(n+1)","1/n·1/(n+1)","n−(n+1)"],"answer":0,"analysis":"通分验证即可。","id":"sy-g2-c4-l3-q2"},{"type":"fill","level":"中档","stem":"1/(1×2)+1/(2×3)+…+1/(9×10)=____","answer":"9/10","analysis":"裂项相消后剩 1−1/10=9/10。","id":"sy-g2-c4-l3-q3"},{"type":"fill","level":"中档","stem":"等差数列中 a₃=7，a₇=15，则公差 d=____","answer":"2","analysis":"a₇−a₃=4d，8=4d，故 d=2。","id":"sy-g2-c4-l1-q3"},{"id":"sy-g2-c4-l3-e1","type":"essay","level":"简答","stem":"简答：叙述用\"累加法\"求形如 aₙ₊₁=aₙ+f(n) 的数列通项的步骤。","ref":"写出 a₂−a₁=f(1)，a₃−a₂=f(2)，…，aₙ−aₙ₋₁=f(n−1)；各式相加得 aₙ=a₁+∑f(k)（k=1 到 n−1），再验证 n=1 时成立。"},{"id":"sy-g2-c4-l3-e2","type":"essay","level":"简答","stem":"简答：说明裂项相消法求和的原理，并举 1/[n(n+1)] 型的例子。","ref":"把每项拆成两项之差，使和式中大部分项正负相消。1/[n(n+1)]=1/n−1/(n+1)，故前 n 项和=1−1/(n+1)=n/(n+1)。"}]}]},{"id":"sy-g2-c5","name":"导数及其应用","book":"选择性必修第二册","grade":"高二","lessons":[{"id":"sy-g2-c5-l1","name":"5.1 导数概念与切线","chapterId":"sy-g2-c5","chapterName":"导数及其应用","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"f(x)=x² 的导函数是","options":["2x","x","x²/2","2"],"answer":0,"analysis":"幂函数求导：(x²)′=2x。","id":"sy-g2-c5-l1-q1"},{"type":"choice","level":"基础","stem":"f(x)=x³，则 f′(1)=","options":["3","1","0","2"],"answer":0,"analysis":"f′(x)=3x²，代入 x=1 得 3。","id":"sy-g2-c5-l1-q2"},{"type":"fill","level":"中档","stem":"曲线 y=x² 在点 (1,1) 处的切线斜率为____","answer":"2","analysis":"k=f′(1)=2。","id":"sy-g2-c5-l1-q3"},{"type":"fill","level":"中档","stem":"f(x)=x³−3x 在 [0,2] 上的最小值为____","answer":"−2","analysis":"f(1)=−2 为极小值，与 f(0)=0、f(2)=2 比较得最小值 −2。","id":"sy-g2-c5-l3-q3"},{"id":"sy-g2-c5-l1-e1","type":"essay","level":"简答","stem":"简答：叙述导数的几何意义，并说明如何求曲线 y=f(x) 在点 (x₀,f(x₀)) 处的切线方程。","ref":"导数 f′(x₀) 是切线斜率。切线：y−f(x₀)=f′(x₀)(x−x₀)。注意切点必须在曲线上，切点坐标代入方程验证。"},{"id":"sy-g2-c5-l1-e2","type":"essay","level":"简答","stem":"简答：说明\"在某点处的导数\"与\"导函数\"的区别，并举瞬时速度的例子。","ref":"f′(x₀) 是函数在 x₀ 处的变化率（定值）；f′(x) 是导函数（随 x 变化）。例：位移 s=t²，t=1 时的瞬时速度 s′(1)=2 m/s 是定值，而任意时刻速度 v(t)=2t。"}]},{"id":"sy-g2-c5-l2","name":"5.2 单调性与极值","chapterId":"sy-g2-c5","chapterName":"导数及其应用","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"f(x)=x³−3x 的单调递减区间是","options":["(−1,1)","(−∞,−1)","(1,+∞)","R"],"answer":0,"analysis":"f′(x)=3x²−3<0 得 −1<x<1。","id":"sy-g2-c5-l2-q1"},{"type":"choice","level":"基础","stem":"在区间 I 上，若 f′(x)>0 恒成立，则 f(x) 在 I 上","options":["单调递增","单调递减","为常数","无单调性"],"answer":0,"analysis":"导数符号决定单调性。","id":"sy-g2-c5-l2-q2"},{"type":"fill","level":"中档","stem":"f(x)=x²−4x 的极小值为____","answer":"−4","analysis":"f′(x)=2x−4=0 得 x=2，f(2)=−4。","id":"sy-g2-c5-l2-q3"},{"type":"fill","level":"中档","stem":"f(x)=x³−3x 在 [0,2] 上的最小值为____","answer":"−2","analysis":"f(1)=−2 为极小值，与 f(0)=0、f(2)=2 比较得最小值 −2。","id":"sy-g2-c5-l3-q3"},{"id":"sy-g2-c5-l2-e1","type":"essay","level":"简答","stem":"简答：叙述用导数判断函数单调性的一般步骤，并举 f(x)=x³−3x 说明。","ref":"求定义域→求 f′(x)→解 f′(x)>0 得增区间、<0 得减区间。f′(x)=3x²−3>0 得 x>1 或 x<−1 为增区间，(−1,1) 为减区间。"},{"id":"sy-g2-c5-l2-e2","type":"essay","level":"简答","stem":"简答：说明极值与导数为零的关系，并举 f(x)=x³ 说明\"f′(x₀)=0 未必是极值点\"。","ref":"极值点是导数变号（左正右负为极大、左负右正为极小）的点。f(x)=x³ 的 f′(x)=3x² 在 x=0 为 0 但两侧不变号，故 x=0 不是极值点。"}]},{"id":"sy-g2-c5-l3","name":"5.3 闭区间最值与应用","chapterId":"sy-g2-c5","chapterName":"导数及其应用","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"f(x)=x² 在 [1,3] 上的最大值是","options":["9","1","4","6"],"answer":0,"analysis":"在 [1,3] 上递增，最大值在 x=3 处取到。","id":"sy-g2-c5-l3-q1"},{"type":"choice","level":"基础","stem":"求闭区间上函数最值时，需要比较","options":["端点函数值与极值","只需比较端点","只需比较极值","只需比较导数为零的点"],"answer":0,"analysis":"闭区间最值取端点值与极值中的最大、最小者。","id":"sy-g2-c5-l3-q2"},{"type":"fill","level":"中档","stem":"f(x)=x³−3x 在 [0,2] 上的最小值为____","answer":"−2","analysis":"f(1)=−2 为极小值，与 f(0)=0、f(2)=2 比较得最小值 −2。","id":"sy-g2-c5-l3-q3"},{"type":"fill","level":"中档","stem":"曲线 y=x² 在点 (1,1) 处的切线斜率为____","answer":"2","analysis":"k=f′(1)=2。","id":"sy-g2-c5-l1-q3"},{"id":"sy-g2-c5-l3-e1","type":"essay","level":"简答","stem":"简答：叙述求 f(x) 在闭区间 [a,b] 上最值的步骤。","ref":"求 f′(x) 并解出极值点→计算区间内极值与端点值 f(a)、f(b)→比较大小，最大者为最大值，最小者为最小值。"},{"id":"sy-g2-c5-l3-e2","type":"essay","level":"简答","stem":"简答：举一个用导数解决实际优化问题的例子（如用料最省、利润最大），并说明建模步骤。","ref":"例：矩形周长一定求面积最大。步骤：设变量（一边长 x）→列目标函数 S(x) 与定义域→求导找极值→比较或由唯一极值确定最值→作答。"}]}]},{"id":"sy-g2-c6","name":"计数原理","book":"选择性必修第三册","grade":"高二","lessons":[{"id":"sy-g2-c6-l1","name":"6.1 分类加法与分步乘法","chapterId":"sy-g2-c6","chapterName":"计数原理","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"从甲地到乙地有 3 条路，乙地到丙地有 2 条路，则甲经乙到丙共有走法","options":["6 种","5 种","3 种","2 种"],"answer":0,"analysis":"分步计数用乘法：3×2=6。","id":"sy-g2-c6-l1-q1"},{"type":"choice","level":"基础","stem":"完成一件事有几类互不相同的办法，各类办法数相加，用的是","options":["分类加法计数原理","分步乘法计数原理","排列数公式","组合数公式"],"answer":0,"analysis":"分类用加法，分步用乘法。","id":"sy-g2-c6-l1-q2"},{"type":"fill","level":"中档","stem":"从 3 个不同元素中取 2 个的排列数 A(3,2)=____","answer":"6","analysis":"A(3,2)=3×2=6。","id":"sy-g2-c6-l1-q3"},{"type":"fill","level":"中档","stem":"(x+1)⁴ 展开式中 x² 的系数为____","answer":"6","analysis":"x² 对应 C(4,2)x²·1²=6x²。","id":"sy-g2-c6-l2-q3"},{"id":"sy-g2-c6-l1-e1","type":"essay","level":"简答","stem":"简答：说明分类加法计数原理与分步乘法计数原理的区别及判断标准。","ref":"加法原理：各类方案互斥、任完成一类即完成事情，总数为各类相加；乘法原理：须依次完成各步骤，总数为各步相乘。判断标准：完成任务\"或\"用加、\"且（分步）\"用乘。"},{"id":"sy-g2-c6-l1-e2","type":"essay","level":"简答","stem":"简答：说明排列与组合的区别，并举同一情境的排列数与组合数。","ref":"排列与顺序有关，组合与顺序无关。例：从 5 人中选 3 人参加活动（不计顺序）为组合 C₅³=10；选 3 人分别任三个不同职务（有顺序）为排列 A₅³=60。"}]},{"id":"sy-g2-c6-l2","name":"6.2 二项式定理","chapterId":"sy-g2-c6","chapterName":"计数原理","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"(a+b)ⁿ 展开式的第 k+1 项为","options":["C(n,k)aⁿ⁻ᵏbᵏ","C(n,k)aᵏbⁿ⁻ᵏ","C(n,k)aⁿbᵏ","aⁿ⁻ᵏbᵏ"],"answer":0,"analysis":"通项 T(k+1)=C(n,k)a^(n−k)b^k。","id":"sy-g2-c6-l2-q1"},{"type":"choice","level":"基础","stem":"(1+x)³ 展开式中各项系数之和为","options":["8","7","4","6"],"answer":0,"analysis":"令 x=1 得 2³=8。","id":"sy-g2-c6-l2-q2"},{"type":"fill","level":"中档","stem":"(x+1)⁴ 展开式中 x² 的系数为____","answer":"6","analysis":"x² 对应 C(4,2)x²·1²=6x²。","id":"sy-g2-c6-l2-q3"},{"type":"fill","level":"中档","stem":"从 3 个不同元素中取 2 个的排列数 A(3,2)=____","answer":"6","analysis":"A(3,2)=3×2=6。","id":"sy-g2-c6-l1-q3"},{"id":"sy-g2-c6-l2-e1","type":"essay","level":"简答","stem":"简答：写出二项式定理与通项公式，并说明如何求指定项的系数。","ref":"(a+b)ⁿ=ΣCₙᵏaⁿ⁻ᵏbᵏ（k=0..n），通项 Tₖ₊₁=Cₙᵏaⁿ⁻ᵏbᵏ。求指定项：令通项中字母次数等于目标次数解出 k，再代入计算。"},{"id":"sy-g2-c6-l2-e2","type":"essay","level":"简答","stem":"简答：说明二项式系数 Cₙᵏ 与该项系数的区别，并举 (1+2x)ⁿ 中的例子。","ref":"二项式系数是 Cₙᵏ；项的系数还包含字母上的数字因子。例 (1+2x)⁵ 中含 x² 的项：T₃=C₅²(2x)²=10·4x²=40x²，二项式系数 C₅²=10，而系数为 40。"}]}]},{"id":"sy-g2-c7","name":"随机变量及其分布","book":"选择性必修第三册","grade":"高二","lessons":[{"id":"sy-g2-c7-l1","name":"7.1 离散型随机变量与分布列","chapterId":"sy-g2-c7","chapterName":"随机变量及其分布","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"离散型随机变量分布列中各概率之和必须等于","options":["1","0","样本容量","期望"],"answer":0,"analysis":"所有可能取值的概率和为 1。","id":"sy-g2-c7-l1-q1"},{"type":"choice","level":"基础","stem":"E(X) 的计算公式是","options":["Σxᵢpᵢ","Σpᵢ","Σxᵢ","max xᵢ"],"answer":0,"analysis":"期望为取值与对应概率乘积之和。","id":"sy-g2-c7-l1-q2"},{"type":"fill","level":"中档","stem":"X 只取 0、1，且 P(X=1)=0.3，则 E(X)=____","answer":"0.3","analysis":"E(X)=0×0.7+1×0.3=0.3。","id":"sy-g2-c7-l1-q3"},{"type":"fill","level":"中档","stem":"若 X~N(2,σ²)，则 P(X<2)=____","answer":"0.5","analysis":"正态曲线关于 x=2 对称，左右各占一半。","id":"sy-g2-c7-l3-q3"},{"id":"sy-g2-c7-l1-e1","type":"essay","level":"简答","stem":"简答：叙述离散型随机变量分布列的两条基本性质，并说明其用途。","ref":"①pᵢ≥0（i=1,2,…,n）；②Σpᵢ=1。用途：求出概率后验证是否构成分布列；可利用 Σ=1 求未知参数。"},{"id":"sy-g2-c7-l1-e2","type":"essay","level":"简答","stem":"简答：写出期望 E(X) 的定义，并说明期望与\"平均数\"的关系。","ref":"E(X)=Σxᵢpᵢ，即以概率为权重的加权平均，反映随机变量取值的平均水平。长期重复试验中取值的平均稳定于期望。"}]},{"id":"sy-g2-c7-l2","name":"7.2 二项分布与期望方差","chapterId":"sy-g2-c7","chapterName":"随机变量及其分布","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"若 X~B(n,p)，则 E(X)=","options":["np","n/p","p/n","n(1−p)"],"answer":0,"analysis":"二项分布期望为 np。","id":"sy-g2-c7-l2-q1"},{"type":"choice","level":"基础","stem":"若 X~B(n,p)，则 D(X)=","options":["np(1−p)","np","n²p","p(1−p)"],"answer":0,"analysis":"二项分布方差公式。","id":"sy-g2-c7-l2-q2"},{"type":"fill","level":"中档","stem":"X~B(10,0.2)，则 E(X)=____","answer":"2","analysis":"E(X)=10×0.2=2。","id":"sy-g2-c7-l2-q3"},{"type":"fill","level":"中档","stem":"若 X~N(2,σ²)，则 P(X<2)=____","answer":"0.5","analysis":"正态曲线关于 x=2 对称，左右各占一半。","id":"sy-g2-c7-l3-q3"},{"id":"sy-g2-c7-l2-e1","type":"essay","level":"简答","stem":"简答：写出二项分布 X~B(n,p) 的概率公式、期望与方差公式。","ref":"P(X=k)=Cₙᵏpᵏ(1−p)ⁿ⁻ᵏ；E(X)=np，D(X)=np(1−p)。适用于 n 次独立重复试验中\"成功\"次数。"},{"id":"sy-g2-c7-l2-e2","type":"essay","level":"简答","stem":"简答：说明方差 D(X) 的意义，并举两个期望相同但方差不同的例子。","ref":"方差反映取值的离散（波动）程度，D(X) 越大越不稳定。例：甲、乙射击平均命中数都是 0.8，甲波动小（方差小）则成绩更稳定；应选方差小的选手。"}]},{"id":"sy-g2-c7-l3","name":"7.3 正态分布","chapterId":"sy-g2-c7","chapterName":"随机变量及其分布","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"正态曲线关于直线","options":["x=μ 对称","x=σ 对称","y 轴对称","原点对称"],"answer":0,"analysis":"正态分布由均值 μ 决定对称轴。","id":"sy-g2-c7-l3-q1"},{"type":"choice","level":"基础","stem":"标准正态分布的参数为","options":["μ=0，σ=1","μ=1，σ=0","μ=1，σ=1","μ=0，σ=0"],"answer":0,"analysis":"标准正态记为 N(0,1)。","id":"sy-g2-c7-l3-q2"},{"type":"fill","level":"中档","stem":"若 X~N(2,σ²)，则 P(X<2)=____","answer":"0.5","analysis":"正态曲线关于 x=2 对称，左右各占一半。","id":"sy-g2-c7-l3-q3"},{"type":"fill","level":"中档","stem":"X~B(10,0.2)，则 E(X)=____","answer":"2","analysis":"E(X)=10×0.2=2。","id":"sy-g2-c7-l2-q3"},{"id":"sy-g2-c7-l3-e1","type":"essay","level":"简答","stem":"简答：写出正态分布密度曲线的对称轴、3σ 原则的含义。","ref":"曲线关于 x=μ 对称，μ 决定位置、σ 决定\"高瘦/矮胖\"。3σ 原则：P(μ−σ<X<μ+σ)≈68.3%，P(μ−2σ,μ+2σ)≈95.4%，P(μ−3σ,μ+3σ)≈99.7%。"},{"id":"sy-g2-c7-l3-e2","type":"essay","level":"简答","stem":"简答：说明利用正态分布对称性求概率的方法，并举 X~N(2,σ²) 时 P(X<2) 的例子。","ref":"利用曲线关于 x=μ 对称：左右两侧概率各半、P(X<μ+kσ)=1−P(X<μ−kσ)。例：X~N(2,σ²) 时 P(X<2)=0.5（对称轴处）。"}]}]},{"id":"sy-g2-c8","name":"成对数据的统计分析","book":"选择性必修第三册","grade":"高二","lessons":[{"id":"sy-g2-c8-l1","name":"8.1 相关关系与回归直线","chapterId":"sy-g2-c8","chapterName":"成对数据的统计分析","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"样本相关系数 r 的取值范围是","options":["[−1,1]","[0,1]","R","[−1,0]"],"answer":0,"analysis":"相关系数绝对值不超过 1。","id":"sy-g2-c8-l1-q1"},{"type":"choice","level":"基础","stem":"若 r>0，则两个变量","options":["正相关","负相关","不相关","完全相关"],"answer":0,"analysis":"r 的符号反映相关方向。","id":"sy-g2-c8-l1-q2"},{"type":"fill","level":"中档","stem":"经验回归直线一定经过的点的坐标是____","answer":"(x̄,ȳ)","analysis":"回归直线过样本中心点。","id":"sy-g2-c8-l1-q3"},{"type":"fill","level":"中档","stem":"χ² 公式中分子含有的式子是____（用 a、b、c、d 表示，写出关键部分）","answer":"(ad−bc)²","analysis":"χ²=n(ad−bc)²/[(a+b)(c+d)(a+c)(b+d)]。","id":"sy-g2-c8-l2-q3"},{"id":"sy-g2-c8-l1-e1","type":"essay","level":"简答","stem":"简答：说明散点图与相关系数 r 在判断相关关系中的作用。","ref":"散点图直观展示两变量是否线性相关及方向；r∈[−1,1]，|r| 越接近 1 线性相关越强，r>0 正相关、r<0 负相关。"},{"id":"sy-g2-c8-l1-e2","type":"essay","level":"简答","stem":"简答：叙述回归直线 ŷ=bx+a 中 a、b 的最小二乘法求法及回归直线经过的定点。","ref":"b=Σ(xᵢ−x̄)(yᵢ−ȳ)/Σ(xᵢ−x̄)²，a=ȳ−bx̄。回归直线必过样本中心点 (x̄,ȳ)。"}]},{"id":"sy-g2-c8-l2","name":"8.2 独立性检验","chapterId":"sy-g2-c8","chapterName":"成对数据的统计分析","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"独立性检验中，χ² 的值越大，说明","options":["两个分类变量有关的把握越大","两个变量一定无关","样本容量越小","相关性越弱"],"answer":0,"analysis":"χ² 越大，拒绝\"无关\"的依据越强。","id":"sy-g2-c8-l2-q1"},{"type":"choice","level":"基础","stem":"独立性检验使用的表格称为","options":["2×2 列联表","频率分布表","分布列","回归表"],"answer":0,"analysis":"两个分类变量各取两个值，构成 2×2 列联表。","id":"sy-g2-c8-l2-q2"},{"type":"fill","level":"中档","stem":"χ² 公式中分子含有的式子是____（用 a、b、c、d 表示，写出关键部分）","answer":"(ad−bc)²","analysis":"χ²=n(ad−bc)²/[(a+b)(c+d)(a+c)(b+d)]。","id":"sy-g2-c8-l2-q3"},{"type":"fill","level":"中档","stem":"经验回归直线一定经过的点的坐标是____","answer":"(x̄,ȳ)","analysis":"回归直线过样本中心点。","id":"sy-g2-c8-l1-q3"},{"id":"sy-g2-c8-l2-e1","type":"essay","level":"简答","stem":"简答：叙述独立性检验的基本思路及 χ²（卡方）统计量大小与结论的关系。","ref":"用 2×2 列联表计算 χ²，与临界值比较：χ² 越大，\"两变量有关\"的把握越大；超过临界值则认为有关（在相应置信水平下）。注意：检验结论是概率意义上的相关，不是因果。"},{"id":"sy-g2-c8-l2-e2","type":"essay","level":"简答","stem":"简答：说明独立性检验与反证法的异同。","ref":"相同：都是\"假设—检验—推翻或接受\"的思路。不同：反证法在逻辑上必然推翻（确定性）；独立性检验由样本推断，以显著性水平表达把握大小（随机性，可能犯错）。"}]}]}],"高三一轮":[{"id":"sy-g1-c1","name":"集合与常用逻辑用语","book":"必修第一册","grade":"高一","lessons":[{"id":"sy-g1-c1-l1","name":"1.1 集合的概念与表示","chapterId":"sy-g1-c1","chapterName":"集合与常用逻辑用语","book":"必修第一册","grade":"高一","video":"https://2119944279174578176.app.workbuddy.host/videos/sy-g1-c1-l1.mp4?sharecode=IVGNI3FZYP","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"下列各组对象能组成集合的是","options":["所有的正三角形","著名的数学家","很漂亮的花","很大的数"],"answer":0,"analysis":"集合的元素须确定；\"著名\"\"漂亮\"\"很大\"都无明确标准。","id":"sy-g1-c1-l1-q1"},{"type":"choice","level":"基础","stem":"方程 x²−1=0 的解集用列举法表示为","options":["{−1,1}","{1}","{−1}","∅"],"answer":0,"analysis":"两根 −1 与 1 都要写出。","id":"sy-g1-c1-l1-q2"},{"type":"fill","level":"中档","stem":"若 1∈{a, a²}，则 a=____","answer":"−1","analysis":"a=1 时元素重复不满足互异性；a²=1 得 a=±1，排除 a=1，故 a=−1。","id":"sy-g1-c1-l1-q3"},{"type":"fill","level":"中档","stem":"全集 U={1,2,3,4}，A={1,3}，则 ∁ᵤA=____","answer":"{2,4}","analysis":"补集为 U 中不属于 A 的元素。","id":"sy-g1-c1-l2-q3"},{"id":"sy-g1-c1-l1-e1","type":"essay","level":"简答","stem":"简答：判断下列对象能否构成集合，并说明理由：(1) 本班身高超过 1.7 米的同学；(2) 本班个子高的同学。","ref":"(1) 能，\"身高超过 1.7 米\"标准明确、元素确定；(2) 不能，\"个子高\"没有明确标准，元素不确定。"},{"id":"sy-g1-c1-l1-e2","type":"essay","level":"简答","stem":"简答：用描述法表示不等式 2x−1>3 的解集，并说明列举法与描述法各自的适用情形。","ref":"解集为 {x|x>2}。列举法适合元素个数少且有限（如有限集合）；描述法适合元素较多或有共同特征的集合（如无限集、区间型集合）。"}]},{"id":"sy-g1-c1-l2","name":"1.2 集合间的基本关系与运算","chapterId":"sy-g1-c1","chapterName":"集合与常用逻辑用语","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"A={1,2}，B={2,3}，则 A∩B=","options":["{2}","{1,2}","{2,3}","{1,2,3}"],"answer":0,"analysis":"交集只保留公共元素 2。","id":"sy-g1-c1-l2-q1"},{"type":"choice","level":"基础","stem":"A={1,2}，B={2,3}，则 A∪B=","options":["{2}","{1,2,3}","{1,3}","{1,2}"],"answer":1,"analysis":"并集合并去重，得 {1,2,3}。","id":"sy-g1-c1-l2-q2"},{"type":"fill","level":"中档","stem":"全集 U={1,2,3,4}，A={1,3}，则 ∁ᵤA=____","answer":"{2,4}","analysis":"补集为 U 中不属于 A 的元素。","id":"sy-g1-c1-l2-q3"},{"type":"fill","level":"中档","stem":"若 1∈{a, a²}，则 a=____","answer":"−1","analysis":"a=1 时元素重复不满足互异性；a²=1 得 a=±1，排除 a=1，故 a=−1。","id":"sy-g1-c1-l1-q3"},{"id":"sy-g1-c1-l2-e1","type":"essay","level":"简答","stem":"简答：已知 A={1,2,3}，写出 A 的所有子集，并说明为什么不能漏掉空集。","ref":"子集：∅、{1}、{2}、{3}、{1,2}、{1,3}、{2,3}、{1,2,3}（其中真子集除 {1,2,3} 外共 7 个）。空集是任何集合的子集，定义如此，漏掉会少解。"},{"id":"sy-g1-c1-l2-e2","type":"essay","level":"简答","stem":"简答：说明 A∩B、A∪B、∁ᵤA 三种运算的结果与韦恩图阴影区域的对应关系。","ref":"A∩B 是两集合公共部分；A∪B 是两集合合并后的全部部分；∁ᵤA 是全集 U 中除去 A 剩下的部分。画图时分别涂公共区、并集整体、A 外区域。"}]},{"id":"sy-g1-c1-l3","name":"1.3 充分条件与全称量词","chapterId":"sy-g1-c1","chapterName":"集合与常用逻辑用语","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"\"x>0\" 是 \"x²>0\" 的","options":["充分不必要条件","必要不充分条件","充要条件","既不充分也不必要条件"],"answer":0,"analysis":"x>0 必有 x²>0；x=−1 时 x²>0 但 x<0，反向不成立。","id":"sy-g1-c1-l3-q1"},{"type":"choice","level":"基础","stem":"命题 \"∀x∈R，x²+1>0\" 的否定是","options":["∃x∈R，x²+1≤0","∀x∈R，x²+1≤0","∃x∈R，x²+1>0","∃x∈R，x²+1<0"],"answer":0,"analysis":"全称命题的否定：量词改存在，结论取反（\">\" 的否定是 \"≤\"）。","id":"sy-g1-c1-l3-q2"},{"type":"fill","level":"中档","stem":"\"x>3\" 是 \"x>1\" 的____条件（填\"充分不必要\"\"必要不充分\"\"充要\"\"既不充分也不必要\"）","answer":"充分不必要","analysis":"x>3⇒x>1；反之取 x=2 不成立。","id":"sy-g1-c1-l3-q3"},{"type":"fill","level":"中档","stem":"若 1∈{a, a²}，则 a=____","answer":"−1","analysis":"a=1 时元素重复不满足互异性；a²=1 得 a=±1，排除 a=1，故 a=−1。","id":"sy-g1-c1-l1-q3"},{"id":"sy-g1-c1-l3-e1","type":"essay","level":"简答","stem":"简答：说明判断 \"p 是 q 的充分条件\" 的集合方法，并举例。","ref":"设 p 对应集合 A、q 对应集合 B，若 A⊆B 则 p 是 q 的充分条件。例：p: x>2，q: x>0，{x|x>2}⊆{x|x>0}，故 p 是 q 的充分条件。"},{"id":"sy-g1-c1-l3-e2","type":"essay","level":"简答","stem":"简答：写出 \"∃x∈R，x²−2x+3<0\" 的否定，并判断其真假。","ref":"否定为 \"∀x∈R，x²−2x+3≥0\"。因 Δ=(−2)²−4×3=−8<0，开口向上恒正，故该全称命题为真。"}]}]},{"id":"sy-g1-c2","name":"一元二次函数、方程和不等式","book":"必修第一册","grade":"高一","lessons":[{"id":"sy-g1-c2-l1","name":"2.1 等式性质与不等式性质","chapterId":"sy-g1-c2","chapterName":"一元二次函数、方程和不等式","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"若 a>b，则下列一定成立的是","options":["a−3>b−3","a²>b²","1/a<1/b","ac>bc"],"answer":0,"analysis":"不等式两边同减同一个数，方向不变；其余选项在负数、c≤0 时不成立。","id":"sy-g1-c2-l1-q1"},{"type":"choice","level":"基础","stem":"若 a>b，c>0，则","options":["ac>bc","ac<bc","a/c<b/c","大小不确定"],"answer":0,"analysis":"两边同乘正数 c，不等号方向不变。","id":"sy-g1-c2-l1-q2"},{"type":"fill","level":"中档","stem":"已知 1<x<3，2<y<4，则 x−y 的取值范围是____","answer":"(−3,1)","analysis":"x−y=x+(−y)，而 −4<−y<−2，同向相加得 −3<x−y<1。","id":"sy-g1-c2-l1-q3"},{"type":"fill","level":"中档","stem":"不等式 x²+2x−3≤0 的整数解共有____个","answer":"5","analysis":"解得 −3≤x≤1，整数为 −3,−2,−1,0,1，共 5 个。","id":"sy-g1-c2-l2-q3"},{"id":"sy-g1-c2-l1-e1","type":"essay","level":"简答","stem":"简答：举例说明 \"a>b 时 a²>b² 不一定成立\" 的反例，并指出比较大小的一般方法。","ref":"反例：a=1，b=−2，则 a>b 但 a²=1<b²=4。比较大小一般用作差法：作差→变形（因式分解、配方）→判断符号。"},{"id":"sy-g1-c2-l1-e2","type":"essay","level":"简答","stem":"简答：已知 a>b>0，c<d<0，简述证明 ac<bd 的思路。","ref":"由 c<d<0 得 −c>−d>0；又 a>b>0，同向正数不等式相乘得 −ac>−bd，两边同乘 −1 变号得 ac<bd。"}]},{"id":"sy-g1-c2-l2","name":"2.2 一元二次不等式","chapterId":"sy-g1-c2","chapterName":"一元二次函数、方程和不等式","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"不等式 x²−3x+2<0 的解集是","options":["1<x<2","x<1 或 x>2","−2<x<−1","全体实数"],"answer":0,"analysis":"因式分解 (x−1)(x−2)<0，小于取两根之间。","id":"sy-g1-c2-l2-q1"},{"type":"choice","level":"基础","stem":"不等式 −x²+4x−3≥0 的解集是","options":["1≤x≤3","x≤1 或 x≥3","−3≤x≤−1","空集"],"answer":0,"analysis":"两边乘 −1 得 x²−4x+3≤0，即 (x−1)(x−3)≤0，得 1≤x≤3。","id":"sy-g1-c2-l2-q2"},{"type":"fill","level":"中档","stem":"不等式 x²+2x−3≤0 的整数解共有____个","answer":"5","analysis":"解得 −3≤x≤1，整数为 −3,−2,−1,0,1，共 5 个。","id":"sy-g1-c2-l2-q3"},{"type":"fill","level":"中档","stem":"已知 1<x<3，2<y<4，则 x−y 的取值范围是____","answer":"(−3,1)","analysis":"x−y=x+(−y)，而 −4<−y<−2，同向相加得 −3<x−y<1。","id":"sy-g1-c2-l1-q3"},{"id":"sy-g1-c2-l2-e1","type":"essay","level":"简答","stem":"简答：叙述解一元二次不等式的一般步骤，并以 x²−x−6>0 为例说明。","ref":"步骤：化二次项系数为正→求对应方程的根→结合开口方向写解集。本例分解为 (x−2)(x+3)>0，开口向上，大于取两边，解集为 x<−3 或 x>2。"},{"id":"sy-g1-c2-l2-e2","type":"essay","level":"简答","stem":"简答：不等式 ax²+bx+c<0 恒成立的条件是什么？分情况说明。","ref":"a=0 时须 b=0 且 c<0；a≠0 时须 a<0 且 Δ=b²−4ac<0（开口向下且与 x 轴无交点，图像全在 x 轴下方）。"}]},{"id":"sy-g1-c2-l3","name":"2.3 基本不等式","chapterId":"sy-g1-c2","chapterName":"一元二次函数、方程和不等式","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"x>0 时，x+1/x 的最小值为","options":["1","2","4","不存在"],"answer":1,"analysis":"x+1/x≥2√(x·1/x)=2，当 x=1 时取等。","id":"sy-g1-c2-l3-q1"},{"type":"choice","level":"基础","stem":"x>0，y>0，x+y=4，则 xy 的最大值为","options":["2","4","8","16"],"answer":1,"analysis":"xy≤((x+y)/2)²=4，x=y=2 时取等。","id":"sy-g1-c2-l3-q2"},{"type":"fill","level":"中档","stem":"x>1 时，x+1/(x−1) 的最小值为____","answer":"3","analysis":"凑项：(x−1)+1/(x−1)+1≥2+1=3，当 x=2 时取等。","id":"sy-g1-c2-l3-q3"},{"type":"fill","level":"中档","stem":"已知 1<x<3，2<y<4，则 x−y 的取值范围是____","answer":"(−3,1)","analysis":"x−y=x+(−y)，而 −4<−y<−2，同向相加得 −3<x−y<1。","id":"sy-g1-c2-l1-q3"},{"id":"sy-g1-c2-l3-e1","type":"essay","level":"简答","stem":"简答：用基本不等式求最值时为什么要验证\"一正、二定、三相等\"？各举一个不满足的情形。","ref":"不满足任一条最值结论就不成立：一正——x<0 时不能直接用；二定——积或和不是定值则取不到；三相等——等号条件无解（如 x+1/x² 类型取等方程无实根）时最值不存在，须另求。"},{"id":"sy-g1-c2-l3-e2","type":"essay","level":"简答","stem":"简答：已知 x>0，说明求 x+4/x 最小值的完整过程，并指出等号成立条件。","ref":"x+4/x≥2√(x·4/x)=4，当且仅当 x=4/x 即 x=2 时取等，最小值为 4。关键：积为定值 4、两项均为正、等号可取。"}]}]},{"id":"sy-g1-c3","name":"函数的概念与性质","book":"必修第一册","grade":"高一","lessons":[{"id":"sy-g1-c3-l1","name":"3.1 函数的概念与表示","chapterId":"sy-g1-c3","chapterName":"函数的概念与性质","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"函数 f(x)=1/(x−1) 的定义域是","options":["x≠1","x>1","x≠0","全体实数"],"answer":0,"analysis":"分母不为零，故 x≠1。","id":"sy-g1-c3-l1-q1"},{"type":"choice","level":"基础","stem":"函数 f(x)=√(x+2) 的定义域是","options":["x≥−2","x>−2","x≤−2","全体实数"],"answer":0,"analysis":"被开方数非负：x+2≥0。","id":"sy-g1-c3-l1-q2"},{"type":"fill","level":"中档","stem":"f(x)=2x+1，则 f(f(1))=____","answer":"7","analysis":"f(1)=3，再代入得 f(3)=7。","id":"sy-g1-c3-l1-q3"},{"type":"fill","level":"中档","stem":"f(x) 为奇函数且 f(2)=3，则 f(−2)=____","answer":"−3","analysis":"奇函数满足 f(−x)=−f(x)。","id":"sy-g1-c3-l3-q3"},{"id":"sy-g1-c3-l1-e1","type":"essay","level":"简答","stem":"简答：同一函数的判断标准是什么？判断 f(x)=x 与 g(x)=√(x²) 是否为同一函数。","ref":"标准：定义域与对应关系都相同（值域不必直接比较）。g(x)=√(x²)=|x|，当 x<0 时 g(x)=−x≠x，对应关系不同，故不是同一函数。"},{"id":"sy-g1-c3-l1-e2","type":"essay","level":"简答","stem":"简答：求 f(x)=1/(x−2)+√(x+1) 的定义域，并写出求定义域的一般依据。","ref":"须 x−2≠0 且 x+1≥0，得 x≥−1 且 x≠2，即 [−1,2)∪(2,+∞)。依据：分母不为零、被开方数非负、实际意义等。"}]},{"id":"sy-g1-c3-l2","name":"3.2 单调性与最值","chapterId":"sy-g1-c3","chapterName":"函数的概念与性质","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"函数 f(x)=−2x+3 在 R 上","options":["单调递减","单调递增","先增后减","不具单调性"],"answer":0,"analysis":"一次函数斜率 −2<0，故单调递减。","id":"sy-g1-c3-l2-q1"},{"type":"choice","level":"基础","stem":"函数 f(x)=x²−2x 的单调递增区间是","options":["[1,+∞)","(−∞,1]","R","(0,+∞)"],"answer":0,"analysis":"对称轴 x=1，开口向上，右半支递增。","id":"sy-g1-c3-l2-q2"},{"type":"fill","level":"中档","stem":"f(x)=x²−4x+1 在 [0,3] 上的最小值为____","answer":"−3","analysis":"对称轴 x=2∈[0,3]，最小值 f(2)=−3。","id":"sy-g1-c3-l2-q3"},{"type":"fill","level":"中档","stem":"f(x)=2x+1，则 f(f(1))=____","answer":"7","analysis":"f(1)=3，再代入得 f(3)=7。","id":"sy-g1-c3-l1-q3"},{"id":"sy-g1-c3-l2-e1","type":"essay","level":"简答","stem":"简答：叙述用定义证明 f(x) 在区间 D 上单调递增的规范步骤。","ref":"四步：取值（任取 x₁<x₂∈D）→作差 f(x₁)−f(x₂)→变形（因式分解、通分，定号）→结论（差小于 0，故递增）。"},{"id":"sy-g1-c3-l2-e2","type":"essay","level":"简答","stem":"简答：说明函数 y=x+1/x（x>0）的单调区间及最值情况。","ref":"在 (0,1) 上递减，在 [1,+∞) 上递增；x=1 时取得最小值 2；无最大值。可由对勾函数图像或定义证明。"}]},{"id":"sy-g1-c3-l3","name":"3.3 奇偶性","chapterId":"sy-g1-c3","chapterName":"函数的概念与性质","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"f(x)=x³ 是","options":["奇函数","偶函数","既奇又偶","非奇非偶"],"answer":0,"analysis":"f(−x)=−x³=−f(x)，定义域 R 关于原点对称。","id":"sy-g1-c3-l3-q1"},{"type":"choice","level":"基础","stem":"f(x)=x²+1 是","options":["偶函数","奇函数","既奇又偶","非奇非偶"],"answer":0,"analysis":"f(−x)=f(x)，故为偶函数。","id":"sy-g1-c3-l3-q2"},{"type":"fill","level":"中档","stem":"f(x) 为奇函数且 f(2)=3，则 f(−2)=____","answer":"−3","analysis":"奇函数满足 f(−x)=−f(x)。","id":"sy-g1-c3-l3-q3"},{"type":"fill","level":"中档","stem":"f(x)=2x+1，则 f(f(1))=____","answer":"7","analysis":"f(1)=3，再代入得 f(3)=7。","id":"sy-g1-c3-l1-q3"},{"id":"sy-g1-c3-l3-e1","type":"essay","level":"简答","stem":"简答：叙述奇函数的定义，说明奇函数图像的特征及 f(0) 的取值要求。","ref":"定义：对定义域内任意 x，f(−x)=−f(x)。图像关于原点对称；若 0 在定义域内，则必有 f(0)=0（代 x=0 得 f(0)=−f(0)）。"},{"id":"sy-g1-c3-l3-e2","type":"essay","level":"简答","stem":"简答：判断 f(x)=x³+x 的奇偶性并证明；说明奇函数在对称区间上单调性的关系。","ref":"f(−x)=(−x)³+(−x)=−x³−x=−f(x)，且定义域为 R，故为奇函数。奇函数在对称区间上单调性相同（同增同减）。"}]}]},{"id":"sy-g1-c4","name":"指数函数与对数函数","book":"必修第一册","grade":"高一","lessons":[{"id":"sy-g1-c4-l1","name":"4.1 指数运算与指数函数","chapterId":"sy-g1-c4","chapterName":"指数函数与对数函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"2³×2⁻¹ 的值是","options":["2","4","8","16"],"answer":1,"analysis":"同底数幂相乘指数相加：2^(3−1)=2²=4。","id":"sy-g1-c4-l1-q1"},{"type":"choice","level":"基础","stem":"a^(2/3)·a^(1/3)（a>0）等于","options":["a","a²","a^(2/9)","1"],"answer":0,"analysis":"指数相加 2/3+1/3=1。","id":"sy-g1-c4-l1-q2"},{"type":"fill","level":"中档","stem":"(1/2)⁻² 的值是____","answer":"4","analysis":"负指数取倒数：(1/2)⁻²=2²=4。","id":"sy-g1-c4-l1-q3"},{"type":"fill","level":"中档","stem":"函数 f(x)=x²−3x+2 的零点个数为____","answer":"2","analysis":"Δ=9−8=1>0，两个不同实根 1 与 2。","id":"sy-g1-c4-l3-q3"},{"id":"sy-g1-c4-l1-e1","type":"essay","level":"简答","stem":"简答：化简 √a·√(1/a)（a>0）并说明分数指数幂与根式的互化规则。","ref":"√a·√(1/a)=√(a·1/a)=√1=1。规则：a^(m/n)=ⁿ√(aᵐ)（a>0，n>0）；根指数为分母、被开方数指数为分子，互化后按幂的运算法则计算。"},{"id":"sy-g1-c4-l1-e2","type":"essay","level":"简答","stem":"简答：说明指数函数 y=aˣ 的图象随 a 变化的规律（分 a>1 与 0<a<1 两种情况）。","ref":"a>1：图象上升，x 越大 y 越大，函数递增；0<a<1：图象下降，函数递减。两类图象都过定点 (0,1)，且位于 x 轴上方。"}]},{"id":"sy-g1-c4-l2","name":"4.2 对数运算与对数函数","chapterId":"sy-g1-c4","chapterName":"指数函数与对数函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"log₂8 的值是","options":["2","3","4","8"],"answer":1,"analysis":"2³=8，故 log₂8=3。","id":"sy-g1-c4-l2-q1"},{"type":"choice","level":"基础","stem":"lg2+lg5 的值是","options":["1","2","10","lg7"],"answer":0,"analysis":"lg2+lg5=lg10=1。","id":"sy-g1-c4-l2-q2"},{"type":"fill","level":"中档","stem":"log₃27+log₂(1/4) 的值是____","answer":"1","analysis":"log₃27=3，log₂(1/4)=−2，和为 1。","id":"sy-g1-c4-l2-q3"},{"type":"fill","level":"中档","stem":"函数 f(x)=x²−3x+2 的零点个数为____","answer":"2","analysis":"Δ=9−8=1>0，两个不同实根 1 与 2。","id":"sy-g1-c4-l3-q3"},{"id":"sy-g1-c4-l2-e1","type":"essay","level":"简答","stem":"简答：计算 log₂8+lg100 并写出每步所用的对数运算法则。","ref":"log₂8=log₂2³=3（指数式还原）；lg100=lg10²=2，和为 5。所用法则：log_a aⁿ=n（恒等式）。"},{"id":"sy-g1-c4-l2-e2","type":"essay","level":"简答","stem":"简答：说明对数函数 y=log_a x 的定义域、值域及 a 对单调性的影响。","ref":"定义域 (0,+∞)，值域 R。a>1 时递增，0<a<1 时递减；图象都过定点 (1,0)。真数必须大于 0，这是解题取值依据。"}]},{"id":"sy-g1-c4-l3","name":"4.3 函数的零点","chapterId":"sy-g1-c4","chapterName":"指数函数与对数函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"函数 f(x)=x−2 的零点是","options":["2","−2","(2,0)","0"],"answer":0,"analysis":"零点是使 f(x)=0 的自变量值，不是点。","id":"sy-g1-c4-l3-q1"},{"type":"choice","level":"基础","stem":"函数 f(x)=2ˣ−8 的零点是","options":["3","4","8","log₂8−1"],"answer":0,"analysis":"2ˣ=8=2³，故 x=3。","id":"sy-g1-c4-l3-q2"},{"type":"fill","level":"中档","stem":"函数 f(x)=x²−3x+2 的零点个数为____","answer":"2","analysis":"Δ=9−8=1>0，两个不同实根 1 与 2。","id":"sy-g1-c4-l3-q3"},{"type":"fill","level":"中档","stem":"(1/2)⁻² 的值是____","answer":"4","analysis":"负指数取倒数：(1/2)⁻²=2²=4。","id":"sy-g1-c4-l1-q3"},{"id":"sy-g1-c4-l3-e1","type":"essay","level":"简答","stem":"简答：叙述函数零点存在定理的条件与结论，并举一个不能用该定理的例子。","ref":"条件：f(x) 在 [a,b] 上图象连续不断，且 f(a)·f(b)<0；结论：存在零点 x₀∈(a,b)。反例：f(x)=1/x² 在含 0 的区间两端同号但无零点——定理条件不满足（不连续），不能套用。"},{"id":"sy-g1-c4-l3-e2","type":"essay","level":"简答","stem":"简答：说明用二分法求方程近似解的基本流程与终止标准。","ref":"流程：取两端点使函数值异号→取中点算函数值→与一端异号的区间保留→重复压缩区间。终止：区间长度小于给定精度 ε 时，中点即为近似解。"}]}]},{"id":"sy-g1-c5","name":"三角函数","book":"必修第一册","grade":"高一","lessons":[{"id":"sy-g1-c5-l1","name":"5.1 任意角与弧度制","chapterId":"sy-g1-c5","chapterName":"三角函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"120° 化为弧度是","options":["2π/3","3π/4","π/3","5π/6"],"answer":0,"analysis":"120°×π/180°=2π/3。","id":"sy-g1-c5-l1-q1"},{"type":"choice","level":"基础","stem":"5π/6 化为角度是","options":["150°","120°","135°","210°"],"answer":0,"analysis":"5π/6×180°/π=150°。","id":"sy-g1-c5-l1-q2"},{"type":"fill","level":"中档","stem":"与 −30° 终边相同的角的集合是____（用 α=−30°+k·360° 形式表示）","answer":"{α|α=−30°+k·360°,k∈Z}","analysis":"终边相同的角相差 360° 的整数倍。","id":"sy-g1-c5-l1-q3"},{"type":"fill","level":"中档","stem":"sin30°cos15°+cos30°sin15° 的值是____","answer":"√2/2","analysis":"逆用和角公式得 sin(30°+15°)=sin45°=√2/2。","id":"sy-g1-c5-l4-q3"},{"id":"sy-g1-c5-l1-e1","type":"essay","level":"简答","stem":"简答：写出弧度制下扇形弧长与面积公式，并说明与角度制公式的联系。","ref":"弧长 l=αr，面积 S=½l·r=½αr²（α 为弧度）。与角度制联系：n°=nπ/180 rad，代入后两公式一致。"},{"id":"sy-g1-c5-l1-e2","type":"essay","level":"简答","stem":"简答：把 150° 化为弧度，并说明终边相同的角的表示方法。","ref":"150°=150×π/180=5π/6。与 α 终边相同的角为 β=α+2kπ（k∈Z），即相差整数圈。"}]},{"id":"sy-g1-c5-l2","name":"5.2 三角函数定义与诱导公式","chapterId":"sy-g1-c5","chapterName":"三角函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"已知角 α 的终边经过点 (3,4)，则 sinα 的值是","options":["4/5","3/5","3/4","4/3"],"answer":0,"analysis":"r=5，sinα=y/r=4/5。","id":"sy-g1-c5-l2-q1"},{"type":"choice","level":"基础","stem":"sin150° 的值是","options":["1/2","−1/2","√3/2","−√3/2"],"answer":0,"analysis":"sin150°=sin(180°−30°)=sin30°=1/2。","id":"sy-g1-c5-l2-q2"},{"type":"fill","level":"中档","stem":"cos(π+α)=____","answer":"−cosα","analysis":"π+α 在第三象限，余弦为负，函数名不变。","id":"sy-g1-c5-l2-q3"},{"type":"fill","level":"中档","stem":"sin30°cos15°+cos30°sin15° 的值是____","answer":"√2/2","analysis":"逆用和角公式得 sin(30°+15°)=sin45°=√2/2。","id":"sy-g1-c5-l4-q3"},{"id":"sy-g1-c5-l2-e1","type":"essay","level":"简答","stem":"简答：写出角 α 终边上一点 P(x,y)（r=|OP|）的六个三角函数值定义。","ref":"sinα=y/r，cosα=x/r，tanα=y/x（x≠0），倒数关系：cscα=r/y、secα=r/x、cotα=x/y（相应分母非零）。"},{"id":"sy-g1-c5-l2-e2","type":"essay","level":"简答","stem":"简答：叙述诱导公式中\"奇变偶不变，符号看象限\"的含义并举一例。","ref":"角 π/2±α、3π/2±α（奇数倍）时函数名改变（sin↔cos），2π±α、π±α（偶数倍）不变；符号由把 α 看作锐角时原函数在相应象限的正负决定。例：sin(π+α)=−sinα（第三象限 sin 为负）。"}]},{"id":"sy-g1-c5-l3","name":"5.3 三角函数的图象与性质","chapterId":"sy-g1-c5","chapterName":"三角函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"函数 y=sin x 的最小正周期为","options":["2π","π","π/2","4π"],"answer":0,"analysis":"正弦函数周期 2π。","id":"sy-g1-c5-l3-q1"},{"type":"choice","level":"基础","stem":"y=cosx 的最大值是","options":["1","0","−1","2"],"answer":0,"analysis":"余弦值域 [−1,1]，最大值 1。","id":"sy-g1-c5-l3-q2"},{"type":"fill","level":"中档","stem":"y=2sin(2x+π/3) 的最小正周期是____","answer":"π","analysis":"T=2π/|ω|=2π/2=π。","id":"sy-g1-c5-l3-q3"},{"type":"fill","level":"中档","stem":"sin30°cos15°+cos30°sin15° 的值是____","answer":"√2/2","analysis":"逆用和角公式得 sin(30°+15°)=sin45°=√2/2。","id":"sy-g1-c5-l4-q3"},{"id":"sy-g1-c5-l3-e1","type":"essay","level":"简答","stem":"简答：说明正弦曲线 y=sin x 的周期、最值、对称轴，并说明 \"T=2π\" 的含义。","ref":"最小正周期 2π：每隔 2π 图象重复一次；最大值 1（x=π/2+2kπ）、最小值 −1（x=3π/2+2kπ）；对称轴 x=π/2+kπ。"},{"id":"sy-g1-c5-l3-e2","type":"essay","level":"简答","stem":"简答：由 y=sin x 的图象如何得到 y=2sin(2x+π/3) 的图象？写出变换顺序。","ref":"三种等效顺序之一：先左移 π/3 得 y=sin(x+π/3)；再纵坐标不变横坐标缩短为原来 1/2（周期变 π）；最后纵坐标伸长为原来的 2 倍（最大值 2）。"}]},{"id":"sy-g1-c5-l4","name":"5.4 三角恒等变换","chapterId":"sy-g1-c5","chapterName":"三角函数","book":"必修第一册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"sin2α 等于","options":["2sinαcosα","sin²α−cos²α","2sin²α","cos²α−sin²α"],"answer":0,"analysis":"二倍角正弦公式。","id":"sy-g1-c5-l4-q1"},{"type":"choice","level":"基础","stem":"cos2α 可化为","options":["1−2sin²α","2sin²α−1","2cos²α−1+2","1+2sin²α"],"answer":0,"analysis":"cos2α=1−2sin²α=2cos²α−1。","id":"sy-g1-c5-l4-q2"},{"type":"fill","level":"中档","stem":"sin30°cos15°+cos30°sin15° 的值是____","answer":"√2/2","analysis":"逆用和角公式得 sin(30°+15°)=sin45°=√2/2。","id":"sy-g1-c5-l4-q3"},{"type":"fill","level":"中档","stem":"与 −30° 终边相同的角的集合是____（用 α=−30°+k·360° 形式表示）","answer":"{α|α=−30°+k·360°,k∈Z}","analysis":"终边相同的角相差 360° 的整数倍。","id":"sy-g1-c5-l1-q3"},{"id":"sy-g1-c5-l4-e1","type":"essay","level":"简答","stem":"简答：写出两角和与差的正弦、余弦公式（sin(α±β)、cos(α±β)）。","ref":"sin(α±β)=sinαcosβ±cosαsinβ；cos(α±β)=cosαcosβ∓sinαsinβ（和角取上号、差角取下号）。"},{"id":"sy-g1-c5-l4-e2","type":"essay","level":"简答","stem":"简答：化简 sin(x+π/4)·cos(x−π/4)−cos(x+π/4)·sin(x−π/4)，并说明所用公式。","ref":"逆用 sin(A−B)=sinAcosB−cosAsinB，原式=sin[(x+π/4)−(x−π/4)]=sin(π/2)=1。"}]}]},{"id":"sy-g1-c6","name":"平面向量及其应用","book":"必修第二册","grade":"高一","lessons":[{"id":"sy-g1-c6-l1","name":"6.1 向量的线性运算","chapterId":"sy-g1-c6","chapterName":"平面向量及其应用","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"向量 AB + 向量 BC =","options":["向量 AC","向量 CA","向量 BA","零向量"],"answer":0,"analysis":"首尾相接，首连尾：AB+BC=AC。","id":"sy-g1-c6-l1-q1"},{"type":"choice","level":"基础","stem":"a=(1,2)，b=(3,−1)，则 a+b=","options":["(4,1)","(2,3)","(−2,3)","(4,−1)"],"answer":0,"analysis":"坐标相加：(1+3, 2−1)=(4,1)。","id":"sy-g1-c6-l1-q2"},{"type":"fill","level":"中档","stem":"a=(2,−4)，则 2a=____","answer":"(4,−8)","analysis":"数乘向量各坐标同乘 2。","id":"sy-g1-c6-l1-q3"},{"type":"fill","level":"中档","stem":"在 △ABC 中，a=3，b=4，C=60°，则 c²=____","answer":"13","analysis":"c²=9+16−2×3×4×(1/2)=13。","id":"sy-g1-c6-l3-q3"},{"id":"sy-g1-c6-l1-e1","type":"essay","level":"简答","stem":"简答：说明向量数乘 a 的几何意义，并写出共线向量定理。","ref":"λa 与 a 共线：λ>0 同向、λ<0 反向、|λa|=|λ||a|。共线定理：a∥b（a≠0）⇔ 存在唯一实数 λ 使 b=λa。"},{"id":"sy-g1-c6-l1-e2","type":"essay","level":"简答","stem":"简答：用向量线性运算说明\"AB→+BC→=AC→\"的几何意义，并举例说明化简一条折线向量式的方法。","ref":"首尾相接的两段位移之和等于起点到终点的总位移（三角形法则）。化简方法：按字母顺序首尾相接逐步合并，如 AB→+BC→+CD→=AD→。"}]},{"id":"sy-g1-c6-l2","name":"6.2 数量积、夹角与模","chapterId":"sy-g1-c6","chapterName":"平面向量及其应用","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"a·b=|a||b|cosθ 中 θ 的取值范围是","options":["[0,π]","[0,2π)","(0,π)","[−π/2,π/2]"],"answer":0,"analysis":"两向量夹角定义在 0 到 π 之间。","id":"sy-g1-c6-l2-q1"},{"type":"choice","level":"基础","stem":"a=(1,0)，b=(0,1)，则 a·b=","options":["0","1","2","−1"],"answer":0,"analysis":"坐标数量积 1×0+0×1=0，两向量垂直。","id":"sy-g1-c6-l2-q2"},{"type":"fill","level":"中档","stem":"|a|=2，|b|=3，a·b=3，则 cos<a,b>=____","answer":"1/2","analysis":"cosθ=3/(2×3)=1/2。","id":"sy-g1-c6-l2-q3"},{"type":"fill","level":"中档","stem":"在 △ABC 中，a=3，b=4，C=60°，则 c²=____","answer":"13","analysis":"c²=9+16−2×3×4×(1/2)=13。","id":"sy-g1-c6-l3-q3"},{"id":"sy-g1-c6-l2-e1","type":"essay","level":"简答","stem":"简答：写出数量积的定义式，并说明如何用它求两向量的夹角。","ref":"a·b=|a||b|cosθ。由 cosθ=(a·b)/(|a||b|)（θ∈[0,π]）反求夹角；a·b=0 是垂直的充要条件。"},{"id":"sy-g1-c6-l2-e2","type":"essay","level":"简答","stem":"简答：说明 a·b 与 |a||b| 的大小关系及取等条件。","ref":"a·b=|a||b|cosθ≤|a||b|，当且仅当 θ=0（同向）时取等；θ=π（反向）时 a·b=−|a||b| 最小。"}]},{"id":"sy-g1-c6-l3","name":"6.3 解三角形（正弦、余弦定理）","chapterId":"sy-g1-c6","chapterName":"平面向量及其应用","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"在 △ABC 中，a=2，A=30°，则 2R（R 为外接圆半径）等于","options":["4","2","1","8"],"answer":0,"analysis":"由 a/sinA=2R 得 2R=2/(1/2)=4。","id":"sy-g1-c6-l3-q1"},{"type":"choice","level":"基础","stem":"已知 b=3，c=4，A=90°，则 a=","options":["5","7","1","√7"],"answer":0,"analysis":"余弦定理 a²=b²+c²−2bc·cos90°=25。","id":"sy-g1-c6-l3-q2"},{"type":"fill","level":"中档","stem":"在 △ABC 中，a=3，b=4，C=60°，则 c²=____","answer":"13","analysis":"c²=9+16−2×3×4×(1/2)=13。","id":"sy-g1-c6-l3-q3"},{"type":"fill","level":"中档","stem":"|a|=2，|b|=3，a·b=3，则 cos<a,b>=____","answer":"1/2","analysis":"cosθ=3/(2×3)=1/2。","id":"sy-g1-c6-l2-q3"},{"id":"sy-g1-c6-l3-e1","type":"essay","level":"简答","stem":"简答：写出正弦定理与余弦定理，并各说明一种典型适用情形。","ref":"正弦定理 a/sinA=b/sinB=c/sinC=2R：已知两角一边或两边与其中一边的对角时用。余弦定理 a²=b²+c²−2bc·cosA：已知两边夹角或三边求角时用。"},{"id":"sy-g1-c6-l3-e2","type":"essay","level":"简答","stem":"简答：在△ABC 中说明由 a²>b²+c² 能得到什么结论，依据是什么。","ref":"由余弦定理 cosA=(b²+c²−a²)/(2bc)<0，而 A∈(0,π)，故 A 为钝角，三角形为钝角三角形。依据：余弦定理与余弦函数在 (0,π) 的符号。"}]}]},{"id":"sy-g1-c7","name":"复数","book":"必修第二册","grade":"高一","lessons":[{"id":"sy-g1-c7-l1","name":"7.1 复数的概念与几何意义","chapterId":"sy-g1-c7","chapterName":"复数","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"复数 z=3−2i 的虚部是","options":["−2","2","−2i","3"],"answer":0,"analysis":"虚部是不含 i 的实数 −2。","id":"sy-g1-c7-l1-q1"},{"type":"choice","level":"基础","stem":"复数 z=1+2i 在复平面内对应的点位于","options":["第一象限","第二象限","第三象限","第四象限"],"answer":0,"analysis":"实部 1>0，虚部 2>0，位于第一象限。","id":"sy-g1-c7-l1-q2"},{"type":"fill","level":"中档","stem":"复数 z=3+4i 的模 |z|=____","answer":"5","analysis":"|z|=√(9+16)=5。","id":"sy-g1-c7-l1-q3"},{"type":"fill","level":"中档","stem":"(1+i)(1−i)=____","answer":"2","analysis":"按平方差展开得 1−i²=1+1=2。","id":"sy-g1-c7-l2-q3"},{"id":"sy-g1-c7-l1-e1","type":"essay","level":"简答","stem":"简答：说明复数 z=a+bi（a,b∈R）与复平面内点、平面向量的对应关系，并写出模的计算式。","ref":"z 对应点 Z(a,b) 及向量 OZ→；模 |z|=√(a²+b²)。实部 a 对应横坐标，虚部 b 对应纵坐标。"},{"id":"sy-g1-c7-l1-e2","type":"essay","level":"简答","stem":"简答：说明纯虚数与实数的区别，并指出 b 为何值时 z=(b−1)+(b²−1)i 为纯虚数。","ref":"纯虚数实部为 0 且虚部不为 0。须 b−1=0 且 b²−1≠0，得 b=1（b=−1 时虚部为 0 舍去），此时 z=2i 为纯虚数。"}]},{"id":"sy-g1-c7-l2","name":"7.2 复数的四则运算","chapterId":"sy-g1-c7","chapterName":"复数","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"(1+i)+(2−i)=","options":["3","3+2i","1+2i","3−2i"],"answer":0,"analysis":"实部虚部分别相加，虚部抵消为 0。","id":"sy-g1-c7-l2-q1"},{"type":"choice","level":"基础","stem":"i² 等于","options":["−1","1","i","−i"],"answer":0,"analysis":"虚数单位定义 i²=−1。","id":"sy-g1-c7-l2-q2"},{"type":"fill","level":"中档","stem":"(1+i)(1−i)=____","answer":"2","analysis":"按平方差展开得 1−i²=1+1=2。","id":"sy-g1-c7-l2-q3"},{"type":"fill","level":"中档","stem":"复数 z=3+4i 的模 |z|=____","answer":"5","analysis":"|z|=√(9+16)=5。","id":"sy-g1-c7-l1-q3"},{"id":"sy-g1-c7-l2-e1","type":"essay","level":"简答","stem":"简答：计算 (1+i)² 并说明虚数单位 i 的乘方周期性。","ref":"(1+i)²=1+2i+i²=2i。i 的乘方按 4 为周期循环：i¹=i，i²=−1，i³=−i，i⁴=1，iⁿ 按 n 除以 4 的余数取值。"},{"id":"sy-g1-c7-l2-e2","type":"essay","level":"简答","stem":"简答：说明复数除法\"分母实数化\"的方法，并计算 (1+i)/(1−i)。","ref":"分子分母同乘分母的共轭复数。(1+i)/(1−i)×[(1+i)/(1+i)]=(1+i)²/2=2i/2=i。"}]}]},{"id":"sy-g1-c8","name":"立体几何初步","book":"必修第二册","grade":"高一","lessons":[{"id":"sy-g1-c8-l1","name":"8.1 基本几何体与表面积、体积","chapterId":"sy-g1-c8","chapterName":"立体几何初步","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"棱长为 2 的正方体体积为","options":["8","4","12","6"],"answer":0,"analysis":"V=a³=8。","id":"sy-g1-c8-l1-q1"},{"type":"choice","level":"基础","stem":"底面半径为 1、高为 3 的圆柱体积为","options":["3π","π","6π","9π"],"answer":0,"analysis":"V=πr²h=3π。","id":"sy-g1-c8-l1-q2"},{"type":"fill","level":"中档","stem":"表面积为 6 的正方体，其棱长为____","answer":"1","analysis":"6a²=6 得 a=1。","id":"sy-g1-c8-l1-q3"},{"type":"fill","level":"中档","stem":"过平面外一点，与已知平面平行的平面有____个","answer":"1","analysis":"过平面外一点有且只有一个平面与已知平面平行。","id":"sy-g1-c8-l2-q3"},{"id":"sy-g1-c8-l1-e1","type":"essay","level":"简答","stem":"简答：写出棱柱、棱锥、棱台的定义要点，并说明它们的联系。","ref":"棱柱：两底面平行、侧面均为平行四边形；棱锥：一个底面、侧面三角形共顶点；棱台：棱锥被平行于底面的平面截得。联系：棱台可由棱锥截得，棱柱上下底面全等。"},{"id":"sy-g1-c8-l1-e2","type":"essay","level":"简答","stem":"简答：写出球的表面积与体积公式，并说明用\"正方体外接球\"求球的思路。","ref":"S=4πR²，V=(4/3)πR³。正方体棱长 a 时，体对角线即外接球直径：2R=√3·a，故 R=√3a/2，再代公式。"}]},{"id":"sy-g1-c8-l2","name":"8.2 空间点线面位置关系","chapterId":"sy-g1-c8","chapterName":"立体几何初步","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"两条不重合直线的位置关系有","options":["平行、相交、异面","只有平行与相交","只有相交与异面","只有平行与异面"],"answer":0,"analysis":"空间中两直线共面则平行或相交，不共面则异面。","id":"sy-g1-c8-l2-q1"},{"type":"choice","level":"基础","stem":"若直线 a∥平面 α，直线 b⊂α，则 a 与 b","options":["可能平行也可能异面","一定平行","一定相交","一定异面"],"answer":0,"analysis":"线面平行时，面内直线与它无公共点，可能平行也可能异面。","id":"sy-g1-c8-l2-q2"},{"type":"fill","level":"中档","stem":"过平面外一点，与已知平面平行的平面有____个","answer":"1","analysis":"过平面外一点有且只有一个平面与已知平面平行。","id":"sy-g1-c8-l2-q3"},{"type":"fill","level":"中档","stem":"表面积为 6 的正方体，其棱长为____","answer":"1","analysis":"6a²=6 得 a=1。","id":"sy-g1-c8-l1-q3"},{"id":"sy-g1-c8-l2-e1","type":"essay","level":"简答","stem":"简答：叙述异面直线的定义，并举教室里的一个实例说明\"不同在任何一个平面内\"。","ref":"不同在任何一个平面内的两条直线叫异面直线，既不平行也不相交。实例：教室前排地面上的一条线与天花板另一侧横走的直线，无论如何放置平面都不能同时包含两者。"},{"id":"sy-g1-c8-l2-e2","type":"essay","level":"简答","stem":"简答：说明线面平行、面面平行的判定定理及各自需要的条件个数。","ref":"线面平行：平面外一条直线与此平面内一条直线平行（需线在面外+面内线平行）。面面平行：一个平面内两条相交直线都平行于另一平面（需两条且相交）。"}]},{"id":"sy-g1-c8-l3","name":"8.3 平行与垂直的判定","chapterId":"sy-g1-c8","chapterName":"立体几何初步","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"判定直线与平面平行的常用方法是","options":["平面外一条直线与此平面内一条直线平行","直线与平面内两条直线平行","直线与平面垂直","直线与平面无交点即可直接判定"],"answer":0,"analysis":"线面平行判定定理：线线平行推出线面平行。","id":"sy-g1-c8-l3-q1"},{"type":"choice","level":"基础","stem":"若一条直线垂直于平面内两条相交直线，则该直线","options":["垂直于这个平面","平行于这个平面","在平面内","与平面斜交"],"answer":0,"analysis":"线面垂直判定定理。","id":"sy-g1-c8-l3-q2"},{"type":"fill","level":"中档","stem":"正方体 ABCD-A₁B₁C₁D₁ 中，AB 与 A₁C₁ 的位置关系是____（填\"平行\"\"相交\"或\"异面\"）","answer":"异面","analysis":"两直线不共面且不相交，为异面直线。","id":"sy-g1-c8-l3-q3"},{"type":"fill","level":"中档","stem":"过平面外一点，与已知平面平行的平面有____个","answer":"1","analysis":"过平面外一点有且只有一个平面与已知平面平行。","id":"sy-g1-c8-l2-q3"},{"id":"sy-g1-c8-l3-e1","type":"essay","level":"简答","stem":"简答：写出线面垂直的判定定理，并说明为什么\"一条直线垂直于平面内一条直线\"不够。","ref":"定理：直线垂直于平面内两条相交直线，则线面垂直。只垂直一条直线时该直线可能斜着落在平面内，必须与两条相交直线都垂直才能保证垂直于所有直线。"},{"id":"sy-g1-c8-l3-e2","type":"essay","level":"简答","stem":"简答：证明\"若 a∥α，b⊂α，则 a∥b 或 a 与 b 异面\"，写出推理思路。","ref":"反证：若 a 与 b 相交，交点在 α 内，则 a 与 α 有公共点，与 a∥α 矛盾。又 a 不在 α 内（面外），故 a 与 b 无公共点，只能平行或异面。"}]}]},{"id":"sy-g1-c9","name":"统计、概率","book":"必修第二册","grade":"高一","lessons":[{"id":"sy-g1-c9-l1","name":"9.1 随机抽样与样本估计","chapterId":"sy-g1-c9","chapterName":"统计、概率","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"从 1000 名学生中抽取 50 人调查，最合适的抽样方法是","options":["系统抽样","简单随机抽样中的抽签法","整群抽样","普查"],"answer":0,"analysis":"总体容量较大且无明显分层时，等距抽取即系统抽样更便利。","id":"sy-g1-c9-l1-q1"},{"type":"choice","level":"基础","stem":"一组数据 1,2,3,4,5 的平均数是","options":["3","2.5","4","15"],"answer":0,"analysis":"总和 15 除以 5 得 3。","id":"sy-g1-c9-l1-q2"},{"type":"fill","level":"中档","stem":"数据 1,2,3,4,5 的方差是____","answer":"2","analysis":"偏差平方和 (4+1+0+1+4)=10，除以 5 得 2。","id":"sy-g1-c9-l1-q3"},{"type":"fill","level":"中档","stem":"同时掷两枚均匀硬币，恰有一枚正面向上的概率是____","answer":"1/2","analysis":"样本空间 {正正,正反,反正,反反}，符合条件 2 个，概率 1/2。","id":"sy-g1-c9-l2-q3"},{"id":"sy-g1-c9-l1-e1","type":"essay","level":"简答","stem":"简答：比较简单随机抽样、分层抽样、系统抽样的特点与适用情形。","ref":"简单随机抽样：总体小、个体差异小，抽签或随机数；分层抽样：总体由差异明显的几层构成，按比例各层抽取；系统抽样：总体大且分布均匀，编号后按固定间隔抽。共同点：每个个体被抽到机会均等。"},{"id":"sy-g1-c9-l1-e2","type":"essay","level":"简答","stem":"简答：说明用样本频率分布直方图估计总体分布的步骤及纵坐标的含义。","ref":"步骤：求极差→定组距分组→统计频数→算频率/组距作纵坐标→画直方图。纵坐标=频率/组距，各矩形面积之和为 1，面积才是该组频率。"}]},{"id":"sy-g1-c9-l2","name":"9.2 古典概型","chapterId":"sy-g1-c9","chapterName":"统计、概率","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"掷一枚质地均匀的骰子，出现偶数点的概率是","options":["1/2","1/3","1/6","2/3"],"answer":0,"analysis":"偶数点 2,4,6 共 3 个，3/6=1/2。","id":"sy-g1-c9-l2-q1"},{"type":"choice","level":"基础","stem":"从 1,2,3,4 中任取一个数，取到质数的概率是","options":["1/2","1/4","3/4","1/3"],"answer":0,"analysis":"质数 2,3 共 2 个，2/4=1/2。","id":"sy-g1-c9-l2-q2"},{"type":"fill","level":"中档","stem":"同时掷两枚均匀硬币，恰有一枚正面向上的概率是____","answer":"1/2","analysis":"样本空间 {正正,正反,反正,反反}，符合条件 2 个，概率 1/2。","id":"sy-g1-c9-l2-q3"},{"type":"fill","level":"中档","stem":"数据 1,2,3,4,5 的方差是____","answer":"2","analysis":"偏差平方和 (4+1+0+1+4)=10，除以 5 得 2。","id":"sy-g1-c9-l1-q3"},{"id":"sy-g1-c9-l2-e1","type":"essay","level":"简答","stem":"简答：叙述古典概型的两个特征，并举一个满足与一个不满足的例子。","ref":"特征：基本事件有限个；每个基本事件等可能。满足：掷一枚均匀骰子（6 个等可能结果）。不满足：射击命中环数概率不等或连续型情形（如转盘指针停点位置无限多）。"},{"id":"sy-g1-c9-l2-e2","type":"essay","level":"简答","stem":"简答：同时掷两枚均匀硬币，说明\"出现一正一反\"的概率为什么是 1/2 而不是 1/3。","ref":"基本事件：(正,正)、(正,反)、(反,正)、(反,反) 共 4 个等可能；一正一反含 (正,反)、(反,正) 两个事件，故 P=2/4=1/2。错误在于把 (正,反) 与 (反,正) 当成一个事件。"}]},{"id":"sy-g1-c9-l3","name":"9.3 事件的关系与频率","chapterId":"sy-g1-c9","chapterName":"统计、概率","book":"必修第二册","grade":"高一","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"若 A、B 为互斥事件，则 P(A∪B)=","options":["P(A)+P(B)","P(A)P(B)","1","P(A)−P(B)"],"answer":0,"analysis":"互斥事件不能同时发生，概率可直接相加。","id":"sy-g1-c9-l3-q1"},{"type":"choice","level":"基础","stem":"事件 A 与其对立事件 Ā 满足","options":["P(A)+P(Ā)=1","P(A)=P(Ā)","P(A)P(Ā)=1","P(A)+P(Ā)=0"],"answer":0,"analysis":"对立事件必有一个发生，概率和为 1。","id":"sy-g1-c9-l3-q2"},{"type":"fill","level":"中档","stem":"P(A)=0.3，则 P(Ā)=____","answer":"0.7","analysis":"对立事件概率 = 1−0.3。","id":"sy-g1-c9-l3-q3"},{"type":"fill","level":"中档","stem":"数据 1,2,3,4,5 的方差是____","answer":"2","analysis":"偏差平方和 (4+1+0+1+4)=10，除以 5 得 2。","id":"sy-g1-c9-l1-q3"},{"id":"sy-g1-c9-l3-e1","type":"essay","level":"简答","stem":"简答：说明互斥事件与对立事件的区别与联系，并各举一例。","ref":"互斥：不能同时发生；对立：互斥且必有一个发生（并集为全集）。对立必互斥，互斥未必对立。例：掷骰子\"出现 1 点\"与\"出现 2 点\"互斥不对立；\"出现奇数\"与\"出现偶数\"对立。"},{"id":"sy-g1-c9-l3-e2","type":"essay","level":"简答","stem":"简答：说明用频率估计概率的依据与注意点。","ref":"大量重复试验中频率稳定于概率附近（概率的统计定义），可用频率作为概率的估计值。注意：试验次数要足够多；单次或少次试验的频率波动大，不宜直接当概率。"}]}]},{"id":"sy-g2-c1","name":"空间向量与立体几何","book":"选择性必修第一册","grade":"高二","lessons":[{"id":"sy-g2-c1-l1","name":"1.1 空间向量的运算与坐标表示","chapterId":"sy-g2-c1","chapterName":"空间向量与立体几何","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"a=(1,2,3)，b=(0,1,−1)，则 a−b=","options":["(1,1,4)","(1,3,2)","(1,1,2)","(1,−1,4)"],"answer":0,"analysis":"对应坐标相减：(1−0, 2−1, 3+1)。","id":"sy-g2-c1-l1-q1"},{"type":"choice","level":"基础","stem":"a=(2,−1,2)，则 |a|=","options":["3","5","√5","9"],"answer":0,"analysis":"|a|=√(4+1+4)=3。","id":"sy-g2-c1-l1-q2"},{"type":"fill","level":"中档","stem":"A(1,0,0)，B(0,2,2)，则 |AB|=____","answer":"3","analysis":"AB=(−1,2,2)，模为 √(1+4+4)=3。","id":"sy-g2-c1-l1-q3"},{"type":"fill","level":"中档","stem":"向量 a=(1,0,0) 与 b=(0,1,0) 的夹角为____度","answer":"90","analysis":"a·b=0，两向量垂直，夹角 90°。","id":"sy-g2-c1-l2-q3"},{"id":"sy-g2-c1-l1-e1","type":"essay","level":"简答","stem":"简答：写出空间向量数量积的坐标公式，并说明如何用它求两条异面直线所成角。","ref":"a·b=a₁b₁+a₂b₂+a₃b₃。求出两直线方向向量 a、b，则 cosθ=|a·b|/(|a||b|)（加绝对值保证角为 [0,π/2]）。"},{"id":"sy-g2-c1-l1-e2","type":"essay","level":"简答","stem":"简答：说明如何建立空间直角坐标系表示一个长方体中的点，并举点 A(0,0,0)、B(2,0,0)、C(2,3,0)、D(2,3,4) 说明 AC→ 与 BD→ 是否垂直。","ref":"取公共顶点为原点，三条棱为 x、y、z 轴。AC→=(2,3,0)，BD→=(0,3,4)；数量积=2×0+3×3+0×4=9≠0，不垂直。"}]},{"id":"sy-g2-c1-l2","name":"1.2 空间角与距离的向量求法","chapterId":"sy-g2-c1","chapterName":"空间向量与立体几何","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"直线与平面所成角 θ 的取值范围是","options":["[0,π/2]","[0,π]","(0,π/2)","[−π/2,π/2]"],"answer":0,"analysis":"线面角不超过直角。","id":"sy-g2-c1-l2-q1"},{"type":"choice","level":"基础","stem":"两个半平面所成二面角的取值范围是","options":["[0,π]","[0,π/2]","(0,π)","[−π,π]"],"answer":0,"analysis":"二面角可以取到钝角，范围 0 到 π。","id":"sy-g2-c1-l2-q2"},{"type":"fill","level":"中档","stem":"向量 a=(1,0,0) 与 b=(0,1,0) 的夹角为____度","answer":"90","analysis":"a·b=0，两向量垂直，夹角 90°。","id":"sy-g2-c1-l2-q3"},{"type":"fill","level":"中档","stem":"A(1,0,0)，B(0,2,2)，则 |AB|=____","answer":"3","analysis":"AB=(−1,2,2)，模为 √(1+4+4)=3。","id":"sy-g2-c1-l1-q3"},{"id":"sy-g2-c1-l2-e1","type":"essay","level":"简答","stem":"简答：叙述用向量法求线面角、二面角的步骤及角度取值范围。","ref":"线面角：求直线方向向量 a 与法向量 n，sinθ=|a·n|/(|a||n|)，θ∈[0,π/2]。二面角：求两半平面法向量 n₁、n₂，cosθ=±(n₁·n₂)/(|n₁||n₂|)，结合图形判断取正取负，θ∈[0,π]。"},{"id":"sy-g2-c1-l2-e2","type":"essay","level":"简答","stem":"简答：说明点到平面的距离的向量求法。","ref":"求平面法向量 n，取平面内一点 B 与该点 P，则距离 d=|PB→·n|/|n|，即投影长度。"}]},{"id":"sy-g2-c1-l3","name":"1.3 外接球、截面与折叠","chapterId":"sy-g2-c1","chapterName":"空间向量与立体几何","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"棱长为 a 的正方体的外接球半径是","options":["√3a/2","a/2","√2a/2","√3a"],"answer":0,"analysis":"体对角线为直径：2R=√3a。","id":"sy-g2-c1-l3-q1"},{"type":"choice","level":"基础","stem":"长、宽、高分别为 a、b、c 的长方体外接球半径是","options":["√(a²+b²+c²)/2","(a+b+c)/2","√(a²+b²)/2","√(abc)/2"],"answer":0,"analysis":"体对角线为直径，半径取一半。","id":"sy-g2-c1-l3-q2"},{"type":"fill","level":"中档","stem":"棱长为 2 的正方体的外接球表面积为____","answer":"12π","analysis":"R=√3，表面积 4πR²=12π。","id":"sy-g2-c1-l3-q3"},{"type":"fill","level":"中档","stem":"向量 a=(1,0,0) 与 b=(0,1,0) 的夹角为____度","answer":"90","analysis":"a·b=0，两向量垂直，夹角 90°。","id":"sy-g2-c1-l2-q3"},{"id":"sy-g2-c1-l3-e1","type":"essay","level":"简答","stem":"简答：说明正方体、长方体外接球球心位置的确定方法。","ref":"球心在体对角线中点（长方体/正方体各顶点到该点距离相等）。利用 2R=体对角线长求半径。"},{"id":"sy-g2-c1-l3-e2","type":"essay","level":"简答","stem":"简答：说明折叠问题中\"折前折后不变的量\"有哪些，并举一例。","ref":"不变量：同一半平面内的线段长度、共面图形内部的角与距离、垂直关系中同侧的部分。例：三角形沿一边折叠后，该边上的高（在被折图形内）长度不变，可用其构造直角三角形求翻折后的距离。"}]}]},{"id":"sy-g2-c2","name":"直线和圆的方程","book":"选择性必修第一册","grade":"高二","lessons":[{"id":"sy-g2-c2-l1","name":"2.1 直线的斜率与方程","chapterId":"sy-g2-c2","chapterName":"直线和圆的方程","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"过点 (0,0) 与 (1,2) 的直线斜率为","options":["2","1/2","−2","−1/2"],"answer":0,"analysis":"k=(2−0)/(1−0)=2。","id":"sy-g2-c2-l1-q1"},{"type":"choice","level":"基础","stem":"直线 y=2x+1 的纵截距为","options":["1","2","−1","1/2"],"answer":0,"analysis":"y=kx+b 中 b 为纵截距。","id":"sy-g2-c2-l1-q2"},{"type":"fill","level":"中档","stem":"过点 (1,2) 且斜率为 3 的直线方程是____（写成 y=kx+b 形式）","answer":"y=3x−1","analysis":"y−2=3(x−1)，整理得 y=3x−1。","id":"sy-g2-c2-l1-q3"},{"type":"fill","level":"中档","stem":"点 (1,1) 关于 x 轴对称的点的坐标是____","answer":"(1,−1)","analysis":"关于 x 轴对称时纵坐标取相反数。","id":"sy-g2-c2-l2-q3"},{"id":"sy-g2-c2-l1-e1","type":"essay","level":"简答","stem":"简答：写出直线斜率公式并说明斜率不存在的情形；说明倾斜角与斜率的关系。","ref":"k=(y₂−y₁)/(x₂−x₁)（x₁≠x₂）。x₁=x₂（倾斜角 90°）时斜率不存在。k=tanα，α∈[0,π)；α=90° 时 tanα 不存在。"},{"id":"sy-g2-c2-l1-e2","type":"essay","level":"简答","stem":"简答：写出直线方程的四种形式及各自适用条件。","ref":"点斜式 y−y₀=k(x−x₀)：已知一点与斜率（斜率存在）；斜截式 y=kx+b：已知斜率与纵截距；两点式：已知两点（横坐标不等且纵坐标不等）；一般式 Ax+By+C=0（A、B 不同时为 0，普适）。"}]},{"id":"sy-g2-c2-l2","name":"2.2 距离公式与对称问题","chapterId":"sy-g2-c2","chapterName":"直线和圆的方程","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"点 (3,4) 到原点的距离是","options":["5","7","25","√7"],"answer":0,"analysis":"√(9+16)=5。","id":"sy-g2-c2-l2-q1"},{"type":"choice","level":"基础","stem":"平行直线 y=x 与 y=x+1 之间的距离是","options":["√2/2","1","√2","1/2"],"answer":0,"analysis":"化为 x−y+1=0，d=1/√2=√2/2。","id":"sy-g2-c2-l2-q2"},{"type":"fill","level":"中档","stem":"点 (1,1) 关于 x 轴对称的点的坐标是____","answer":"(1,−1)","analysis":"关于 x 轴对称时纵坐标取相反数。","id":"sy-g2-c2-l2-q3"},{"type":"fill","level":"中档","stem":"过点 (1,2) 且斜率为 3 的直线方程是____（写成 y=kx+b 形式）","answer":"y=3x−1","analysis":"y−2=3(x−1)，整理得 y=3x−1。","id":"sy-g2-c2-l1-q3"},{"id":"sy-g2-c2-l2-e1","type":"essay","level":"简答","stem":"简答：写出点到直线的距离公式与两平行线间的距离公式。","ref":"点 (x₀,y₀) 到 Ax+By+C=0：d=|Ax₀+By₀+C|/√(A²+B²)。平行线 Ax+By+C₁=0 与 Ax+By+C₂=0：d=|C₁−C₂|/√(A²+B²)，须先把 x、y 系数化成相同。"},{"id":"sy-g2-c2-l2-e2","type":"essay","level":"简答","stem":"简答：说明点 (x₀,y₀) 关于直线 y=x 对称的点的求法，并举一例。","ref":"关于 y=x 对称：横纵坐标互换，(x₀,y₀)→(y₀,x₀)。例：(2,5) 关于 y=x 的对称点为 (5,2)。其他对称轴可用中点在对称轴上+连线垂直于对称轴联立求解。"}]},{"id":"sy-g2-c2-l3","name":"2.3 圆的方程与直线与圆","chapterId":"sy-g2-c2","chapterName":"直线和圆的方程","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"圆 x²+y²=4 的圆心与半径分别是","options":["(0,0)，2","(0,0)，4","(2,0)，2","(0,2)，2"],"answer":0,"analysis":"标准形式圆心原点，半径 r=2。","id":"sy-g2-c2-l3-q1"},{"type":"choice","level":"基础","stem":"圆 (x−1)²+(y+2)²=9 的圆心是","options":["(1,−2)","(−1,2)","(1,2)","(−1,−2)"],"answer":0,"analysis":"注意 y+2 对应圆心纵坐标 −2。","id":"sy-g2-c2-l3-q2"},{"type":"fill","level":"中档","stem":"直线 y=x+2 与圆 x²+y²=2 的位置关系是____（填\"相交\"\"相切\"或\"相离\"）","answer":"相切","analysis":"圆心到直线距离 d=2/√2=√2，等于半径，故相切。","id":"sy-g2-c2-l3-q3"},{"type":"fill","level":"中档","stem":"过点 (1,2) 且斜率为 3 的直线方程是____（写成 y=kx+b 形式）","answer":"y=3x−1","analysis":"y−2=3(x−1)，整理得 y=3x−1。","id":"sy-g2-c2-l1-q3"},{"id":"sy-g2-c2-l3-e1","type":"essay","level":"简答","stem":"简答：写出圆的标准方程与一般方程，并说明一般方程中 D²+E²−4F 的意义。","ref":"标准：(x−a)²+(y−b)²=r²；一般：x²+y²+Dx+Ey+F=0（配方可化标准式）。D²+E²−4F=4r²>0 表示圆；=0 表示点；<0 不表示任何图形。"},{"id":"sy-g2-c2-l3-e2","type":"essay","level":"简答","stem":"简答：说明判断直线与圆位置关系的两种方法，并比较优劣。","ref":"几何法：圆心距 d 与半径 r 比较（d<r 相交、=r 相切、>r 相离），计算量小、首选；代数法：联立方程用判别式 Δ（Δ>0 两交点、=0 相切、<0 相离），通用但运算量大。"}]}]},{"id":"sy-g2-c3","name":"圆锥曲线","book":"选择性必修第一册","grade":"高二","lessons":[{"id":"sy-g2-c3-l1","name":"3.1 椭圆的定义与性质","chapterId":"sy-g2-c3","chapterName":"圆锥曲线","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"椭圆 x²/25+y²/9=1 的离心率是","options":["4/5","3/5","5/4","9/25"],"answer":0,"analysis":"a=5，b=3，c=4，e=c/a=4/5。","id":"sy-g2-c3-l1-q1"},{"type":"choice","level":"基础","stem":"焦点在 x 轴上，a=5，c=3 的椭圆方程是","options":["x²/25+y²/16=1","x²/16+y²/25=1","x²/25+y²/9=1","x²/9+y²/25=1"],"answer":0,"analysis":"b²=a²−c²=16，长轴在 x 轴。","id":"sy-g2-c3-l1-q2"},{"type":"fill","level":"中档","stem":"椭圆上一点 P 到两焦点 F₁、F₂ 的距离之和为____（用 a 表示）","answer":"2a","analysis":"椭圆定义：|PF₁|+|PF₂|=2a。","id":"sy-g2-c3-l1-q3"},{"type":"fill","level":"中档","stem":"双曲线 x²/4−y²/5=1 的焦距为____","answer":"6","analysis":"c²=4+5=9，c=3，焦距 2c=6。","id":"sy-g2-c3-l2-q3"},{"id":"sy-g2-c3-l1-e1","type":"essay","level":"简答","stem":"简答：写出椭圆的定义、标准方程与 a、b、c 的关系式。","ref":"定义：到两定点距离之和为常数 2a（2a>2c）的点的轨迹。焦点在 x 轴：x²/a²+y²/b²=1（a>b>0）；关系：a²=b²+c²，2c 为焦距。"},{"id":"sy-g2-c3-l1-e2","type":"essay","level":"简答","stem":"简答：说明椭圆的离心率的定义及 e 的大小对椭圆形状的影响。","ref":"e=c/a∈(0,1)。e 越小越接近圆（c 相对越小），e 越接近 1 越扁。e=0 时退化为圆（c=0）。"}]},{"id":"sy-g2-c3-l2","name":"3.2 双曲线的定义与性质","chapterId":"sy-g2-c3","chapterName":"圆锥曲线","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"双曲线 x²/9−y²/16=1 的渐近线方程是","options":["y=±4x/3","y=±3x/4","y=±16x/9","y=±9x/16"],"answer":0,"analysis":"渐近线 y=±(b/a)x=±(4/3)x。","id":"sy-g2-c3-l2-q1"},{"type":"choice","level":"基础","stem":"双曲线的离心率 e 满足","options":["e>1","0<e<1","e=1","e<0"],"answer":0,"analysis":"双曲线 c>a，故 e=c/a>1。","id":"sy-g2-c3-l2-q2"},{"type":"fill","level":"中档","stem":"双曲线 x²/4−y²/5=1 的焦距为____","answer":"6","analysis":"c²=4+5=9，c=3，焦距 2c=6。","id":"sy-g2-c3-l2-q3"},{"type":"fill","level":"中档","stem":"椭圆上一点 P 到两焦点 F₁、F₂ 的距离之和为____（用 a 表示）","answer":"2a","analysis":"椭圆定义：|PF₁|+|PF₂|=2a。","id":"sy-g2-c3-l1-q3"},{"id":"sy-g2-c3-l2-e1","type":"essay","level":"简答","stem":"简答：写出双曲线的定义与标准方程，说明与椭圆方程中 a²、b² 关系的差别。","ref":"定义：到两定点距离之差的绝对值为常数 2a（0<2a<2c）。x²/a²−y²/b²=1（焦点在 x 轴）；双曲线中 c²=a²+b²，而椭圆是 a²=b²+c²，符号方向相反。"},{"id":"sy-g2-c3-l2-e2","type":"essay","level":"简答","stem":"简答：写出双曲线渐近线方程的求法，并说明离心率与渐近线斜率的关系。","ref":"x²/a²−y²/b²=1 的渐近线为 y=±(b/a)x（把 1 换成 0 解出）。e=√(1+b²/a²)，b/a 越大 e 越大，开口越开阔。"}]},{"id":"sy-g2-c3-l3","name":"3.3 抛物线的定义与性质","chapterId":"sy-g2-c3","chapterName":"圆锥曲线","book":"选择性必修第一册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"抛物线 y²=8x 的准线方程是","options":["x=−2","x=2","y=−2","y=2"],"answer":0,"analysis":"2p=8，p=4，准线 x=−p/2=−2。","id":"sy-g2-c3-l3-q1"},{"type":"choice","level":"基础","stem":"抛物线 y²=2px（p>0）的焦点坐标是","options":["(p/2,0)","(p,0)","(0,p/2)","(−p/2,0)"],"answer":0,"analysis":"焦点在 x 轴正半轴，横坐标 p/2。","id":"sy-g2-c3-l3-q2"},{"type":"fill","level":"中档","stem":"抛物线 y²=4x 上一点 P(1,2) 到焦点的距离为____","answer":"2","analysis":"到焦点距离等于到准线 x=−1 的距离：1+1=2。","id":"sy-g2-c3-l3-q3"},{"type":"fill","level":"中档","stem":"椭圆上一点 P 到两焦点 F₁、F₂ 的距离之和为____（用 a 表示）","answer":"2a","analysis":"椭圆定义：|PF₁|+|PF₂|=2a。","id":"sy-g2-c3-l1-q3"},{"id":"sy-g2-c3-l3-e1","type":"essay","level":"简答","stem":"简答：写出抛物线 y²=2px（p>0）的焦点坐标与准线方程，并说明抛物线的定义。","ref":"焦点 (p/2,0)，准线 x=−p/2。定义：与定点（焦点）和定直线（准线）距离相等的点的轨迹（直线不经过焦点）。"},{"id":"sy-g2-c3-l3-e2","type":"essay","level":"简答","stem":"简答：说明抛物线的焦点弦的性质：\"焦点弦长最短为通径 2p\"。","ref":"过焦点垂直于对称轴的弦（通径）长为 2p，是最短的焦点弦；一般焦点弦两端点横坐标之积为定值 −p²/4（y²=2px 时）。"}]}]},{"id":"sy-g2-c4","name":"数列","book":"选择性必修第二册","grade":"高二","lessons":[{"id":"sy-g2-c4-l1","name":"4.1 等差数列","chapterId":"sy-g2-c4","chapterName":"数列","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"等差数列 a₁=2，d=3，则 a₅=","options":["14","15","12","17"],"answer":0,"analysis":"a₅=a₁+4d=2+12=14。","id":"sy-g2-c4-l1-q1"},{"type":"choice","level":"基础","stem":"若 a、b、c 成等差数列，则","options":["2b=a+c","b²=ac","b=a+c","a+b=c"],"answer":0,"analysis":"等差中项为两端之和的一半。","id":"sy-g2-c4-l1-q2"},{"type":"fill","level":"中档","stem":"等差数列中 a₃=7，a₇=15，则公差 d=____","answer":"2","analysis":"a₇−a₃=4d，8=4d，故 d=2。","id":"sy-g2-c4-l1-q3"},{"type":"fill","level":"中档","stem":"1/(1×2)+1/(2×3)+…+1/(9×10)=____","answer":"9/10","analysis":"裂项相消后剩 1−1/10=9/10。","id":"sy-g2-c4-l3-q3"},{"id":"sy-g2-c4-l1-e1","type":"essay","level":"简答","stem":"简答：写出等差数列的通项公式与前 n 项和公式，并说明判断等差数列的方法。","ref":"aₙ=a₁+(n−1)d；Sₙ=n(a₁+aₙ)/2=na₁+n(n−1)d/2。判定：aₙ₊₁−aₙ 为同一常数（定义法），或 2aₙ₊₁=aₙ+aₙ₊₂（中项法）。"},{"id":"sy-g2-c4-l1-e2","type":"essay","level":"简答","stem":"简答：说明等差数列前 n 项和 Sₙ 与 n 的函数关系及图象特征。","ref":"Sₙ=(d/2)n²+(a₁−d/2)n 是关于 n 的常数项为 0 的二次函数（d≠0 时），图象为抛物线上的离散点，开口由 d 决定。"}]},{"id":"sy-g2-c4-l2","name":"4.2 等比数列","chapterId":"sy-g2-c4","chapterName":"数列","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"等比数列 a₁=1，q=2，则 a₄=","options":["8","6","4","16"],"answer":0,"analysis":"a₄=a₁q³=8。","id":"sy-g2-c4-l2-q1"},{"type":"choice","level":"基础","stem":"若 a、b、c 成等比数列，则","options":["b²=ac","2b=a+c","b=ac","b²=a+c"],"answer":0,"analysis":"等比中项满足 b²=ac（同号）。","id":"sy-g2-c4-l2-q2"},{"type":"fill","level":"中档","stem":"等比数列 a₁=2，q=3，则 S₃=____","answer":"26","analysis":"S₃=2(1+3+9)=26。","id":"sy-g2-c4-l2-q3"},{"type":"fill","level":"中档","stem":"等差数列中 a₃=7，a₇=15，则公差 d=____","answer":"2","analysis":"a₇−a₃=4d，8=4d，故 d=2。","id":"sy-g2-c4-l1-q3"},{"id":"sy-g2-c4-l2-e1","type":"essay","level":"简答","stem":"简答：写出等比数列的通项公式与前 n 项和公式，并说明公比 q=1 时的特殊处理。","ref":"aₙ=a₁qⁿ⁻¹；q≠1 时 Sₙ=a₁(1−qⁿ)/(1−q)，q=1 时 Sₙ=na₁（求和公式分母 1−q 不能为 0，须分讨）。"},{"id":"sy-g2-c4-l2-e2","type":"essay","level":"简答","stem":"简答：说明等比数列各项均为正时，为什么取对数后成等差数列。","ref":"aₙ>0 时设 bₙ=lg aₙ，则 bₙ₊₁−bₙ=lg(aₙ₊₁/aₙ)=lg q 为常数，故 {bₙ} 是公差 lg q 的等差数列——指数运算与对数运算互逆的体现。"}]},{"id":"sy-g2-c4-l3","name":"4.3 通项与求和方法","chapterId":"sy-g2-c4","chapterName":"数列","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"等差数列通项公式为","options":["aₙ=a₁+(n−1)d","aₙ=a₁+nd","aₙ=a₁·dⁿ⁻¹","aₙ=n·d"],"answer":0,"analysis":"第 n 项比首项多加 n−1 个公差。","id":"sy-g2-c4-l3-q1"},{"type":"choice","level":"基础","stem":"裂项 1/[n(n+1)] 可写成","options":["1/n−1/(n+1)","1/n+1/(n+1)","1/n·1/(n+1)","n−(n+1)"],"answer":0,"analysis":"通分验证即可。","id":"sy-g2-c4-l3-q2"},{"type":"fill","level":"中档","stem":"1/(1×2)+1/(2×3)+…+1/(9×10)=____","answer":"9/10","analysis":"裂项相消后剩 1−1/10=9/10。","id":"sy-g2-c4-l3-q3"},{"type":"fill","level":"中档","stem":"等差数列中 a₃=7，a₇=15，则公差 d=____","answer":"2","analysis":"a₇−a₃=4d，8=4d，故 d=2。","id":"sy-g2-c4-l1-q3"},{"id":"sy-g2-c4-l3-e1","type":"essay","level":"简答","stem":"简答：叙述用\"累加法\"求形如 aₙ₊₁=aₙ+f(n) 的数列通项的步骤。","ref":"写出 a₂−a₁=f(1)，a₃−a₂=f(2)，…，aₙ−aₙ₋₁=f(n−1)；各式相加得 aₙ=a₁+∑f(k)（k=1 到 n−1），再验证 n=1 时成立。"},{"id":"sy-g2-c4-l3-e2","type":"essay","level":"简答","stem":"简答：说明裂项相消法求和的原理，并举 1/[n(n+1)] 型的例子。","ref":"把每项拆成两项之差，使和式中大部分项正负相消。1/[n(n+1)]=1/n−1/(n+1)，故前 n 项和=1−1/(n+1)=n/(n+1)。"}]}]},{"id":"sy-g2-c5","name":"导数及其应用","book":"选择性必修第二册","grade":"高二","lessons":[{"id":"sy-g2-c5-l1","name":"5.1 导数概念与切线","chapterId":"sy-g2-c5","chapterName":"导数及其应用","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"f(x)=x² 的导函数是","options":["2x","x","x²/2","2"],"answer":0,"analysis":"幂函数求导：(x²)′=2x。","id":"sy-g2-c5-l1-q1"},{"type":"choice","level":"基础","stem":"f(x)=x³，则 f′(1)=","options":["3","1","0","2"],"answer":0,"analysis":"f′(x)=3x²，代入 x=1 得 3。","id":"sy-g2-c5-l1-q2"},{"type":"fill","level":"中档","stem":"曲线 y=x² 在点 (1,1) 处的切线斜率为____","answer":"2","analysis":"k=f′(1)=2。","id":"sy-g2-c5-l1-q3"},{"type":"fill","level":"中档","stem":"f(x)=x³−3x 在 [0,2] 上的最小值为____","answer":"−2","analysis":"f(1)=−2 为极小值，与 f(0)=0、f(2)=2 比较得最小值 −2。","id":"sy-g2-c5-l3-q3"},{"id":"sy-g2-c5-l1-e1","type":"essay","level":"简答","stem":"简答：叙述导数的几何意义，并说明如何求曲线 y=f(x) 在点 (x₀,f(x₀)) 处的切线方程。","ref":"导数 f′(x₀) 是切线斜率。切线：y−f(x₀)=f′(x₀)(x−x₀)。注意切点必须在曲线上，切点坐标代入方程验证。"},{"id":"sy-g2-c5-l1-e2","type":"essay","level":"简答","stem":"简答：说明\"在某点处的导数\"与\"导函数\"的区别，并举瞬时速度的例子。","ref":"f′(x₀) 是函数在 x₀ 处的变化率（定值）；f′(x) 是导函数（随 x 变化）。例：位移 s=t²，t=1 时的瞬时速度 s′(1)=2 m/s 是定值，而任意时刻速度 v(t)=2t。"}]},{"id":"sy-g2-c5-l2","name":"5.2 单调性与极值","chapterId":"sy-g2-c5","chapterName":"导数及其应用","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"f(x)=x³−3x 的单调递减区间是","options":["(−1,1)","(−∞,−1)","(1,+∞)","R"],"answer":0,"analysis":"f′(x)=3x²−3<0 得 −1<x<1。","id":"sy-g2-c5-l2-q1"},{"type":"choice","level":"基础","stem":"在区间 I 上，若 f′(x)>0 恒成立，则 f(x) 在 I 上","options":["单调递增","单调递减","为常数","无单调性"],"answer":0,"analysis":"导数符号决定单调性。","id":"sy-g2-c5-l2-q2"},{"type":"fill","level":"中档","stem":"f(x)=x²−4x 的极小值为____","answer":"−4","analysis":"f′(x)=2x−4=0 得 x=2，f(2)=−4。","id":"sy-g2-c5-l2-q3"},{"type":"fill","level":"中档","stem":"f(x)=x³−3x 在 [0,2] 上的最小值为____","answer":"−2","analysis":"f(1)=−2 为极小值，与 f(0)=0、f(2)=2 比较得最小值 −2。","id":"sy-g2-c5-l3-q3"},{"id":"sy-g2-c5-l2-e1","type":"essay","level":"简答","stem":"简答：叙述用导数判断函数单调性的一般步骤，并举 f(x)=x³−3x 说明。","ref":"求定义域→求 f′(x)→解 f′(x)>0 得增区间、<0 得减区间。f′(x)=3x²−3>0 得 x>1 或 x<−1 为增区间，(−1,1) 为减区间。"},{"id":"sy-g2-c5-l2-e2","type":"essay","level":"简答","stem":"简答：说明极值与导数为零的关系，并举 f(x)=x³ 说明\"f′(x₀)=0 未必是极值点\"。","ref":"极值点是导数变号（左正右负为极大、左负右正为极小）的点。f(x)=x³ 的 f′(x)=3x² 在 x=0 为 0 但两侧不变号，故 x=0 不是极值点。"}]},{"id":"sy-g2-c5-l3","name":"5.3 闭区间最值与应用","chapterId":"sy-g2-c5","chapterName":"导数及其应用","book":"选择性必修第二册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"f(x)=x² 在 [1,3] 上的最大值是","options":["9","1","4","6"],"answer":0,"analysis":"在 [1,3] 上递增，最大值在 x=3 处取到。","id":"sy-g2-c5-l3-q1"},{"type":"choice","level":"基础","stem":"求闭区间上函数最值时，需要比较","options":["端点函数值与极值","只需比较端点","只需比较极值","只需比较导数为零的点"],"answer":0,"analysis":"闭区间最值取端点值与极值中的最大、最小者。","id":"sy-g2-c5-l3-q2"},{"type":"fill","level":"中档","stem":"f(x)=x³−3x 在 [0,2] 上的最小值为____","answer":"−2","analysis":"f(1)=−2 为极小值，与 f(0)=0、f(2)=2 比较得最小值 −2。","id":"sy-g2-c5-l3-q3"},{"type":"fill","level":"中档","stem":"曲线 y=x² 在点 (1,1) 处的切线斜率为____","answer":"2","analysis":"k=f′(1)=2。","id":"sy-g2-c5-l1-q3"},{"id":"sy-g2-c5-l3-e1","type":"essay","level":"简答","stem":"简答：叙述求 f(x) 在闭区间 [a,b] 上最值的步骤。","ref":"求 f′(x) 并解出极值点→计算区间内极值与端点值 f(a)、f(b)→比较大小，最大者为最大值，最小者为最小值。"},{"id":"sy-g2-c5-l3-e2","type":"essay","level":"简答","stem":"简答：举一个用导数解决实际优化问题的例子（如用料最省、利润最大），并说明建模步骤。","ref":"例：矩形周长一定求面积最大。步骤：设变量（一边长 x）→列目标函数 S(x) 与定义域→求导找极值→比较或由唯一极值确定最值→作答。"}]}]},{"id":"sy-g2-c6","name":"计数原理","book":"选择性必修第三册","grade":"高二","lessons":[{"id":"sy-g2-c6-l1","name":"6.1 分类加法与分步乘法","chapterId":"sy-g2-c6","chapterName":"计数原理","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"从甲地到乙地有 3 条路，乙地到丙地有 2 条路，则甲经乙到丙共有走法","options":["6 种","5 种","3 种","2 种"],"answer":0,"analysis":"分步计数用乘法：3×2=6。","id":"sy-g2-c6-l1-q1"},{"type":"choice","level":"基础","stem":"完成一件事有几类互不相同的办法，各类办法数相加，用的是","options":["分类加法计数原理","分步乘法计数原理","排列数公式","组合数公式"],"answer":0,"analysis":"分类用加法，分步用乘法。","id":"sy-g2-c6-l1-q2"},{"type":"fill","level":"中档","stem":"从 3 个不同元素中取 2 个的排列数 A(3,2)=____","answer":"6","analysis":"A(3,2)=3×2=6。","id":"sy-g2-c6-l1-q3"},{"type":"fill","level":"中档","stem":"(x+1)⁴ 展开式中 x² 的系数为____","answer":"6","analysis":"x² 对应 C(4,2)x²·1²=6x²。","id":"sy-g2-c6-l2-q3"},{"id":"sy-g2-c6-l1-e1","type":"essay","level":"简答","stem":"简答：说明分类加法计数原理与分步乘法计数原理的区别及判断标准。","ref":"加法原理：各类方案互斥、任完成一类即完成事情，总数为各类相加；乘法原理：须依次完成各步骤，总数为各步相乘。判断标准：完成任务\"或\"用加、\"且（分步）\"用乘。"},{"id":"sy-g2-c6-l1-e2","type":"essay","level":"简答","stem":"简答：说明排列与组合的区别，并举同一情境的排列数与组合数。","ref":"排列与顺序有关，组合与顺序无关。例：从 5 人中选 3 人参加活动（不计顺序）为组合 C₅³=10；选 3 人分别任三个不同职务（有顺序）为排列 A₅³=60。"}]},{"id":"sy-g2-c6-l2","name":"6.2 二项式定理","chapterId":"sy-g2-c6","chapterName":"计数原理","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"(a+b)ⁿ 展开式的第 k+1 项为","options":["C(n,k)aⁿ⁻ᵏbᵏ","C(n,k)aᵏbⁿ⁻ᵏ","C(n,k)aⁿbᵏ","aⁿ⁻ᵏbᵏ"],"answer":0,"analysis":"通项 T(k+1)=C(n,k)a^(n−k)b^k。","id":"sy-g2-c6-l2-q1"},{"type":"choice","level":"基础","stem":"(1+x)³ 展开式中各项系数之和为","options":["8","7","4","6"],"answer":0,"analysis":"令 x=1 得 2³=8。","id":"sy-g2-c6-l2-q2"},{"type":"fill","level":"中档","stem":"(x+1)⁴ 展开式中 x² 的系数为____","answer":"6","analysis":"x² 对应 C(4,2)x²·1²=6x²。","id":"sy-g2-c6-l2-q3"},{"type":"fill","level":"中档","stem":"从 3 个不同元素中取 2 个的排列数 A(3,2)=____","answer":"6","analysis":"A(3,2)=3×2=6。","id":"sy-g2-c6-l1-q3"},{"id":"sy-g2-c6-l2-e1","type":"essay","level":"简答","stem":"简答：写出二项式定理与通项公式，并说明如何求指定项的系数。","ref":"(a+b)ⁿ=ΣCₙᵏaⁿ⁻ᵏbᵏ（k=0..n），通项 Tₖ₊₁=Cₙᵏaⁿ⁻ᵏbᵏ。求指定项：令通项中字母次数等于目标次数解出 k，再代入计算。"},{"id":"sy-g2-c6-l2-e2","type":"essay","level":"简答","stem":"简答：说明二项式系数 Cₙᵏ 与该项系数的区别，并举 (1+2x)ⁿ 中的例子。","ref":"二项式系数是 Cₙᵏ；项的系数还包含字母上的数字因子。例 (1+2x)⁵ 中含 x² 的项：T₃=C₅²(2x)²=10·4x²=40x²，二项式系数 C₅²=10，而系数为 40。"}]}]},{"id":"sy-g2-c7","name":"随机变量及其分布","book":"选择性必修第三册","grade":"高二","lessons":[{"id":"sy-g2-c7-l1","name":"7.1 离散型随机变量与分布列","chapterId":"sy-g2-c7","chapterName":"随机变量及其分布","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"离散型随机变量分布列中各概率之和必须等于","options":["1","0","样本容量","期望"],"answer":0,"analysis":"所有可能取值的概率和为 1。","id":"sy-g2-c7-l1-q1"},{"type":"choice","level":"基础","stem":"E(X) 的计算公式是","options":["Σxᵢpᵢ","Σpᵢ","Σxᵢ","max xᵢ"],"answer":0,"analysis":"期望为取值与对应概率乘积之和。","id":"sy-g2-c7-l1-q2"},{"type":"fill","level":"中档","stem":"X 只取 0、1，且 P(X=1)=0.3，则 E(X)=____","answer":"0.3","analysis":"E(X)=0×0.7+1×0.3=0.3。","id":"sy-g2-c7-l1-q3"},{"type":"fill","level":"中档","stem":"若 X~N(2,σ²)，则 P(X<2)=____","answer":"0.5","analysis":"正态曲线关于 x=2 对称，左右各占一半。","id":"sy-g2-c7-l3-q3"},{"id":"sy-g2-c7-l1-e1","type":"essay","level":"简答","stem":"简答：叙述离散型随机变量分布列的两条基本性质，并说明其用途。","ref":"①pᵢ≥0（i=1,2,…,n）；②Σpᵢ=1。用途：求出概率后验证是否构成分布列；可利用 Σ=1 求未知参数。"},{"id":"sy-g2-c7-l1-e2","type":"essay","level":"简答","stem":"简答：写出期望 E(X) 的定义，并说明期望与\"平均数\"的关系。","ref":"E(X)=Σxᵢpᵢ，即以概率为权重的加权平均，反映随机变量取值的平均水平。长期重复试验中取值的平均稳定于期望。"}]},{"id":"sy-g2-c7-l2","name":"7.2 二项分布与期望方差","chapterId":"sy-g2-c7","chapterName":"随机变量及其分布","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"若 X~B(n,p)，则 E(X)=","options":["np","n/p","p/n","n(1−p)"],"answer":0,"analysis":"二项分布期望为 np。","id":"sy-g2-c7-l2-q1"},{"type":"choice","level":"基础","stem":"若 X~B(n,p)，则 D(X)=","options":["np(1−p)","np","n²p","p(1−p)"],"answer":0,"analysis":"二项分布方差公式。","id":"sy-g2-c7-l2-q2"},{"type":"fill","level":"中档","stem":"X~B(10,0.2)，则 E(X)=____","answer":"2","analysis":"E(X)=10×0.2=2。","id":"sy-g2-c7-l2-q3"},{"type":"fill","level":"中档","stem":"若 X~N(2,σ²)，则 P(X<2)=____","answer":"0.5","analysis":"正态曲线关于 x=2 对称，左右各占一半。","id":"sy-g2-c7-l3-q3"},{"id":"sy-g2-c7-l2-e1","type":"essay","level":"简答","stem":"简答：写出二项分布 X~B(n,p) 的概率公式、期望与方差公式。","ref":"P(X=k)=Cₙᵏpᵏ(1−p)ⁿ⁻ᵏ；E(X)=np，D(X)=np(1−p)。适用于 n 次独立重复试验中\"成功\"次数。"},{"id":"sy-g2-c7-l2-e2","type":"essay","level":"简答","stem":"简答：说明方差 D(X) 的意义，并举两个期望相同但方差不同的例子。","ref":"方差反映取值的离散（波动）程度，D(X) 越大越不稳定。例：甲、乙射击平均命中数都是 0.8，甲波动小（方差小）则成绩更稳定；应选方差小的选手。"}]},{"id":"sy-g2-c7-l3","name":"7.3 正态分布","chapterId":"sy-g2-c7","chapterName":"随机变量及其分布","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"正态曲线关于直线","options":["x=μ 对称","x=σ 对称","y 轴对称","原点对称"],"answer":0,"analysis":"正态分布由均值 μ 决定对称轴。","id":"sy-g2-c7-l3-q1"},{"type":"choice","level":"基础","stem":"标准正态分布的参数为","options":["μ=0，σ=1","μ=1，σ=0","μ=1，σ=1","μ=0，σ=0"],"answer":0,"analysis":"标准正态记为 N(0,1)。","id":"sy-g2-c7-l3-q2"},{"type":"fill","level":"中档","stem":"若 X~N(2,σ²)，则 P(X<2)=____","answer":"0.5","analysis":"正态曲线关于 x=2 对称，左右各占一半。","id":"sy-g2-c7-l3-q3"},{"type":"fill","level":"中档","stem":"X~B(10,0.2)，则 E(X)=____","answer":"2","analysis":"E(X)=10×0.2=2。","id":"sy-g2-c7-l2-q3"},{"id":"sy-g2-c7-l3-e1","type":"essay","level":"简答","stem":"简答：写出正态分布密度曲线的对称轴、3σ 原则的含义。","ref":"曲线关于 x=μ 对称，μ 决定位置、σ 决定\"高瘦/矮胖\"。3σ 原则：P(μ−σ<X<μ+σ)≈68.3%，P(μ−2σ,μ+2σ)≈95.4%，P(μ−3σ,μ+3σ)≈99.7%。"},{"id":"sy-g2-c7-l3-e2","type":"essay","level":"简答","stem":"简答：说明利用正态分布对称性求概率的方法，并举 X~N(2,σ²) 时 P(X<2) 的例子。","ref":"利用曲线关于 x=μ 对称：左右两侧概率各半、P(X<μ+kσ)=1−P(X<μ−kσ)。例：X~N(2,σ²) 时 P(X<2)=0.5（对称轴处）。"}]}]},{"id":"sy-g2-c8","name":"成对数据的统计分析","book":"选择性必修第三册","grade":"高二","lessons":[{"id":"sy-g2-c8-l1","name":"8.1 相关关系与回归直线","chapterId":"sy-g2-c8","chapterName":"成对数据的统计分析","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"样本相关系数 r 的取值范围是","options":["[−1,1]","[0,1]","R","[−1,0]"],"answer":0,"analysis":"相关系数绝对值不超过 1。","id":"sy-g2-c8-l1-q1"},{"type":"choice","level":"基础","stem":"若 r>0，则两个变量","options":["正相关","负相关","不相关","完全相关"],"answer":0,"analysis":"r 的符号反映相关方向。","id":"sy-g2-c8-l1-q2"},{"type":"fill","level":"中档","stem":"经验回归直线一定经过的点的坐标是____","answer":"(x̄,ȳ)","analysis":"回归直线过样本中心点。","id":"sy-g2-c8-l1-q3"},{"type":"fill","level":"中档","stem":"χ² 公式中分子含有的式子是____（用 a、b、c、d 表示，写出关键部分）","answer":"(ad−bc)²","analysis":"χ²=n(ad−bc)²/[(a+b)(c+d)(a+c)(b+d)]。","id":"sy-g2-c8-l2-q3"},{"id":"sy-g2-c8-l1-e1","type":"essay","level":"简答","stem":"简答：说明散点图与相关系数 r 在判断相关关系中的作用。","ref":"散点图直观展示两变量是否线性相关及方向；r∈[−1,1]，|r| 越接近 1 线性相关越强，r>0 正相关、r<0 负相关。"},{"id":"sy-g2-c8-l1-e2","type":"essay","level":"简答","stem":"简答：叙述回归直线 ŷ=bx+a 中 a、b 的最小二乘法求法及回归直线经过的定点。","ref":"b=Σ(xᵢ−x̄)(yᵢ−ȳ)/Σ(xᵢ−x̄)²，a=ȳ−bx̄。回归直线必过样本中心点 (x̄,ȳ)。"}]},{"id":"sy-g2-c8-l2","name":"8.2 独立性检验","chapterId":"sy-g2-c8","chapterName":"成对数据的统计分析","book":"选择性必修第三册","grade":"高二","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"独立性检验中，χ² 的值越大，说明","options":["两个分类变量有关的把握越大","两个变量一定无关","样本容量越小","相关性越弱"],"answer":0,"analysis":"χ² 越大，拒绝\"无关\"的依据越强。","id":"sy-g2-c8-l2-q1"},{"type":"choice","level":"基础","stem":"独立性检验使用的表格称为","options":["2×2 列联表","频率分布表","分布列","回归表"],"answer":0,"analysis":"两个分类变量各取两个值，构成 2×2 列联表。","id":"sy-g2-c8-l2-q2"},{"type":"fill","level":"中档","stem":"χ² 公式中分子含有的式子是____（用 a、b、c、d 表示，写出关键部分）","answer":"(ad−bc)²","analysis":"χ²=n(ad−bc)²/[(a+b)(c+d)(a+c)(b+d)]。","id":"sy-g2-c8-l2-q3"},{"type":"fill","level":"中档","stem":"经验回归直线一定经过的点的坐标是____","answer":"(x̄,ȳ)","analysis":"回归直线过样本中心点。","id":"sy-g2-c8-l1-q3"},{"id":"sy-g2-c8-l2-e1","type":"essay","level":"简答","stem":"简答：叙述独立性检验的基本思路及 χ²（卡方）统计量大小与结论的关系。","ref":"用 2×2 列联表计算 χ²，与临界值比较：χ² 越大，\"两变量有关\"的把握越大；超过临界值则认为有关（在相应置信水平下）。注意：检验结论是概率意义上的相关，不是因果。"},{"id":"sy-g2-c8-l2-e2","type":"essay","level":"简答","stem":"简答：说明独立性检验与反证法的异同。","ref":"相同：都是\"假设—检验—推翻或接受\"的思路。不同：反证法在逻辑上必然推翻（确定性）；独立性检验由样本推断，以显著性水平表达把握大小（随机性，可能犯错）。"}]}]}],"高三二轮":[{"id":"sy-g3-c1","name":"函数与导数综合","book":"二轮专题复习","grade":"高三","lessons":[{"id":"sy-g3-c1-l1","name":"专题1-1 单调性与参数范围","chapterId":"sy-g3-c1","chapterName":"函数与导数综合","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"若函数 f(x)=x³−3ax 在区间 (0,1) 上单调递减，则实数 a 的取值范围是","options":["a≥1","0<a<1","a≥0","a>1"],"answer":0,"analysis":"f′(x)=3x²−3a≤0 在 (0,1) 上恒成立，即 a≥x² 恒成立。x∈(0,1) 时 x² 的上确界为 1，故 a≥1。","id":"sy-g3-c1-l1-q1"},{"type":"choice","level":"较难","stem":"函数 f(x)=x³−3x 在 [−2,2] 上的最大值与最小值之差为","options":["6","2","0","4"],"answer":3,"analysis":"f′(x)=3x²−3，驻点 x=±1。端点与驻点函数值：f(−2)=−2，f(−1)=2，f(1)=−2，f(2)=2。最大值 2 与最小值 −2 之差为 4。","id":"sy-g3-c1-l1-q4"},{"type":"fill","level":"中档","stem":"函数 f(x)=x−ln x 的最小值为____","answer":"1","analysis":"f′(x)=1−1/x：0<x<1 时 f′<0，x>1 时 f′>0，故 x=1 处取最小值 f(1)=1。","id":"sy-g3-c1-l1-q2"},{"type":"fill","level":"中档","stem":"若 f(x)=eˣ−ax 在 R 上单调递增，则实数 a 的最大值为____","answer":"0","analysis":"f′(x)=eˣ−a≥0 恒成立，即 a≤eˣ。eˣ 恒正且可无限接近 0，故 a≤0，最大值为 0。","id":"sy-g3-c1-l1-q3"},{"id":"sy-g3-c1-l1-e1","type":"essay","level":"简答","stem":"简答：说明含参数函数单调性问题的讨论要点（按什么顺序分类）。","ref":"按\"二次项系数是否为 0→判别式→根的大小与定义域关系→导数零点是否在定义域内\"的顺序不重不漏地讨论，最后汇总各类的单调区间。"},{"id":"sy-g3-c1-l1-e2","type":"essay","level":"简答","stem":"简答：说明\"已知单调区间求参数范围\"的转化方法。","ref":"转化为导数在该区间上≥0（增）或≤0（减）恒成立，且在端点处导数可以为 0（单调区间是闭可开闭），用分离参数或最值法求范围。"}]},{"id":"sy-g3-c1-l2","name":"专题1-2 零点与恒成立","chapterId":"sy-g3-c1","chapterName":"函数与导数综合","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"方程 ln x=x−2 的实根个数为","options":["3","1","2","0"],"answer":2,"analysis":"令 g(x)=ln x−x+2。g(0.5)>0 而 x→0⁺ 时 g→−∞，得一根在 (0,0.5)；g(3)>0、g(4)<0，得一根在 (3,4)。g 在 (0,1) 递增、(1,+∞) 递减，故恰有 2 个实根。","id":"sy-g3-c1-l2-q1"},{"type":"choice","level":"较难","stem":"函数 f(x)=x³−3x 在 [−2,2] 上的最大值与最小值之差为","options":["6","2","0","4"],"answer":3,"analysis":"f′(x)=3x²−3，驻点 x=±1。端点与驻点函数值：f(−2)=−2，f(−1)=2，f(1)=−2，f(2)=2。最大值 2 与最小值 −2 之差为 4。","id":"sy-g3-c1-l1-q4"},{"type":"fill","level":"中档","stem":"函数 f(x)=x²−2ln x 的极小值为____","answer":"1","analysis":"f′(x)=2x−2/x，令其为 0 得 x=1（x>0）。x<1 时 f′<0，x>1 时 f′>0，故极小值 f(1)=1。","id":"sy-g3-c1-l2-q2"},{"type":"fill","level":"中档","stem":"若对任意 x>0，不等式 x²−ax+1≥0 恒成立，则 a 的最大值为____","answer":"2","analysis":"变形得 a≤x+1/x。由基本不等式 x+1/x≥2（x=1 取等），故 a≤2，最大值为 2。","id":"sy-g3-c1-l2-q3"},{"id":"sy-g3-c1-l2-e1","type":"essay","level":"简答","stem":"简答：说明用函数零点个数解决\"方程有解\"问题的转化思路。","ref":"方程 f(x)=g(x) 有解 ⇔ 函数 F(x)=f(x)−g(x) 有零点 ⇔ 两函数图象 y=f(x) 与 y=g(x) 有交点；常借助数形结合或单调性+零点存在定理说明个数。"},{"id":"sy-g3-c1-l2-e2","type":"essay","level":"简答","stem":"简答：说明恒成立问题中\"分离参数法\"的步骤与易错点。","ref":"步骤：把参数与变量分离→转化为 a≥h(x) 恒成立（a≥h(x)max）或 a≤h(x)min。易错点：h(x) 最值须在定义域内求；不等号是否带等号决定取值端点能否取得。"}]},{"id":"sy-g3-c1-l3","name":"专题1-3 切线与极值应用","chapterId":"sy-g3-c1","chapterName":"函数与导数综合","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"若 f(x)=x³+ax²+bx 在 x=1 处取得极值 0，则 a+b 的值为","options":["−1","0","−3","1"],"answer":0,"analysis":"由 f(1)=1+a+b=0 与 f′(1)=3+2a+b=0 相减得 a=−2，代回得 b=1，故 a+b=−1。","id":"sy-g3-c1-l3-q2"},{"type":"choice","level":"中档","stem":"方程 ln x=x−2 的实根个数为","options":["3","1","2","0"],"answer":2,"analysis":"令 g(x)=ln x−x+2。g(0.5)>0 而 x→0⁺ 时 g→−∞，得一根在 (0,0.5)；g(3)>0、g(4)<0，得一根在 (3,4)。g 在 (0,1) 递增、(1,+∞) 递减，故恰有 2 个实根。","id":"sy-g3-c1-l2-q1"},{"type":"fill","level":"基础","stem":"曲线 y=eˣ 在 x=0 处的切线方程为____","answer":"y=x+1","analysis":"x=0 时 y=1，y′=e⁰=1，切线为 y−1=1·(x−0)，即 y=x+1。","id":"sy-g3-c1-l3-q1"},{"type":"fill","level":"中档","stem":"周长为 20 的矩形面积的最大值为____","answer":"25","analysis":"设一边为 x，则另一边为 10−x，面积 S=x(10−x)≤25，x=5 时取等号。","id":"sy-g3-c1-l3-q3"},{"id":"sy-g3-c1-l3-e1","type":"essay","level":"简答","stem":"简答：说明\"过曲线上一点的切线\"与\"过曲线外一点的切线\"处理上的差别。","ref":"曲线上一点：直接以该点为切点，斜率 f′(x₀)。曲线外一点：设切点 (t, f(t))，由\"切点在曲线上+斜率等于连线斜率\"两个方程解出 t，可能有多解。"},{"id":"sy-g3-c1-l3-e2","type":"essay","level":"简答","stem":"简答：说明如何用导数研究\"含 x₀ 的极值点问题\"（已知极值求参数）。","ref":"由极值点处 f′(x₀)=0 列参数方程求参数；必要时再验证导数在该点两侧变号（防止 x³ 型假极值），并检查定义域。"}]}]},{"id":"sy-g3-c2","name":"三角函数与解三角形","book":"二轮专题复习","grade":"高三","lessons":[{"id":"sy-g3-c2-l1","name":"专题2-1 恒等变换与图像","chapterId":"sy-g3-c2","chapterName":"三角函数与解三角形","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"sin 75° 的值为","options":["(√6−√2)/4","(√6+√2)/4","(√2−√6)/4","1/2"],"answer":1,"analysis":"sin75°=sin(45°+30°)=sin45°cos30°+cos45°sin30°=(√6+√2)/4。","id":"sy-g3-c2-l1-q1"},{"type":"choice","level":"中档","stem":"将 y=sin2x 的图像向左平移 π/6 个单位，所得图像的解析式为","options":["y=sin(2x+π/12)","y=sin(2x+π/3)","y=sin(2x−π/3)","y=sin(2x+π/6)"],"answer":1,"analysis":"左移 π/6 即把 x 换成 x+π/6：sin2(x+π/6)=sin(2x+π/3)。注意平移量要乘 ω。","id":"sy-g3-c2-l1-q3"},{"type":"fill","level":"基础","stem":"函数 y=2sin(2x+π/6) 的最小正周期为____","answer":"π","analysis":"最小正周期 T=2π/ω=2π/2=π。","id":"sy-g3-c2-l1-q2"},{"type":"fill","level":"中档","stem":"cos²22.5°−sin²22.5° 的值为____","answer":"√2/2","analysis":"由二倍角公式，原式=cos45°=√2/2。","id":"sy-g3-c2-l1-q4"},{"id":"sy-g3-c2-l1-e1","type":"essay","level":"简答","stem":"简答：说明 y=Asin(ωx+φ)+k 中各参数对图象的影响。","ref":"A 影响振幅（最大最小值 k±A）；ω 影响周期 T=2π/ω；φ 影响左右平移（x+φ：φ>0 左移）；k 上下平移。"},{"id":"sy-g3-c2-l1-e2","type":"essay","level":"简答","stem":"简答：说明求 y=Asin(ωx+φ)+k 在给定区间上最值的方法。","ref":"令 t=ωx+φ，由 x 区间求出 t 的范围，再按正弦函数在 t 范围上的图象取最大、最小值，最后加 k 并乘 A。"}]},{"id":"sy-g3-c2-l2","name":"专题2-2 解三角形","chapterId":"sy-g3-c2","chapterName":"三角函数与解三角形","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"在 △ABC 中，a=3，b=4，C=90°，则 c=","options":["25","5","7","√7"],"answer":1,"analysis":"由勾股定理 c²=3²+4²=25，故 c=5。","id":"sy-g3-c2-l2-q1"},{"type":"choice","level":"易错","stem":"在 △ABC 中，a=2，b=2√3，A=30°，则 B=","options":["120°","30°","60°","60° 或 120°"],"answer":3,"analysis":"由正弦定理 sinB=bsinA/a=(2√3×0.5)/2=√3/2。因 b>a，故 B>A，60° 与 120° 都满足，出现两解。","id":"sy-g3-c2-l2-q2"},{"type":"fill","level":"中档","stem":"在 △ABC 中，A=60°，b=1，面积为 √3，则 c=____","answer":"4","analysis":"S=½bcsinA=½×1×c×(√3/2)=√3c/4=√3，解得 c=4。","id":"sy-g3-c2-l2-q3"},{"type":"fill","level":"中档","stem":"在 △ABC 中，sinA:sinB:sinC=3:5:7，则最大角为____","answer":"120°","analysis":"由正弦定理 a:b:c=3:5:7。cosC=(9+25−49)/(2×3×5)=−1/2，故 C=120°。","id":"sy-g3-c2-l2-q4"},{"id":"sy-g3-c2-l2-e1","type":"essay","level":"简答","stem":"简答：解三角形应用题（测量距离、高度、角度）的一般建模步骤。","ref":"画示意图→把实际问题抽象成三角形（标注已知角与边）→选正弦或余弦定理→解出目标量→按实际意义取近似并作答（注意仰角俯角、方位角含义）。"},{"id":"sy-g3-c2-l2-e2","type":"essay","level":"简答","stem":"简答：说明已知两边及其中一边的对角时解三角形可能出现的解的个数情形。","ref":"设已知 a、b、A：①a≥b 时唯一解（大边对大角）；②a<b 时比较 a 与 b·sinA：a<b·sinA 无解、a=b·sinA 一解（直角）、b·sinA<a<b 两解。"}]},{"id":"sy-g3-c2-l3","name":"专题2-3 三角最值与实际应用","chapterId":"sy-g3-c2","chapterName":"三角函数与解三角形","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"函数 f(x)=sinx+√3cosx 的最大值为","options":["1","4","√3","2"],"answer":3,"analysis":"辅助角公式：sinx+√3cosx=2sin(x+π/3)，最大值为 2。","id":"sy-g3-c2-l3-q1"},{"type":"choice","level":"中档","stem":"把 y=3sin2x 图像上所有点的横坐标伸长到原来的 2 倍（纵坐标不变），所得函数的最小正周期为","options":["4π","π","π/2","2π"],"answer":3,"analysis":"横坐标伸长 2 倍使 ω 由 2 变为 1，新函数 y=3sinx，周期 T=2π。","id":"sy-g3-c2-l3-q4"},{"type":"fill","level":"中档","stem":"函数 f(x)=2sinxcosx+2cos²x−1 的最大值为____","answer":"√2","analysis":"化简得 f(x)=sin2x+cos2x=√2sin(2x+π/4)，最大值为 √2。","id":"sy-g3-c2-l3-q2"},{"type":"fill","level":"中档","stem":"周长为 8 的扇形面积最大时，其半径为____","answer":"2","analysis":"设半径为 r，弧长为 8−2r，S=½r(8−2r)=4r−r²，r=2 时取最大值 4。","id":"sy-g3-c2-l3-q3"},{"id":"sy-g3-c2-l3-e1","type":"essay","level":"简答","stem":"简答：说明△ABC 中求\"边角混合式\"最值的常用工具（正弦定理边化角、余弦定理角化边）。","ref":"统一变量：用正弦定理把边化为角的正弦，利用 A+B+C=π 消元后化为三角函数最值；或用余弦定理把角化边，用基本不等式求范围。注意定义域限制。"},{"id":"sy-g3-c2-l3-e2","type":"essay","level":"简答","stem":"简答：举一个三角形的面积公式选择问题，并说明何时用 S=½ab·sinC 而不是 ½ah。","ref":"已知两边及其夹角时用 S=½ab·sinC（无需再求高）；已知底和高（或可求高）时用 ½ah。测量类问题中夹角往往已知，用含角公式更直接。"}]}]},{"id":"sy-g3-c3","name":"数列","book":"二轮专题复习","grade":"高三","lessons":[{"id":"sy-g3-c3-l1","name":"专题3-1 递推与通项","chapterId":"sy-g3-c3","chapterName":"数列","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"数列 {aₙ} 满足 a₁=1，aₙ₊₁=2aₙ+1，则 aₙ=","options":["2ⁿ","2ⁿ+1","2ⁿ⁻¹−1","2ⁿ−1"],"answer":3,"analysis":"两边加 1 得 aₙ₊₁+1=2(aₙ+1)，故 {aₙ+1} 是首项 2、公比 2 的等比数列，aₙ+1=2ⁿ，aₙ=2ⁿ−1。","id":"sy-g3-c3-l1-q1"},{"type":"choice","level":"基础","stem":"等差数列中 a₃=7，a₇=15，则 a₁₀=","options":["19","21","25","23"],"answer":1,"analysis":"公差 d=(15−7)/4=2，a₁=7−2×2=3，故 a₁₀=3+9×2=21。","id":"sy-g3-c3-l1-q4"},{"type":"fill","level":"中档","stem":"数列 {aₙ} 中 a₁=1，aₙ₊₁−aₙ=2n，则 aₙ=____","answer":"n²−n+1","analysis":"累加得 aₙ=1+2(1+2+…+(n−1))=1+n(n−1)=n²−n+1。","id":"sy-g3-c3-l1-q2"},{"type":"fill","level":"基础","stem":"等比数列中 a₁=2，公比 q=3，则 a₅=____","answer":"162","analysis":"a₅=a₁q⁴=2×81=162。","id":"sy-g3-c3-l1-q3"},{"id":"sy-g3-c3-l1-e1","type":"essay","level":"简答","stem":"简答：说明形如 aₙ₊₁=paₙ+q 的数列化为等比数列的方法（待定系数法）。","ref":"设 aₙ₊₁+λ=p(aₙ+λ)，展开比较得 λ=q/(p−1)（p≠1），则 {aₙ+λ} 是公比 p 的等比数列，先求 a₁+λ 再写通项。"},{"id":"sy-g3-c3-l1-e2","type":"essay","level":"简答","stem":"简答：说明已知 Sₙ 求 aₙ 的方法及易错点。","ref":"n≥2 时 aₙ=Sₙ−Sₙ₋₁，n=1 时 a₁=S₁；须检验 Sₙ−Sₙ₋₁ 在 n=1 时的表达式是否也适用 a₁，不适用时分段写。易错点：漏验 n=1。"}]},{"id":"sy-g3-c3-l2","name":"专题3-2 数列求和","chapterId":"sy-g3-c3","chapterName":"数列","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"1/(1×2)+1/(2×3)+…+1/(n(n+1))=","options":["n/(n+2)","n/(n+1)","1/(n+1)","(n+1)/n"],"answer":1,"analysis":"裂项相消：各项为 1/k−1/(k+1)，求和得 1−1/(n+1)=n/(n+1)。","id":"sy-g3-c3-l2-q1"},{"type":"choice","level":"较难","stem":"数列 {n·2ⁿ} 的前 n 项和为","options":["(n−1)2ⁿ⁺¹+2","(n+1)2ⁿ⁺¹+2","n·2ⁿ⁺¹","(n−1)2ⁿ+2"],"answer":0,"analysis":"错位相减可得 Sₙ=(n−1)2ⁿ⁺¹+2。取 n=1 检验：(0)×4+2=2，与实际首项 1×2=2 相符。","id":"sy-g3-c3-l2-q3"},{"type":"fill","level":"基础","stem":"数列 1,3,5,…,2n−1 的前 n 项和为____","answer":"n²","analysis":"这是首项 1、公差 2 的等差数列，Sₙ=n(1+2n−1)/2=n²。","id":"sy-g3-c3-l2-q2"},{"type":"fill","level":"中档","stem":"等比数列 1/2，1/4，1/8，… 各项之和为____","answer":"1","analysis":"首项 1/2、公比 1/2，无穷递缩等比数列求和 S=a₁/(1−q)=(1/2)/(1/2)=1。","id":"sy-g3-c3-l2-q4"},{"id":"sy-g3-c3-l2-e1","type":"essay","level":"简答","stem":"简答：叙述错位相减法适用的数列特征与操作步骤。","ref":"适用于\"等差×等比\"型（如 aₙ=n·2ⁿ）。步骤：写 Sₙ→两边乘公比 q 写 qSₙ→两式错位相减→右侧化为等比数列求和→解出 Sₙ。注意最后讨论 q=1。"},{"id":"sy-g3-c3-l2-e2","type":"essay","level":"简答","stem":"简答：说明并项求和法适用的情形并举例。","ref":"适用于通项正负交替或周期变化（如 aₙ=(−1)ⁿn）。相邻两项并成一组，每组结果规律相同，按组数奇偶分讨求和。例：(−1)ⁿn 两两并组，每组为 −1。"}]},{"id":"sy-g3-c3-l3","name":"专题3-3 通项与求和综合","chapterId":"sy-g3-c3","chapterName":"数列","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"等比数列 a₁=1，q=2，则前 n 项和 Sₙ=","options":["2ⁿ⁺¹−1","2ⁿ⁻¹","2ⁿ−1","2ⁿ"],"answer":2,"analysis":"Sₙ=a₁(1−qⁿ)/(1−q)=(1−2ⁿ)/(−1)=2ⁿ−1。","id":"sy-g3-c3-l3-q2"},{"type":"choice","level":"中档","stem":"数列 {1/(n(n+1))} 的前 n 项和 Tₙ 满足","options":["Tₙ<1 恒成立","Tₙ=1","Tₙ 无上界","Tₙ>1 恒成立"],"answer":0,"analysis":"Tₙ=n/(n+1)<1，且随 n 增大趋近于 1。","id":"sy-g3-c3-l3-q3"},{"type":"fill","level":"中档","stem":"若数列前 n 项和 Sₙ=n²+n，则 aₙ=____","answer":"2n","analysis":"n≥2 时 aₙ=Sₙ−Sₙ₋₁=2n；n=1 时 a₁=S₁=2 也满足该式。","id":"sy-g3-c3-l3-q1"},{"type":"fill","level":"基础","stem":"等差数列首项为 1、公差为 2，其前 n 项和 Sₙ=____","answer":"n²","analysis":"Sₙ=n×1+n(n−1)/2×2=n+n(n−1)=n²。","id":"sy-g3-c3-l3-q4"},{"id":"sy-g3-c3-l3-e1","type":"essay","level":"简答","stem":"简答：说明数列与不等式综合问题中\"放缩法\"的基本思路。","ref":"把通项放缩为可求和的形式（如 1/n² 放缩为 1/[n(n−1)]），使和易于估计，从而证明 Sₙ<T 或 >T；注意放缩方向与目标不等式一致、首项单独处理。"},{"id":"sy-g3-c3-l3-e2","type":"essay","level":"简答","stem":"简答：说明如何求数列 {aₙ} 的最大项（或最小项）。","ref":"方法一：把 aₙ 看作 n 的函数，研究其单调性（作商/作差判断 aₙ₊₁ 与 aₙ 大小）；方法二：解不等式组 aₙ≥aₙ₊₁ 且 aₙ≥aₙ₋₁ 定位最大项。"}]}]},{"id":"sy-g3-c4","name":"立体几何与空间向量","book":"二轮专题复习","grade":"高三","lessons":[{"id":"sy-g3-c4-l1","name":"专题4-1 位置关系与体积","chapterId":"sy-g3-c4","chapterName":"立体几何与空间向量","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"正方体 ABCD-A₁B₁C₁D₁ 中，异面直线 AB₁ 与 BC₁ 所成的角为","options":["30°","60°","90°","45°"],"answer":1,"analysis":"连接 AD₁，则 BC₁∥AD₁，于是 ∠B₁AD₁ 即为所求。△AB₁D₁ 为等边三角形，故夹角 60°。","id":"sy-g3-c4-l1-q1"},{"type":"choice","level":"中档","stem":"圆锥底面半径为 3、高为 4，则其侧面积为","options":["24π","9π","12π","15π"],"answer":3,"analysis":"母线 l=√(3²+4²)=5，侧面积 S=πrl=π×3×5=15π。","id":"sy-g3-c4-l3-q4"},{"type":"fill","level":"中档","stem":"棱长为 2 的正四面体体积为____","answer":"2√2/3","analysis":"正四面体体积 V=a³/(6√2)=8/(6√2)=2√2/3。","id":"sy-g3-c4-l1-q2"},{"type":"fill","level":"基础","stem":"底面积为 6、高为 4 的三棱锥体积为____","answer":"8","analysis":"V=⅓Sh=⅓×6×4=8。","id":"sy-g3-c4-l1-q3"},{"id":"sy-g3-c4-l1-e1","type":"essay","level":"简答","stem":"简答：叙述证明线面垂直的常用路径（至少三条）。","ref":"①判定定理：垂直面内两相交直线；②平行传递：a∥b，b⊥α 则 a⊥α；③面面垂直的性质：α⊥β，α∩β=l，a⊂α 且 a⊥l 则 a⊥β。"},{"id":"sy-g3-c4-l1-e2","type":"essay","level":"简答","stem":"简答：说明求几何体体积的\"割补法\"思路并举一例。","ref":"不规则或不易直接求的几何体，可分割成棱锥、棱柱之和，或补成易求体积的几何体作差。例：三棱锥补成三棱柱（三棱锥体积为同底等高三棱柱的 1/3）。"}]},{"id":"sy-g3-c4-l2","name":"专题4-2 空间向量法","chapterId":"sy-g3-c4","chapterName":"立体几何与空间向量","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"若平面 α 的法向量为 (1,2,−1)，平面 β 的法向量为 (−2,1,0)，则 α 与 β 所成的二面角为","options":["30°","90°","60°","45°"],"answer":1,"analysis":"两法向量数量积为 −2+2+0=0，互相垂直，故两平面垂直，夹角 90°。","id":"sy-g3-c4-l2-q1"},{"type":"choice","level":"中档","stem":"直线 l 的方向向量为 (1,0,0)，平面 α 的法向量为 (0,1,0)，则 l 与 α 的位置关系是","options":["l 与 α 斜交","无法确定","l⊥α","l∥α 或 l⊂α"],"answer":3,"analysis":"方向向量与法向量数量积为 0，说明方向向量平行于平面，故 l 平行于 α 或在 α 内。","id":"sy-g3-c4-l2-q3"},{"type":"fill","level":"中档","stem":"点 (1,1,1) 到平面 x+2y+2z−3=0 的距离为____","answer":"2/3","analysis":"由点到平面距离公式 d=|1+2+2−3|/√(1+4+4)=2/3。","id":"sy-g3-c4-l2-q2"},{"type":"fill","level":"较难","stem":"正方体 ABCD-A₁B₁C₁D₁ 棱长为 1，则点 A 到平面 BDC₁ 的距离为____","answer":"√3/3","analysis":"以 A 为原点、AB、AD、AA₁ 为坐标轴，B(1,0,0)、D(0,1,0)、C₁(1,1,1)。平面 BDC₁ 的方程为 x+y−z−1=0，点 A(0,0,0) 到它的距离为 |−1|/√3=√3/3。","id":"sy-g3-c4-l2-q4"},{"id":"sy-g3-c4-l2-e1","type":"essay","level":"简答","stem":"简答：说明建立空间坐标系时坐标原点与轴的选取原则。","ref":"选两两垂直的三条棱为轴、公共顶点为原点，使尽量多的点落在坐标轴或坐标面上，简化坐标计算；无现成垂直时先证垂直。"},{"id":"sy-g3-c4-l2-e2","type":"essay","level":"简答","stem":"简答：说明向量法求二面角时\"如何确定所求角是法向量夹角还是其补角\"。","ref":"观察二面角是锐角还是钝角（或由图形/法向量方向）：两法向量夹角与二面角相等或互补；可代入一个半平面内的点判断 n·方向向量的符号，或依据图形直观判断取正取负。"}]},{"id":"sy-g3-c4-l3","name":"专题4-3 外接球与几何体计算","chapterId":"sy-g3-c4","chapterName":"立体几何与空间向量","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"半径为 2 的球的表面积为","options":["32π","8π","4π","16π"],"answer":3,"analysis":"S=4πR²=4π×4=16π。","id":"sy-g3-c4-l3-q2"},{"type":"choice","level":"中档","stem":"圆锥底面半径为 3、高为 4，则其侧面积为","options":["24π","9π","12π","15π"],"answer":3,"analysis":"母线 l=√(3²+4²)=5，侧面积 S=πrl=π×3×5=15π。","id":"sy-g3-c4-l3-q4"},{"type":"fill","level":"中档","stem":"长、宽、高分别为 3、4、5 的长方体外接球半径为____","answer":"5√2/2","analysis":"体对角线 √(9+16+25)=5√2，外接球半径为其一半，即 5√2/2。","id":"sy-g3-c4-l3-q1"},{"type":"fill","level":"较难","stem":"底面边长为 2、侧棱长为 2 的正三棱柱，其外接球半径为____","answer":"√21/3","analysis":"底面外接圆半径 r=2/√3，球心到底面距离为棱长的一半 1，故 R²=4/3+1=7/3，R=√21/3。","id":"sy-g3-c4-l3-q3"},{"id":"sy-g3-c4-l3-e1","type":"essay","level":"简答","stem":"简答：总结三类外接球（墙角型、直棱柱型、补形型）的求半径方法。","ref":"墙角型（三条棱两两垂直）：R=√(a²+b²+c²)/2；直棱柱型：R=√(r底²+(h/2)²)；一般补形：补成长方体/正方体，R=体对角线/2。"},{"id":"sy-g3-c4-l3-e2","type":"essay","level":"简答","stem":"简答：说明正四面体棱长为 a 时外接球半径的求法。","ref":"补形成正方体：正四面体棱长 a 对应正方体面对角线，正方体棱长 x=a/√2，R=√3x/2=√6a/4。也可由底面中心到顶点与球心共线的高线方程求解。"}]}]},{"id":"sy-g3-c5","name":"解析几何","book":"二轮专题复习","grade":"高三","lessons":[{"id":"sy-g3-c5-l1","name":"专题5-1 直线与圆","chapterId":"sy-g3-c5","chapterName":"解析几何","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"圆 x²+y²−4x=0 的圆心与半径分别是","options":["(2,0)，2","(−2,0)，2","(0,2)，2","(2,0)，4"],"answer":0,"analysis":"配方得 (x−2)²+y²=4，圆心 (2,0)，半径 2。","id":"sy-g3-c5-l1-q1"},{"type":"choice","level":"中档","stem":"若直线 y=kx+1 与圆 x²+y²=1 相切，则 k=","options":["±1","2","1","0"],"answer":3,"analysis":"圆心到直线距离 d=1/√(k²+1)=1，得 k=0，此时直线 y=1 与圆相切于 (0,1)。","id":"sy-g3-c5-l1-q3"},{"type":"fill","level":"基础","stem":"点 (0,0) 到直线 3x+4y−5=0 的距离为____","answer":"1","analysis":"d=|3×0+4×0−5|/√(9+16)=5/5=1。","id":"sy-g3-c5-l1-q2"},{"type":"fill","level":"中档","stem":"圆 x²+y²=1 与圆 (x−2)²+y²=1 的位置关系是____","answer":"外切","analysis":"圆心距为 2，等于两半径之和 1+1=2，故两圆外切。","id":"sy-g3-c5-l1-q4"},{"id":"sy-g3-c5-l1-e1","type":"essay","level":"简答","stem":"简答：说明圆上点到直线距离的最值求法（几何法）。","ref":"圆心到直线距离 d：圆上点最大距离 d+r，最小距离 |d−r|（点在直线的两侧情形不同）；相切时 d=r 为临界。用几何法先求 d=|Ax₀+By₀+C|/√(A²+B²)。"},{"id":"sy-g3-c5-l1-e2","type":"essay","level":"简答","stem":"简答：说明\"过定点问题\"的处理方法并举直线系例子。","ref":"含参直线方程按参数整理成 A(λ)x+B(λ)y+C(λ)=0 形式，令关于 λ 的系数组为零解出定点。例：(m+1)x+(m−1)y−2m=0 对 m 整理：m(x+y−2)+(x−y)=0，解 x+y−2=0 且 x−y=0，定点 (1,1)。"}]},{"id":"sy-g3-c5-l2","name":"专题5-2 椭圆与双曲线","chapterId":"sy-g3-c5","chapterName":"解析几何","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"椭圆 x²/25+y²/9=1 的焦距为","options":["10","16","8","6"],"answer":2,"analysis":"c²=25−9=16，c=4，焦距 2c=8。","id":"sy-g3-c5-l2-q1"},{"type":"choice","level":"中档","stem":"焦点在 x 轴上、长半轴为 4、离心率为 1/2 的椭圆方程为","options":["x²/16+y²/8=1","x²/16+y²/4=1","x²/4+y²/3=1","x²/16+y²/12=1"],"answer":3,"analysis":"由 e=c/a=1/2、a=4 得 c=2，b²=16−4=12，方程为 x²/16+y²/12=1。","id":"sy-g3-c5-l2-q3"},{"type":"fill","level":"中档","stem":"双曲线 x²/9−y²/16=1 的渐近线方程为____","answer":"y=±(4/3)x","analysis":"令 x²/9−y²/16=0 得 y=±(4/3)x。","id":"sy-g3-c5-l2-q2"},{"type":"fill","level":"基础","stem":"抛物线 y²=8x 的准线方程为____","answer":"x=−2","analysis":"2p=8，p=4，准线 x=−p/2=−2。","id":"sy-g3-c5-l2-q4"},{"id":"sy-g3-c5-l2-e1","type":"essay","level":"简答","stem":"简答：说明椭圆与双曲线中焦点三角形问题的共同处理思路。","ref":"利用定义：|PF₁|±|PF₂|=2a，结合余弦定理列出 |PF₁|·|PF₂| 与焦距的关系，求面积或角度；椭圆用和、双曲线用差，注意绝对值。"},{"id":"sy-g3-c5-l2-e2","type":"essay","level":"简答","stem":"简答：说明求圆锥曲线离心率取值范围的常用列式来源。","ref":"来源：焦点位置与曲线形状限制（如椭圆需 a>b）、点在曲线上、向量数量积条件、角的范围（如 θ∈(0,π/2) 对应余弦为正）、存在性条件，均可化为 a、b、c 的齐次式除以 a² 得 e 范围。"}]},{"id":"sy-g3-c5-l3","name":"专题5-3 焦点弦与最值","chapterId":"sy-g3-c5","chapterName":"解析几何","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"过抛物线 y²=4x 焦点的弦的最小长度为","options":["8","2","4","6"],"answer":2,"analysis":"通径最短，长度为 2p=4。","id":"sy-g3-c5-l3-q1"},{"type":"choice","level":"基础","stem":"椭圆 x²/4+y²=1 的短轴长为","options":["2√3","4","2","1"],"answer":2,"analysis":"b=1，短轴长 2b=2。","id":"sy-g3-c5-l3-q3"},{"type":"fill","level":"中档","stem":"抛物线 y²=4x 上横坐标为 1 的点，到焦点的距离为____","answer":"2","analysis":"准线为 x=−1。横坐标 1 的点到准线的距离为 1−(−1)=2，由抛物线定义，它到焦点的距离也是 2。","id":"sy-g3-c5-l3-q2"},{"type":"fill","level":"中档","stem":"双曲线 x²−y²=1 的离心率为____","answer":"√2","analysis":"a=1，b=1，c=√2，故 e=c/a=√2。","id":"sy-g3-c5-l3-q4"},{"id":"sy-g3-c5-l3-e1","type":"essay","level":"简答","stem":"简答：说明联立直线与圆锥曲线方程后\"设而不求\"的韦达定理应用要点。","ref":"联立消 y 得关于 x 的二次方程 A₂x²+B₂x+C₂=0；由 Δ>0 定参数范围，再用 x₁+x₂、x₁x₂ 表示弦长（|x₁−x₂|=√(Δ)/|A|）或中点、向量条件，避免求交点坐标。"},{"id":"sy-g3-c5-l3-e2","type":"essay","level":"简答","stem":"简答：说明抛物线焦点弦中利用坐标关系的技巧。","ref":"y²=2px 的焦点弦端点 A(x₁,y₁)、B(x₂,y₂)：x₁x₂=p²/4、y₁y₂=−p²；弦长 x₁+x₂+p。先设直线代入抛物线，用上述定值减少运算。"}]}]},{"id":"sy-g3-c6","name":"概率与统计","book":"二轮专题复习","grade":"高三","lessons":[{"id":"sy-g3-c6-l1","name":"专题6-1 古典概型与条件概率","chapterId":"sy-g3-c6","chapterName":"概率与统计","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"掷两枚均匀骰子，点数之和为 7 的概率是","options":["1/12","5/36","1/6","1/9"],"answer":2,"analysis":"基本事件共 36 个，和为 7 的有 6 个，概率 6/36=1/6。","id":"sy-g3-c6-l1-q1"},{"type":"choice","level":"基础","stem":"条件概率公式 P(B|A)=","options":["P(A∪B)/P(A)","P(A)/P(AB)","P(AB)/P(A)","P(A)P(B)"],"answer":2,"analysis":"条件概率定义为 P(B|A)=P(AB)/P(A)，要求 P(A)>0。","id":"sy-g3-c6-l1-q3"},{"type":"fill","level":"中档","stem":"袋中有 5 个白球、3 个黑球，任取 2 个，恰好 1 个黑球的概率为____","answer":"15/28","analysis":"P=C(5,1)C(3,1)/C(8,2)=15/28。","id":"sy-g3-c6-l1-q2"},{"type":"fill","level":"中档","stem":"甲、乙独立射击的命中率分别为 0.8、0.7，至少一人命中的概率为____","answer":"0.94","analysis":"用对立事件：1−0.2×0.3=1−0.06=0.94。","id":"sy-g3-c6-l1-q4"},{"id":"sy-g3-c6-l1-e1","type":"essay","level":"简答","stem":"简答：写出条件概率 P(B|A) 的定义与计算式，并举掷骰子的例子。","ref":"P(B|A)=P(AB)/P(A)，表示事件 A 发生条件下 B 的概率。例：掷骰子，已知出现偶数（A），问出现 2（B）的概率：P(AB)=1/6，P(A)=1/2，P(B|A)=1/3。"},{"id":"sy-g3-c6-l1-e2","type":"essay","level":"简答","stem":"简答：说明全概率公式与贝叶斯公式的使用场景差别。","ref":"全概率公式：由各\"原因\"概率求\"结果\"总概率（正向）；贝叶斯公式：结果发生后反推某个原因的概率（逆向，如检测呈阳性时真患病的概率）。"}]},{"id":"sy-g3-c6-l2","name":"专题6-2 分布列与期望","chapterId":"sy-g3-c6","chapterName":"概率与统计","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"中档","stem":"若 X~B(4,0.5)，则 E(X) 与 D(X) 分别为","options":["1 和 2","2 和 2","4 和 1","2 和 1"],"answer":3,"analysis":"E(X)=np=2，D(X)=np(1−p)=4×0.5×0.5=1。","id":"sy-g3-c6-l2-q1"},{"type":"choice","level":"中档","stem":"设随机变量 X 服从二项分布 B(n,p)，则其方差 D(X)=","options":["np(1−p)","p(1−p)","np","n²p"],"answer":0,"analysis":"二项分布的方差为 np(1−p)，标准差为 √(np(1−p))。","id":"sy-g3-c6-l2-q3"},{"type":"fill","level":"基础","stem":"随机变量 X 只取 0、1，且 P(X=1)=0.3，则 E(X)=____","answer":"0.3","analysis":"E(X)=0×0.7+1×0.3=0.3。","id":"sy-g3-c6-l2-q2"},{"type":"fill","level":"中档","stem":"若 X~N(0,1)，则 P(|X|<2) 约为____（保留三位小数）","answer":"0.954","analysis":"标准正态分布下，±2σ 区间概率约为 0.9545，取三位小数为 0.954。","id":"sy-g3-c6-l2-q4"},{"id":"sy-g3-c6-l2-e1","type":"essay","level":"简答","stem":"简答：说明求离散型随机变量期望方差的一般流程。","ref":"确定 X 的所有取值→逐个求概率（注意独立性、互斥性）→列分布列并验证 Σ=1→计算 E(X)=Σxᵢpᵢ→D(X)=Σ(xᵢ−E)²pᵢ 或用公式。"},{"id":"sy-g3-c6-l2-e2","type":"essay","level":"简答","stem":"简答：说明二项分布、超几何分布的判别差别。","ref":"二项分布：每次试验独立、p 不变（有放回或独立重复）；超几何分布：不放回抽样、概率随抽取变化（P(X=k)=C_MᵏC_{N−M}^{n−k}/C_Nⁿ）。区分关键：是否放回。"}]},{"id":"sy-g3-c6-l3","name":"专题6-3 统计案例与回归","chapterId":"sy-g3-c6","chapterName":"概率与统计","book":"二轮专题复习","grade":"高三","video":"","seconds":1800,"quiz":[{"type":"choice","level":"基础","stem":"线性回归直线一定经过","options":["(x̄,0)","坐标原点","样本中心点 (x̄,ȳ)","(0,ȳ)"],"answer":2,"analysis":"由最小二乘法正规方程可得回归直线必过样本中心点。","id":"sy-g3-c6-l3-q1"},{"type":"choice","level":"中档","stem":"独立性检验中，K² 的观测值越大，说明","options":["两变量一定无关","样本容量越小","认为两变量有关的把握越大","两变量一定有关"],"answer":2,"analysis":"K² 越大，对应临界值下的显著性水平越低，否定“无关”的把握越大。","id":"sy-g3-c6-l3-q3"},{"type":"fill","level":"中档","stem":"若样本相关系数 r=0.98，说明两个变量之间存在较强的____相关","answer":"正","analysis":"r>0 为正相关，|r| 越接近 1 线性相关越强。","id":"sy-g3-c6-l3-q2"},{"type":"fill","level":"中档","stem":"一组数据的方差为 2，将每个数据都加 1 后，新数据的方差为____","answer":"2","analysis":"方差不受整体平移影响，加常数后方差不变。","id":"sy-g3-c6-l3-q4"},{"id":"sy-g3-c6-l3-e1","type":"essay","level":"简答","stem":"简答：说明回归分析中\"残差\"的作用与残差图的判读。","ref":"残差=观测值−预测值，反映模型拟合好坏；残差图点随机均匀分布在横轴附近说明模型合适，出现系统性弯曲说明应换模型（如非线性）。R² 越接近 1 拟合越好。"},{"id":"sy-g3-c6-l3-e2","type":"essay","level":"简答","stem":"简答：说明独立性检验的完整步骤及结论的规范表述。","ref":"步骤：列 2×2 列联表→计算 χ²→与临界值比较→下结论。规范表述：\"在犯错误的概率不超过 α 的前提下，认为 A 与 B 有关\"，不能说\"一定有关\"或给出因果结论。"}]}]}]},"count":{"高一":27,"高二":22,"高三一轮":49,"高三二轮":18},"builtAt":"2026-11-11T01:40:48.979Z"};
